/* paper-picker: the course data of the module's test and of its CI course (ci/oncourse.js).
 *
 * Basic-Pharmacokinetics' own data, read from a read-only copy at ac2eb73, with nothing
 * written for the test:
 *   exams       src/course.js `exams`, all three, every field as the course has it
 *   activeExam  src/course.js `activeExam` (3)
 *   lectures    src/course.js `lectures`, all twelve (the exams' pools name modules 1-9)
 *   skills      the src/course.js `skills` entries the questions below use
 *   topics      the TOPICS entries (src/q1_module1.js and the files that push to it) the
 *               questions below belong to
 *   qs          118 of its questions (src/q*.js, in the order its build.py reads them),
 *               every field as the course has it
 *   images      the 9 src/images.json entries those questions show
 * Which questions (the rule only chooses; no question is changed). A question can be taken
 * when it has no `type` (a single-answer or select-all question; these exams have no
 * `typed`, so their papers carry only these), is not `lowYield`, does not name the
 * professor in its text, passes the core's rules for a question (style_check.js STEM_RE; a
 * stem that promises a figure shows one, browser_test.js; its cite names a lecture deck, at
 * least 3 options and a select-all at least 4 with a distractor, test.js; no word
 * "undefined", "null" or "NaN", browser_test.js and nullexam_test.js), and its `dupOf`
 * chain, if any, can be taken too. Every such question without an image is taken; one with
 * an image only while a pool of Exam 3 or Exam 2 has fewer question families than its
 * marks, smallest image first. Exam 1's Module 2 pool cannot be filled from such questions,
 * so a paper for Exam 1 cannot be drawn here, as the drill then says. The script that made
 * this file is kept with the review evidence (branch evidence/paper-picker).
 * The one change to the data: `prof` is left out here, and courseData(prof) writes the
 * course's own first professor (the kit template's "Professor") into every question, topic
 * and lecture, so the kit holds no personal name. In the course, the lectures' ids carry
 * the prefix `pp-` (pp-L01 ... pp-L12), because the kit template already has a lecture L01;
 * the questions' own `lecture` field is kept as the course has it (the kit does not read it).
 * courseData(prof) returns the question file (one question per line, opening {id:'...', in
 * the kit's question-file form, which core browser_test.js counts) and the course.js line.
 */
const PK = {"qs":[{"id":"m1-int-01","tier":"new","exam":1,"module":1,"lecture":"L01","topic":"intro","sub":"disc","concept":"biopharmaceutics-defn","skill":"recall","source":"both","stem":"Which term covers the interrelationship of the physicochemical properties of a drug, the dosage form in which it is given, and the route of administration on the rate and extent of systemic drug absorption?","options":[{"t":"Biopharmaceutics","correct":true,"why":"This is her definition of biopharmaceutics: drug properties, dosage form and route, acting on the rate and extent of systemic absorption. Biopharmaceutics stops where the drug enters the circulation, which is where pharmacokinetics starts."},{"t":"Toxicology","correct":false,"why":"Clinical toxicology studies the adverse effects of drugs in the body: what a drug does once present, not how much gets in. Choosing it usually comes from reading \"extent\" as extent of injury rather than extent of absorption."},{"t":"Pharmacodynamics","correct":false,"why":"Choosing this confuses absorption with response. Pharmacodynamics relates drug concentration at the site of action to pharmacological response, so its two variables are concentration and effect. The definition names dosage form and route, which are formulation variables, and never a response."},{"t":"Pharmacology","correct":false,"why":"Pharmacology is the broader study of drug action, and picking it means answering at the level of the whole field rather than the specific discipline named. The definition is narrow and formulation-centred, so a general term cannot be the best match."}],"teach":[{"h":"The idea","list":["Each related discipline is defined by the two quantities it links.","Biopharmaceutics links the drug, the dosage form and the route to the rate and extent of absorption; drug-product design factors such as particle size and excipients fall within it.","Pharmacokinetics links concentration to time; pharmacodynamics links concentration to response.","Clinical toxicology deals with the adverse effects of drugs.","Rate of absorption shows in how early and how high the curve peaks (tmax and Cmax); extent is how much arrives, measured by the area under the curve (AUC)."]},{"h":"Where to read more","t":"Introduction.pdf, slide \"Related Discipline: Biopharmaceutics\"."}],"teachImg":"slide_Introduction_p6","cite":"Introduction.pdf slide 6, and the poll slide following slide 10","quote":"The interrelationship of the physicochemical drug properties, dosage form and route of administration on the rate and extent of systemic drug absorption"},{"id":"m1-ord-c01","tier":"new","exam":1,"module":1,"lecture":"L01","topic":"orders","sub":"zero","concept":"zero-order-defn","skill":"recall","source":"slide","stem":"In a zero-order reaction, the amount or concentration of drug decreases:","options":[{"t":"At a constant rate","correct":true,"why":"The differential form is {{frac:dC|dt}} = −k with no concentration term on the right, so the rate does not depend on how much drug is present. The same quantity leaves in each unit of time whether the concentration is high or low; integrating gives the straight line C = C0 − kt."},{"t":"At a rate proportional to the amount remaining","correct":false,"why":"That statement is the definition of a first-order reaction, where {{frac:dC|dt}} = −kC and the concentration appears on the right-hand side. The two definitions differ by exactly that one term. Selecting this means matching on the word rate without checking what the rate is tied to."},{"t":"By a constant fraction of the amount remaining per unit time","correct":false,"why":"A constant fraction per unit time is the first-order behaviour restated in words rather than symbols. For a zero-order process the fraction lost per hour grows as the concentration falls, because the quantity removed stays fixed while the amount present shrinks. Fraction and quantity are what separate the two orders."},{"t":"At a rate proportional to the square of the amount remaining","correct":false,"why":"A rate proportional to concentration squared would be second order, which is two steps away from the definition asked for. The exponent on the concentration term is what names the order, and zero order means that exponent is zero, so the term disappears entirely."}],"teach":[{"h":"The idea","list":["The order of a reaction is the power to which the concentration is raised in the rate law.","Zero order: the power is zero, so the concentration drops out: {{frac:dC|dt}} = −k, which integrates to C = C0 − kt.","C0 is the concentration at time zero; k carries units of concentration or amount per unit time.","On linear axes the line has slope −k; k itself is written as a positive number, the size of the loss per unit time.","Half-life: t½ = {{frac:C0|2k}}, so it changes with the starting concentration."]},{"h":"Where to read more","t":"Introduction.pdf, slide 17."}],"teachImg":"slide_Introduction_p20","cite":"Introduction.pdf slide 17","quote":"Amount or concentration of drug decreases at a constant rate"},{"id":"m1-ord-c03","tier":"new","exam":1,"module":1,"lecture":"L01","topic":"orders","sub":"first","concept":"first-order-properties","skill":"recall","source":"both","stem":"First-order processes are characterised by:","options":[{"t":"A constant half-life","correct":true,"why":"First-order half-life is 0.693 divided by the rate constant, and both are constants, so the half-life is constant and does not depend on the starting concentration. That is why a drug can be quoted with one half-life rather than a value for every dose."},{"t":"A constant rate of elimination","correct":false,"why":"Picking this holds on to the word constant and loses what it attaches to. The rate of elimination is the rate constant multiplied by the concentration, so it changes continuously as the concentration falls; a constant rate of elimination is the zero-order property."},{"t":"dC/dt = −k","correct":false,"why":"Choosing this treats the rate law as a shape to match rather than an equation to read for its concentration term. {{frac:dC|dt}} = −k has no concentration on the right-hand side, which makes it zero order. The first-order form is {{frac:dC|dt}} = −kC."},{"t":"Units of k of concentration or amount per unit time","correct":false,"why":"Choosing this gives the zero-order units. Concentration or amount per unit time are the units of a zero-order constant, which is itself a rate. A first-order constant multiplies a concentration to give a rate, so its units are reciprocal time."}],"teach":[{"h":"The idea","list":["Every first-order property follows from one fact: the rate is proportional to the concentration, {{frac:dC|dt}} = −kC.","The proportion removed per unit time is fixed, so the rate constant k has units of reciprocal time.","The half-life is fixed at {{frac:0.693|k}}; 0.693 is ln 2, because setting C = {{frac:C0|2}} in ln C = ln C0 − kt leaves k × t½ = ln 2.","The quantity removed per unit time is not fixed, so the rate of elimination falls as the concentration falls."]}],"teachImg":"slide_Introduction_p24","cite":"Introduction.pdf, poll slide following slide 21","quote":"first order processes, constant half-life, constant half-life, OK. The rate of elimination … the rate is constantly changing"},{"id":"m1-ord-c04","tier":"new","exam":1,"module":1,"lecture":"L01","topic":"orders","sub":"first","concept":"first-order-rate-depends","skill":"tell","source":"both","stem":"Which of the following best describes the rate of a first-order process?","options":[{"t":"It is proportional to the concentration of drug present","correct":true,"why":"The rate law {{frac:dC|dt}} = −kC puts the concentration on the right-hand side, so the rate cannot be independent of it: faster at high concentration, slower as it falls. What is independent of concentration is the rate constant, and so the half-life."},{"t":"It is independent of the concentration of drug present","why":"This swaps the rate constant for the rate. The constant is a fixed number in reciprocal time, but the rate is that constant times the concentration, so it changes whenever the concentration changes."},{"t":"It is constant over time","why":"Picking this reads the constant half-life of a first-order process as a constant rate. A rate that stays the same over time, the same quantity lost per unit time, is the zero-order case. In first order the rate is k times the concentration and falls with it; only k and the half-life stay fixed."},{"t":"It is set by the half-life alone","why":"This answer confuses the time to lose a fixed proportion with the quantity lost per unit time. A constant half-life is a real first-order property, but half of a large concentration is more drug than half of a small one over the same interval, so the rate changes while the half-life does not."}],"teach":[{"h":"The idea","list":["In a first-order process the rate and the rate constant behave differently as the concentration falls.","The rate constant k is fixed: the proportion of what is present that is removed per unit time.","The rate is k multiplied by the current concentration, so it is largest at the start and falls continuously.","A k of 0.04 hr⁻¹ removes the same fraction every hour, about 4% (1 − e^(−0.04) = 0.039), whatever the concentration.","In a zero-order process this reverses: the rate is fixed, and the proportion removed per unit time grows."]}],"teachImg":"slide_Introduction_p24","cite":"Introduction.pdf, poll slide following slide 21","quote":"the rate depends on the concentration that’s there"},{"id":"inf-c9","tier":"new","exam":1,"module":3,"lecture":"L04","topic":"infusion","sub":"stop","concept":"post-cessation-model","skill":"recall","source":"both","stem":"Which of the following best describes the plasma concentration after a continuous intravenous infusion is stopped?","options":[{"t":"It declines by first-order elimination from the concentration at cessation","correct":true,"why":"With no input, only first-order elimination remains: the same decay seen after a bolus. The concentration at cessation plays the part of the initial concentration, and t is counted from cessation rather than from the start; getting that peak value right is the main work."},{"t":"It continues to rise toward the steady-state concentration","why":"Picking this reads a stopped infusion as one that is still running. The rise toward Css, the steady-state concentration, is driven by the input rate R; once R is zero nothing drives it, and only first-order elimination, with rate constant k, remains. The concentration can only fall from its value at cessation."},{"t":"It declines from the steady-state concentration in every case","why":"This answer treats every infusion as having reached its plateau before it stopped. The decline starts from Cpeak, the concentration at cessation, which equals Css only after about three to five half-lives of infusion; one stopped earlier decays from ({{frac:R|Cl}})(1 − e^(−kT)), where T is the infusion length and Cl clearance."},{"t":"It stays at the concentration reached at cessation","why":"Picking this reads the end of input as the end of all change. Elimination does not stop when the pump does: the first-order output, k times the amount in the body, continues whatever the input, so the concentration falls from the moment the infusion ends. A flat level would need input to keep matching output."}],"teach":[{"h":"The idea","list":["Stopping an infusion removes the zero-order input and leaves the first-order output unchanged.","From that point the curve is an ordinary first-order decay, C = Cpeak·e^(−kt), with t counted from cessation.","Cpeak, the concentration when the infusion stopped, is Css if the infusion ran to steady state, and ({{frac:R|Cl}})(1 − e^(−kT)) if it stopped earlier, T being the infusion length.","So every post-cessation problem has two steps: find Cpeak, then decay it for the stated time."]},{"h":"Where to read more","t":"3IntravenousInfusions.pdf, slide \"Drug Concentration after an IV Infusion has Ended\"."}],"cite":"3IntravenousInfusions.pdf, slide \"Drug Concentration after an IV Infusion has Ended\"","quote":"Think of that C peak as your C0 as your starting point."},{"id":"inf-c10","tier":"new","exam":1,"module":3,"lecture":"L04","topic":"infusion","sub":"stop","concept":"peak-vs-css","skill":"tell","source":"both","stem":"Two patients receive the same drug at the same infusion rate. One infusion runs to steady state and the other is stopped after two half-lives. In calculating the concentration some hours after each infusion ends, how do the two differ?","options":[{"t":"The second decays from 75% of the plateau","correct":true,"why":"Two half-lives of infusion close three quarters of the gap to the plateau, so the concentration at cessation is 0.75 times Css rather than Css itself. That value is the starting point for the decay, and everything after it is identical between the two patients."},{"t":"The second decays with a larger rate constant","correct":false,"why":"The elimination rate constant belongs to the drug in the patient and does not depend on how long the infusion ran. Both curves fall at the same fractional rate once the infusion stops. Selecting this attributes a difference in starting height to a difference in slope."},{"t":"The second has a lower steady-state concentration","correct":false,"why":"Steady-state concentration is the infusion rate divided by clearance, and both patients have the same rate and the same drug, so both have the same Css. The second patient simply never got there. Confusing the plateau a regimen would reach with the level it actually reached is the specific error here."},{"t":"Both decay from the steady-state concentration","correct":false,"why":"This answer treats every post-infusion decay as starting from the plateau. Only an infusion run to steady state peaks at Css, the steady-state concentration; two half-lives of infusion leave the concentration at 0.75 Css, a quarter short. Starting the second decay from Css overestimates that patient at every later time, by the same factor throughout."}],"teach":[{"h":"The idea","list":["After cessation both patients follow the same first-order decay with the same k, so only the starting concentration can differ.","An infusion run to steady state starts its decay at Css (the steady-state concentration).","An infusion stopped earlier starts from Css × (1 − e^(−kT)), with T the duration actually infused.","Deciding which of the two applies is the first step in any post-cessation question."]}],"cite":"IV-Infusions-Practice-3---Solutions.pdf, parts f and g; 3IntravenousInfusions.pdf, slide \"Drug Concentration after an IV Infusion has Ended\"","quote":"Css or not Css"},{"id":"inf-c11","tier":"new","exam":1,"module":3,"lecture":"L04","topic":"infusion","sub":"load","concept":"loading-purpose","skill":"recall","source":"both","stem":"What is the purpose of giving an intravenous loading dose at the start of a continuous infusion?","options":[{"t":"To reach the target steady-state concentration almost immediately","correct":true,"why":"Without a loading dose the concentration has to climb over three to five half-lives, which is unacceptable for a drug that is needed now. A bolus of the amount present at steady state reaches that level at once, and the infusion then holds it. The loading dose saves time; it does not raise the level."},{"t":"To raise the steady-state concentration above what the infusion alone would give","correct":false,"why":"The plateau is set by infusion rate and clearance, and a single bolus changes neither; the bolus is eliminated like the infused drug and adds nothing to the rate coming in. Choosing this treats the loading dose as extra drug that stays, when it only saves the time spent climbing to the plateau."},{"t":"To shorten the elimination half-life so that steady state arrives sooner","correct":false,"why":"Half-life is a property of the drug and the patient and no dose changes it. The loading dose does not make the approach to the plateau faster; it starts the patient at the plateau so that no approach is needed. Confusing those two is the reason this option is tempting."},{"t":"To allow a lower infusion rate to be used for the same effect","correct":false,"why":"The maintenance rate is fixed by the target concentration and the clearance; lowering it would let the level fall away from the target once the loading dose is eliminated. Picking this treats the total drug given, rather than the rate, as what matters."}],"teach":[{"h":"The idea","list":["A loading dose and an infusion rate answer two separate questions.","The rate sets where the concentration settles, because the plateau is the rate divided by clearance.","The loading dose sets how soon it gets there, by putting the steady-state amount into the body at once.","So DL (loading dose) = Css × VD, the steady-state concentration times the volume of distribution; equivalently {{frac:R|k}}, once R has been chosen for that target."]},{"h":"Where to read more","t":"3IntravenousInfusions.pdf, slide \"IV Bolus Loading Dose and Continuous IV Infusion\"."}],"cite":"3IntravenousInfusions.pdf, slide \"IV Bolus Loading Dose and Continuous IV Infusion\"","quote":"We want the loading dose to look like the amount of drug that’s in the body at steady state."},{"id":"inf-c12","tier":"new","exam":1,"module":3,"lecture":"L04","multi":true,"topic":"infusion","sub":"load","concept":"loading-dose-properties","skill":"apply","source":"both","stem":"Which of the following is true about a loading dose given at the same time as a continuous infusion is started? Select all that apply.","options":[{"t":"An appropriate loading dose can be calculated as R divided by k","correct":true,"why":"Infusion rate divided by elimination rate constant is the amount the infusion would eventually hold in the body at steady state. It is right provided the rate was chosen to hit the intended concentration; an arbitrary rate gives a loading dose matched to that arbitrary plateau instead of the target."},{"t":"An appropriate loading dose is Css multiplied by the volume of distribution","correct":true,"why":"Volume of distribution relates the amount in the body to the plasma concentration, so target concentration times volume gives the amount needed to produce that concentration. This route starts from the target rather than the rate, and it agrees with {{frac:R|k}} when the rate matches the target."},{"t":"The steady-state concentration is unchanged by the loading dose","correct":true,"why":"The plateau is the infusion rate divided by clearance, and a single bolus alters neither. The loading dose changes only the early part of the curve, and the bolus component decays away as the infusion component builds. Her practice problem asks for the steady-state concentration twice, with different loading doses, and the answer is unchanged."},{"t":"The loading dose shortens the elimination half-life","correct":false,"why":"Picking this reads the loading dose as something that acts on the drug rather than on the amount present. Half-life is 0.693 divided by k, the elimination rate constant, and k is a constant of the drug in the patient that no dose changes. A loading dose changes only how soon the target is reached."},{"t":"The loading dose must be recalculated whenever the half-life changes","correct":false,"why":"Choosing this confuses the loading dose with the maintenance rate. The loading dose fills the volume of distribution to the target, so it depends on Css and VD, not on clearance. In her renal failure example clearance and the maintenance rate fall, but the loading dose stays the same."}],"teach":[{"h":"The idea","list":["The loading dose brings the body to the target concentration; the infusion replaces what is eliminated.","DL = Css × VD, or {{frac:R|k}} when the rate already matches the target (Css the steady-state concentration, VD the volume of distribution, R the infusion rate, k the elimination rate constant).","The plateau depends on rate and clearance, so the loading dose does not alter it."]}],"cite":"3IntravenousInfusions.pdf, slide \"IV Bolus Loading Dose and Continuous IV Infusion\"; IV-Infusions-Practice-4-Solutions.pdf part g","quote":"another way to think about this loading dose. Concentration of drug in the body at steady-state times the volume and distribution"},{"id":"inf-c13","tier":"new","exam":1,"module":3,"lecture":"L04","topic":"infusion","sub":"load","concept":"loading-dose-mismatch","skill":"apply","source":"transcript","stem":"A drug is infused at a rate that gives a steady-state concentration of 24 mg/L, and the loading dose given with it is larger than the amount of drug the body holds at steady state. What does the concentration-time curve look like?","options":[{"t":"It starts above 24 mg/L and falls toward it","correct":true,"why":"The concentration is the decaying bolus curve plus the rising infusion curve; too much drug at once puts the sum above the plateau early, and it falls back as the bolus decays. With her 288 mg loading dose the two-hour concentration is 24 mg/L; 388 mg puts it near 30 mg/L, above the plateau."},{"t":"It starts below 24 mg/L and climbs to it","correct":false,"why":"That is the picture for a loading dose that is too small, where the bolus does not fill the volume of distribution to the target and the infusion has to make up the difference. Starting low is what a loading dose is given to avoid. Selecting this reverses the direction of the mismatch."},{"t":"It rises steadily to a plateau above 24 mg/L","correct":false,"why":"The plateau is the infusion rate divided by clearance and a bolus cannot move it, so no loading dose produces a higher final level. The excess from an oversized bolus is eliminated like any other drug. This answer lets the loading dose set the steady-state concentration."},{"t":"It stays flat at 24 mg/L from the first minute","correct":false,"why":"That is what an appropriate loading dose achieves, and the stem states this one is larger than the steady-state amount. A flat line is the sum of a decaying and a rising curve only when the bolus exactly fills the volume of distribution to Css. Choosing this ignores the condition set in the stem."}],"teach":[{"h":"The idea","list":["With a loading dose and an infusion together, the concentration at any moment is the sum of two curves: C = ({{frac:DL|VD}})e^(−kt) + ({{frac:R|Cl}})(1 − e^(−kt)).","The first term is a bolus decaying from the loading dose divided by the volume of distribution; the second is the infusion climbing toward Css (the steady-state concentration).","When the loading dose equals Css times the volume of distribution, the two sum to a flat line at Css.","Too much loading dose makes the early sum overshoot and fall back; too little makes it start low and climb."]}],"cite":"09-02 lecture (transcript); 3IntravenousInfusions.pdf, slide \"IV Bolus Loading Dose and Continuous IV Infusion\"","quote":"the loading dose helps us to reach that steady state concentration, like almost immediately. But you got to choose wisely on the loading dose","note":"In class she reworked the 288 mg example with a 388 mg loading dose: the level two hours in was about 30 mg/L, against a plateau of 24 mg/L.","audit":"The slide carries only a graph of the too-high and too-low cases with no printed caption, so the described behaviour is taken from the 09-02 transcript, where she recomputes her 288 mg example with 388 mg and gets about 30 mg/L at two hours against a plateau of 24 mg/L."},{"id":"inf-c16","tier":"new","exam":1,"module":3,"lecture":"L04","topic":"infusion","sub":"basics","concept":"bolus-dose-dependence","skill":"apply","source":"slide","stem":"Which of the following would you expect to increase with an increase in an intravenous bolus dose?","options":[{"t":"Plasma drug concentration","correct":true,"why":"Concentration is the amount in the body divided by the volume of distribution, so in a fixed volume a larger dose gives a proportionally larger concentration. Doubling the dose doubles the initial concentration and leaves the shape of the curve unchanged."},{"t":"Clearance","correct":false,"why":"Clearance is the elimination rate constant times the volume of distribution, both constant for the drug in the patient. A larger dose means more drug removed per hour but the same volume of plasma cleared per hour; confusing the rate of elimination with clearance makes this look right."},{"t":"Elimination half-life","correct":false,"why":"Picking this reads a larger amount as taking proportionally longer to remove, which describes zero-order elimination. Half-life is 0.693 divided by k, the elimination rate constant, and neither term contains the dose. In first-order elimination, losing half takes the same time from a high or a low start; a bigger dose keeps the same half-life."},{"t":"Apparent volume of distribution","correct":false,"why":"Picking this treats volume of distribution as a container that stretches with the dose. It is a proportionality constant describing how the drug distributes between plasma and the rest of the body; it belongs to the drug, not the dose. Giving more drug fills the same apparent volume to a higher concentration."}],"teach":[{"h":"The idea","list":["In a linear first-order system the dose scales the concentrations and changes nothing else.","C0 = {{frac:D0|VD}}, so doubling the dose doubles C0 and every later concentration with it.","t½ = {{frac:0.693|k}} and Cl = k × VD contain no dose, so neither moves when the dose does; VD is a constant of the drug in that patient.","The amount eliminated per hour, Cl × Cp, does rise with the dose; the volume cleared per hour, Cl, does not."]},{"h":"How she tests it","t":"The opening poll of the infusion deck asks this question in these words."}],"cite":"3IntravenousInfusions.pdf, opening poll slide","quote":"Which of the following would you expect to increase with an increase in IV bolus dose?"},{"id":"m5-c06","tier":"new","exam":2,"module":5,"lecture":"L06","topic":"oral","sub":"extravasc","concept":"modified-release-input","skill":"apply","source":"transcript","stem":"A solid oral dosage form is formulated to release its drug at a constant rate. How is that product's input and output described?","options":[{"t":"Zero-order input with first-order output","correct":true,"why":"A constant release rate is a fixed amount per hour, which is zero order. Elimination does not depend on the product, so it stays first order. The result looks like an IV infusion: the level climbs and levels off rather than peaking."},{"t":"First-order input with first-order output","why":"This is the ordinary tablet, and choosing it misses what the product was built to change. Its release slows as less drug is left in it, which is what first order means. A constant-rate product is built so that release does not slow, which makes its input zero order."},{"t":"Zero-order input with zero-order output","why":"The input half is right and the output half is not. The product controls only release. Once drug is in the plasma the body removes a fixed fraction of it each hour, which is first order, whatever the tablet did."},{"t":"Instantaneous input with first-order output","why":"Instantaneous input is an IV bolus, where the whole dose enters at once. A product that releases drug steadily over hours is the opposite: its input is spread over time at a constant rate."}],"teach":[{"h":"The output is first order, whatever the product","list":["In this module elimination is first order: each hour the body removes a fixed fraction of the drug in it.","A formulation controls only how the drug is released, not how the body removes drug already in the plasma."]},{"h":"The input is set by how the drug is released","t":"IV means intravenous.","table":{"head":["How drug enters","Input","Example","Curve"],"rows":[["All at once","Instantaneous","IV bolus","Highest at time zero, then falls"],["A fixed fraction of what is left, each hour","First order","Ordinary tablet or capsule","Rises to a peak, then falls"],["A fixed amount each hour","Zero order","IV infusion; constant-rate release product","Levels off while release continues, then falls"]]},"fig":"input_types","after":"A constant-rate product releases the same amount each hour, however much is left in the tablet. That is a zero-order input."}],"cite":"5---Pharmacokinetics-of-Oral-Absorption.pdf, slide \"Summary\"; 09.21 lecture","quote":"if we have a truly modified zero solid dosage form that is releasing drug at a zero order rate … Looks like IV infusion"},{"id":"m5-c07","tier":"new","exam":2,"module":5,"lecture":"L06","topic":"oral","sub":"conc","concept":"f-meaning","skill":"recall","source":"both","stem":"In the single oral dose equation, what does the factor F represent?","options":[{"t":"The fraction of the dose absorbed and available to the body","correct":true,"why":"Some of a swallowed dose never reaches the systemic circulation: it is not absorbed, or the liver removes it on the way through. F is the share of the dose that survives, so dose × F is what the body has to work with; for an intravenous dose F is taken as one."},{"t":"The fraction of the drug bound to plasma protein","correct":false,"why":"This reads F as a fraction of drug rather than of dose. The bound fraction describes drug already in the plasma; F decides how much got there, and because F multiplies the dose, raising it raises every concentration. No binding term appears in the single oral dose equation."},{"t":"The fraction of the dose excreted unchanged in the urine","correct":false,"why":"That fraction describes elimination and belongs in clearance calculations, not in the input term. If F were an excreted fraction, raising it would lower the plasma concentration, the opposite of how F behaves; the two are easy to swap because both are fractions of a dose."},{"t":"The fraction of the absorption rate constant contributed by dissolution","correct":false,"why":"There is no such split in this model; the whole absorption process is compressed into the single constant ka. F is a fraction of the dose and is not part of any rate. Reaching for this answer means trying to attach F to the neighbouring ka rather than to the dose."}],"teach":[{"h":"The idea","list":["F is the oral bioavailability factor: the proportion of a given dose that reaches the systemic circulation, between 0 and 1.","It appears only as a multiplier of the dose in Cp = {{frac:F ka D0|VD(ka - k)}} (e^(-kt) - e^(-ka t)), so its effect is the same as giving a smaller dose completely.","The peak and the area under the curve scale with F; the timing of the peak does not.","A capital F in an equation is itself the signal that the route is oral.","Her slide \"Concentration of Drug in Plasma Following a Single Oral Dose\" prints the equation with every symbol labelled."]}],"cite":"5---Pharmacokinetics-of-Oral-Absorption.pdf, slide \"Concentration of Drug in Plasma Following a Single Oral Dose\"; 09.21 lecture","quote":"what fraction of this oral dose do we expect to be absorbed by the body and available for the body to use, right? When we give a drug IV, then that F is assumed to be one."},{"id":"m5-c20","tier":"new","exam":2,"module":5,"lecture":"L06","topic":"oral","sub":"peak","concept":"significance-of-params","skill":"recall","source":"slide","stem":"Which of the following is a use of the absorption rate constant, the time to peak and the maximum concentration?","options":[{"t":"assessing the onset of action","correct":true,"why":"Onset is the time at which the concentration first reaches a therapeutic level, so it is governed by how quickly the rising limb climbs. A product with a larger absorption rate constant reaches that level sooner. This is a direct clinical consequence of the input kinetics."},{"t":"estimating the glomerular filtration rate","why":"Filtration is a renal elimination process and is estimated from creatinine clearance, which has nothing to do with how fast an oral dose is absorbed. None of these three parameters carries information about the kidney. Selecting it imports a quantity from the elimination and clearance material into a list about input."},{"t":"deciding whether elimination is zero order or first order","why":"Picking this treats the absorption parameters as reporting on the output side. The order of elimination is judged from the shape of the terminal decline, which is governed by k, not by ka, the time to peak or the peak."},{"t":"calculating the total body clearance","why":"Picking this takes the input parameters for the output side. Clearance (Cl) is found from the dose and the area under the curve, or as k × VD, the elimination rate constant times the volume of distribution. ka, tmax and Cmax describe how fast the drug arrives, not how fast the body removes it."}],"teach":[{"h":"What they are used for","t":"Her slide \"Significance of Absorption Rate Constants, tmax, and Cmax\" lists five uses of ka (the absorption rate constant), tmax (the time to peak) and Cmax (the peak concentration):","list":["predicting peaks and troughs in repeated dosing;","comparing products for bioequivalence;","choosing a route and a dosage form;","assessing onset of action, the time at which the concentration first reaches an effective level;","relating the concentration to the pharmacological effect."],"after":"Every use is about input and its consequences, not about elimination."}],"cite":"5---Pharmacokinetics-of-Oral-Absorption.pdf, slide \"Significance of Absorption Rate Constants, tmax, and Cmax\"","quote":"Bioequivalence studies – comparing rates of absorption from chemically equivalent products"},{"id":"m6-c19","tier":"new","exam":2,"module":6,"lecture":"L07","topic":"multi","sub":"ndose","concept":"n-large","skill":"read","source":"both","stem":"In the equation for Cp after n doses, what happens to the term (1 − e^(-nkτ)) as n becomes very large?","options":[{"t":"It approaches 1","correct":true,"why":"e^(-nkτ) shrinks towards 0 as n grows, so 1 minus it approaches 1. The equation then becomes Cp = ({{frac:D0|VD}})[{{frac:1|1 − e^(-kτ)}}]e^(-kt), which is the steady-state equation."},{"t":"It approaches 0","why":"This has the exponential and the whole term the wrong way round. It is e^(-nkτ) that approaches 0; one minus a vanishing number approaches 1."},{"t":"It grows without limit","why":"Choosing this confuses the growing dose number with a growing term. The term is 1 minus a positive fraction, so it can never exceed 1. That limit is why the concentration levels off at a plateau instead of rising forever."},{"t":"It equals the accumulation factor","why":"Choosing this confuses the n term with the accumulation factor, which is {{frac:1|1 − e^(-kτ)}}, with τ and not nτ. The n term approaches 1 and drops out, leaving the accumulation factor behind."}],"teach":[{"t":"The n-dose equation and the steady-state equation are the same equation. Steady state is the limit reached when the dose number is large."},{"h":"After n doses: what each letter is","t":"Cp = {{frac:D0|VD}} ({{frac:1 - e^(-nkτ)|1 - e^(-kτ)}}) e^(-kt). Her Example 2 asks for the level 3 hours after the 2nd dose of 10 mg/kg every 8 hours, with t½ 4 hours and VD 25% of body weight; the right-hand column reads each letter from that problem.","table":{"head":["Symbol","What it is","Example 2"],"rows":[["{{frac:D0|VD}} = C0","The concentration one dose adds at the moment it goes in","{{frac:10 mg/kg|0.25 L/kg}} = 40 mg/L"],["n","How many doses have been given so far, counting the one just given. Her slide labels it \"# of doses\"","2, the 2nd dose"],["t","Hours since the most recent dose, dose n. It runs from 0 to τ and is never counted from the first dose","3 hr"],["τ","Hours between doses","8 hr"],["k","The elimination rate constant, {{frac:0.693|t½}}","{{frac:0.693|4 hr}} = 0.1733 hr⁻¹"],["e^(-kτ)","The fraction of a dose still in the body one interval after it went in. The textbook calls it f","0.25, because 8 hours is two half-lives: 1 → 0.5 → 0.25"],["e^(-nkτ)","The fraction of the first dose still in the body n intervals after it went in, which is f multiplied by itself n times","0.25 × 0.25 = 0.0625"],["e^(-kt)","The fraction of the peak after dose n that is left t hours later","e^(-0.1733 × 3) = e^(-0.520) = 0.5945"]]},"after":"Put together: Cp = 40 mg/L × 1.25 × 0.5945 = 29.7 mg/L. The 1.25 is the bracket, and the steps below show where it comes from."},{"h":"Why the bracket has that shape","ol":true,"list":["Dose 1 goes in. The body holds one dose, so the peak is C0 × 1 = 40 mg/L.","One interval later (τ = 8 hr) dose 1 has fallen to f of itself, 40 × 0.25 = 10 mg/L. Dose 2 adds another 40, so the peak after dose 2 is C0(1 + f) = 40 × 1.25 = 50 mg/L.","After dose 3 the body holds the new dose (1), dose 2 one interval old (f) and dose 1 two intervals old (f²): C0(1 + f + f²) = 40 × (1 + 0.25 + 0.0625) = 40 × 1.3125 = 52.5 mg/L.","Each dose adds one more term, so after n doses the bracket is 1 + f + f² + … + f^(n−1): n terms, one for each dose, and the oldest dose is n − 1 intervals old.","Algebra shortens that sum. Call it S and multiply it by f: fS = f + f² + … + f^n. Subtract this from S: S − fS = 1 − f^n, because every term from f to f^(n−1) is in both lines and cancels.","Factor out S: S(1 − f) = 1 − f^n, so S = {{frac:1 - f^n|1 - f}}. Put back f = e^(-kτ) and f^n = e^(-nkτ): S = {{frac:1 - e^(-nkτ)|1 - e^(-kτ)}}, the bracket on her slide.","Check with two doses: {{frac:1 - 0.0625|1 - 0.25}} = {{frac:0.9375|0.75}} = 1.25, the same as 1 + 0.25 in step 2."]},{"h":"Why the top of the bracket becomes 1 at steady state","ol":true,"list":["f is less than 1, so each power of f is smaller than the one before: f = 0.25, f² = 0.0625, f³ = 0.0156, f⁴ = 0.0039. In words, the first dose is almost gone after a few intervals.","The top of the bracket, 1 − f^n, therefore moves towards 1 as doses are added: 0.75, 0.9375, 0.9844, 0.9961 after doses 1 to 4.","Once f^n is too small to change the answer, the top is 1 and the bracket is {{frac:1|1 - e^(-kτ)}} = {{frac:1|0.75}} = 1.33, the accumulation factor. The textbook's Table 9-4 shows the same climb in amounts for a 1000-mg dose with f = 0.25: 1000, 1250, 1312, 1328, 1332 and 1333 mg after doses 1 to 6.","The equation is then the steady-state one: Cp = {{frac:D0|VD}} ({{frac:1|1 - e^(-kτ)}}) e^(-kt) = Cmax∞e^(-kt). For this regimen Cmax∞ = {{frac:40|0.75}} = 53.3 mg/L."]}],"teachImg":"slide_6RepetitiveIVBolus_p17","cite":"6---Repetitive-IV-Bolus-and-Intermittent-IV-Infusions.pdf, slide \"Plasma Drug Concentration at Steady State\"; 09.23 lecture","quote":"as N increases, that nation numerator portion up there reduces down to 1"},{"id":"m6b-c03","tier":"new","exam":2,"module":6,"lecture":"L08","topic":"intermit","sub":"add","concept":"after-infusion-stops","skill":"apply","source":"both","stem":"The first of a series of intravenous (IV) infusions ends. What governs the plasma concentration from that moment until the next infusion begins?","options":[{"t":"First-order decline from the end level","correct":true,"why":"With the input stopped, only elimination is left, and it is first order. The concentration falls as C = C0e^(-kt) with the end-of-infusion value as C0, which is why that value has to be found first."},{"t":"Zero-order decline at the infusion rate","why":"This reverses input and output. Once the infusion stops the input plays no further part, and the body removes a constant fraction per hour, not a constant amount."},{"t":"A continued rise towards R/Cl","why":"This treats the input as still running. The rise towards {{frac:R|Cl}} happens only while drug is going in; when the pump stops, the concentration is at its highest for that infusion and can only fall."},{"t":"A steady level until the next infusion","why":"This confuses the plateau of a continuous infusion with the gap between two short ones. A level holds steady only while rate in equals rate out, and between infusions the rate in is zero."}],"teach":[{"h":"The idea","list":["Every intermittent-infusion problem is two Module 3 pieces in turn: first the rise during the infusion, then the decline after it stops."]},{"h":"After the infusion stops","list":["Only first-order elimination is left: C = Cpeak e^(-kt), where Cpeak is the concentration when the infusion ended and t is the time since it ended, not since it started."]},{"h":"Her Example 4 drawn out","fig":"two_infusions","list":["300 mg is infused over 2 hours, so R = 150 mg/hr; k is 0.15 hr⁻¹ and VD is 15 L. Each infusion rises to 17.28 mg/L; the second runs from 6 to 8 hours.","At 12 hours the first infusion, declining for 10 hours, contributes 3.86 mg/L and the second, declining for 4 hours, 9.48 mg/L: 13.34 mg/L in all."]}],"cite":"6---Repetitive-IV-Bolus-and-Intermittent-IV-Infusions.pdf, slide \"What is the plasma drug concentration at the end of the first infusion?\"; 09.28 lecture","quote":"What happens when we stop the infusion? It's only elimination. ... So that C0 is gonna be the concentration at the end of the infusion, right?"},{"id":"m6b-c04","tier":"new","exam":2,"module":6,"lecture":"L08","topic":"intermit","sub":"add","concept":"time-since-that-infusion","skill":"apply","source":"both","stem":"A 2-hour infusion runs from 0 to 2 hours; a second identical infusion runs from 6 to 8 hours. To find the first infusion's contribution at 12 hours, what value of t goes into e^(−kt)?","options":[{"t":"10 hours","correct":true,"why":"The first infusion stopped at 2 hours and has been declining since, so at 12 hours it has declined for 12 − 2 = 10 hours. Its contribution is its end-of-infusion concentration multiplied by e^(-10k)."},{"t":"4 hours","why":"Choosing this measures the first infusion from the end of the second. Four hours is the decline time of the second infusion (12 − 8); the first stopped 6 hours earlier and has fallen further."},{"t":"12 hours","why":"Choosing this measures from the start of the first infusion, not its end. For the 2 hours it ran, the concentration was rising; the decline begins when it stops."},{"t":"6 hours","why":"This reads the gap between the two starts as the decline time. Six hours is when the second infusion began, which says nothing about how long the first has been declining at 12 hours."}],"teach":[{"h":"The idea","list":["Draw her number line: mark each start, each end, and the time asked for.","The t of each infusion is measured from its own end.","So the two infusions get different values of t at the same clock time."]},{"h":"Her Example 4 drawn out","fig":"two_infusions","list":["300 mg is infused over 2 hours, so R = 150 mg/hr; k is 0.15 hr⁻¹ and VD is 15 L. Each infusion rises to 17.28 mg/L; the second runs from 6 to 8 hours.","At 12 hours the first infusion, declining for 10 hours, contributes 3.86 mg/L and the second, declining for 4 hours, 9.48 mg/L: 13.34 mg/L in all."]}],"cite":"6---Repetitive-IV-Bolus-and-Intermittent-IV-Infusions.pdf, slide \"What is the plasma drug concentration 4 hours after the cessation of the second infusion?\"; 09.28 lecture","quote":"here is the part that you need to pay attention to. We are interested in the concentration from this red infusion where we stop at time 2. All the way out here on our number line at 12 hours later. So, the time that we're interested in is going to be the time that we're interested 12 minus 2, OK? So, 10 hours."},{"id":"m6b-c05","tier":"new","exam":2,"module":6,"lecture":"L08","topic":"intermit","sub":"add","concept":"infusions-add","skill":"tell","source":"both","stem":"Two identical intravenous (IV) infusions of the same drug are given 6 hours apart. Why can the plasma concentration at a later time be found by adding what is left of each?","options":[{"t":"Elimination is first order","correct":true,"why":"With first-order, linear kinetics a constant fraction is removed per hour whatever else is present, so the first infusion declines the same way whether or not a second is given. Each infusion is its own curve, and the curves add: superposition."},{"t":"Both infusions are zero-order inputs","why":"Choosing this attaches the additivity to the input. A zero-order input sets how drug goes in; the curves can be added because the output is first order and unchanged by the amount present."},{"t":"The second infusion restarts the clock for both","why":"Choosing this collapses two declines into one. The second infusion does not change what the first left behind; the first keeps declining on its own timetable, so its t is measured from its own end."},{"t":"The concentrations are the same at every time","why":"This reads \"identical infusions\" as identical curves at the same clock time. Each reaches the same end-of-infusion concentration, 17.3 mg/L in her example, but at different times, so at any one moment they have declined by different amounts."}],"teach":[{"h":"The idea","list":["This is superposition, from repeated IV (intravenous) bolus dosing, applied to infusions.","It rests on the same assumptions as for repeated bolus doses: first-order elimination, and a half-life and clearance that do not change with more doses.","So the same drug at the same rate for the same duration reaches the same Cpeak (end-of-infusion concentration) every time."]}],"cite":"6---Repetitive-IV-Bolus-and-Intermittent-IV-Infusions.pdf, slide \"Administering One or More Doses by IV Infusion\"; 09.28 lecture","quote":"the concentrations from each administration of the dose will be additive over time"},{"id":"m6b-c06","tier":"new","exam":2,"module":6,"lecture":"L08","topic":"intermit","sub":"why","concept":"intermittent-vs-bolus","skill":"tell","source":"both","stem":"A drug is given either as repeated intravenous (IV) bolus injections or as repeated 2-hour IV infusions, same dose and same interval. Where does each interval's peak occur?","options":[{"t":"Bolus: when the dose is given; infusion: when the infusion ends","correct":true,"why":"A bolus goes in all at once, so its peak is the instant it is given. An infusion keeps adding drug until the pump stops, so its highest point is the end of the infusion, where the decline starts."},{"t":"Both when the dose starts","why":"This treats the infusion as a bolus. When an infusion starts nothing has gone in yet; the concentration rises during the infusion and peaks only at its end."},{"t":"Both at the end of the dosing interval","why":"This reverses peak and trough. The end of the interval, just before the next dose, is where the concentration is lowest for either route."},{"t":"Bolus: when the infusion ends; infusion: when the dose is given","why":"This swaps the two routes. A bolus has no infusion time, and an infusion has no single moment at which the dose is in."}],"teach":[{"h":"The idea","list":["Repeated IV (intravenous) bolus and intermittent infusion share the equations for what happens between doses.","They differ in where the peak sits and in how it is found.","Bolus: C0 = {{frac:D0|VD}}, the dose over the apparent volume of distribution.","Infusion: the infusion equation with t equal to the infusion time."]},{"h":"Repeated bolus against intermittent infusion","table":{"head":["","Repeated IV bolus","Intermittent IV infusion"],"rows":[["Input","Instantaneous","Zero order, for the infusion time"],["Peak","At the dose, C0 = {{frac:D0|VD}}","At the end of the infusion, {{frac:R|VD k}}(1 - e^(-kt))"],["Between doses","First-order decline","First-order decline"],["Why chosen","Simple","A lower peak, better tolerated"]]}}],"cite":"6---Repetitive-IV-Bolus-and-Intermittent-IV-Infusions.pdf, slides \"Rationale\" and \"Administering One or More Doses by IV Infusion\"; 09.28 lecture","quote":"instead of putting all the drug into the body all at once, we are going to put the drug into the body via a zero order, like we just first, just talked about a zero-order constant process"},{"id":"m6b-c20","tier":"new","exam":2,"module":6,"lecture":"L08","topic":"intermit","sub":"why","concept":"infusion-time-in-rise","skill":"apply","source":"both","stem":"A second 2-hour intravenous (IV) infusion of the same dose starts 6 hours after the first began. What value of t goes into (1 − e^(−kt)) to find the concentration at the end of the second infusion?","options":[{"t":"2 hours","correct":true,"why":"The (1 − e^(−kt)) term describes the rise while drug is going in, so its t is how long the pump ran. Every infusion in the series runs 2 hours, so each reaches the same end-of-infusion concentration, 17.28 mg/L in her Example 4."},{"t":"6 hours","why":"Choosing this puts the clock time into an equation that only uses how long drug has been going in. The 6 hours places the second infusion on the time line; its rise depends only on its own 2-hour duration."},{"t":"8 hours","why":"This confuses when the infusion ends with how long it ran. Eight hours is where the second peak sits on the number line; the rise to that peak took 2 hours."},{"t":"4 hours","why":"Choosing this attaches the gap between the infusions to the rise. During the gap the first dose declines; the second dose rises over the same 2-hour climb from zero as the first."}],"teach":[{"h":"The idea","list":["Two different times are used in these problems.","The rise of each infusion uses its own duration.","The decline of each infusion uses the time since its own end.","The clock time serves only to work out those two."]},{"h":"The common error","list":["Using 6 hours in the infusion equation. The (1 - e^(-kt)) term applies only while drug is going in, so its t is the infusion time, 2 hours, for every infusion in the series."]}],"cite":"6---Repetitive-IV-Bolus-and-Intermittent-IV-Infusions.pdf, slide \"Administering One or More Doses by IV Infusion\"; 09.28 lecture","quote":"1 minus E to the minus KT where this T. Is the infusion time."},{"id":"m6b-c07","tier":"new","exam":2,"module":6,"lecture":"L09","topic":"multoral","sub":"oeq","concept":"oral-vs-bolus-ss-equation","skill":"tell","source":"both","stem":"Cmax∞ = {{frac:FD0|VD}} × {{frac:1|1 − e^(−kτ)}} × e^(−k·tmax∞). What marks this as the steady-state peak for an oral dose rather than for a repeated intravenous (IV) bolus?","options":[{"t":"The F and the tmax","correct":true,"why":"F is bioavailability, which an IV dose does not need, and tmax is the time to peak, which a bolus lacks because it peaks at the moment of the dose. Remove those two and what is left, {{frac:D0|VD}} × {{frac:1|1 − e^(−kτ)}}, is the bolus Cmax∞."},{"t":"The τ","why":"This reads the dosing interval as an oral feature. Every multiple-dose regimen has a τ, bolus or oral, so τ cannot tell the two apart."},{"t":"The accumulation factor {{frac:1|1 − e^(−kτ)}}","why":"Choosing this attaches accumulation to the oral route. The same factor appears in the repeated-bolus equations, because accumulation depends on k and τ, not on how the dose enters."},{"t":"The VD","why":"The volume of distribution turns an amount into a concentration for every route, so VD is in the bolus equation too."}],"teach":[{"h":"The idea","list":["On the equation sheet the oral and bolus steady-state peaks sit near each other and look alike.","Her test: an oral equation carries F (bioavailability), and an oral peak needs tmax (the time to peak) found first."]},{"h":"The symbols","list":["Symbols: ka is the absorption rate constant, k the elimination rate constant, τ the dosing interval, F the bioavailability, D0 the dose and VD the apparent volume of distribution. ∞ marks steady state."]}],"cite":"6a---Multiple-Oral-Doses.pdf, slide \"Peak, Trough and Average Plasma Concentrations at Steady State\"; 09.28 lecture","quote":"what tells you that this is for an oral dose? F is one thing. ... What else tells us? Team Max, right? Because when we're giving a bolus dose, when does the max occur? Initially"},{"id":"m6b-c08","tier":"new","exam":2,"module":6,"lecture":"L09","topic":"multoral","sub":"ossc","concept":"tmax-ss-depends","skill":"tell","source":"both","stem":"The time to peak after a single oral dose depends on k and ka. What does the time to peak at steady state, tmax∞, depend on?","options":[{"t":"k, ka and τ","correct":true,"why":"The steady-state expression has τ inside the logarithm, because drug left from earlier doses changes when the rising and falling rates balance. Change how often the drug is given, and tmax∞ must be recalculated."},{"t":"k and ka only","why":"Choosing this carries the single-dose result over unchanged. The τ terms in tmax∞ are the whole difference between the two equations."},{"t":"The dose and VD","why":"Choosing this brings in the quantities that set the height of the peak. Neither appears in tmax∞; a larger dose raises Cmax∞ and leaves the timing where it was."},{"t":"F and the dose","why":"This confuses when the peak occurs with how high it is. F and the dose scale the concentration; the time to peak is set by the two rate constants and, at steady state, the interval."}],"teach":[{"h":"The idea","list":["The single-dose tmax and the steady-state tmax∞ share k (the elimination rate constant) and ka (the absorption rate constant).","tmax∞ adds τ, the dosing interval.","A regimen does not change k or ka, so the interval is the only thing a regimen can change that moves tmax∞."]},{"h":"The steady-state time to peak","list":["Time to peak: tmax∞ = {{frac:1|ka - k}} ln[{{frac:ka(1 - e^(-kτ))|k(1 - e^(-ka τ))}}]."]}],"cite":"6a---Multiple-Oral-Doses.pdf, slide \"Time to Peak at Steady State\"; 09.28 lecture","quote":"for at steady state following multiple oral dosing. Depends on K, KA and tau. OK. Single oral dose, K and KA."},{"id":"m6b-c09","tier":"new","exam":2,"module":6,"lecture":"L09","topic":"multoral","sub":"ossc","concept":"interval-changes-tmax-cmax","skill":"apply","source":"both","stem":"A drug given orally every 6 hours is changed to every 12 hours, same dose. Which of the following must be recalculated?","options":[{"t":"tmax∞ and Cmax∞","correct":true,"why":"Both carry τ (the dosing interval): tmax∞ (the time to peak at steady state) inside its logarithm, and Cmax∞ (the steady-state peak) through the accumulation factor and through tmax∞ itself. A new interval means a new time to peak and a new peak."},{"t":"k and ka","why":"This treats the rate constants as adjustable. They belong to the drug and the formulation; a regimen changes only the dose and the interval."},{"t":"ClT and VD","why":"Picking this treats total clearance (ClT) and the volume of distribution (VD) as things a regimen sets. Both belong to the patient and the drug and do not move when the interval changes; they are inputs to every steady-state equation, not results of the regimen."},{"t":"Nothing at steady state","why":"This reads steady state as a fixed property of the drug. Steady state is a balance between what is given and what is cleared, and giving the same dose half as often halves the input."}],"teach":[{"h":"The idea","list":["Dose and interval are the two things a regimen can change.","The interval reaches into tmax∞, Cmax∞, Cmin∞ and Cavg∞: the time to peak, peak, trough and average at steady state.","The dose scales the concentrations without moving tmax∞."]},{"h":"Where τ sits in the oral equations","list":["Time to peak: tmax∞ = {{frac:1|ka - k}} ln[{{frac:ka(1 - e^(-kτ))|k(1 - e^(-ka τ))}}].","Peak: Cmax∞ = {{frac:FD0|VD}} ({{frac:1|1 - e^(-kτ)}}) e^(-k tmax∞)."]},{"h":"Her Example 1 three ways","fig":"dose_interval","after":"Her Example 1 (each dose adds 40 mg/L, t½ 4 hours) every 8 hours, every 4 hours, and at double the dose."}],"cite":"6a---Multiple-Oral-Doses.pdf, slide \"Time to Peak at Steady State\"; 09.28 lecture","quote":"So if we change the dosing interval, we need to recalculate TMax. Right? And it will also change our CMax."},{"id":"m6b-c10","tier":"new","exam":2,"module":6,"lecture":"L09","topic":"multoral","sub":"ossc","concept":"tmax-ss-shorter","skill":"apply","source":"both","stem":"A drug is given orally at a fixed dose and interval. How does the time to peak at steady state compare with the time to peak after the first dose?","options":[{"t":"It is generally shorter","correct":true,"why":"At steady state drug from earlier doses is already in the body, so elimination runs at a higher rate from the moment the new dose is taken, and the rising and falling rates balance sooner. In her tetracycline example tmax falls from 3.1 hours to 2.06 hours."},{"t":"It is generally longer","why":"This runs the wrong way. Accumulated drug does not delay the peak; it brings it forward, because the elimination rate is already high when absorption begins."},{"t":"It is the same","why":"Choosing this uses single-dose reasoning, where only k and ka matter. The steady-state tmax has τ in it as well, and her worked values differ: 3.1 against 2.06 hours."},{"t":"It is twice as long","why":"This attaches a fixed multiple to a relation that has none. The direction is shorter, and the size of the change depends on k, ka and τ together."}],"teach":[{"h":"The idea","list":["From the first dose to steady state, the peak comes earlier and higher.","Earlier because of tmax∞, the time to peak at steady state; higher because of the accumulation factor."]},{"h":"First dose against steady state: her tetracycline example","list":["250 mg every 8 hours, F 0.75, VD 112.5 L; t½ (half-life) 10 hr, so k is 0.0693 hr⁻¹; ka is 0.9 hr⁻¹."],"table":{"head":["","First dose","At steady state"],"rows":[["tmax","{{frac:ln(ka/k)|ka - k}} = 3.1 hr","tmax∞, with τ in it: 2.06 hr"],["Cmax","The single-dose equation at tmax: 1.35 mg/L","Cmax∞, with the accumulation factor: 3.4 mg/L computed (she says 3.3)"]]},"after":"From the first dose to steady state, tmax falls and Cmax rises by the accumulation factor {{frac:1|1 - e^(-kτ)}}, 2.35 here."}],"cite":"6a---Multiple-Oral-Doses.pdf, slide \"Example 1\"; 09.28 lecture","quote":"That steady state TMAX is going to be lower than the T-Max of the first dose, OK?"},{"id":"m6b-c13","tier":"new","exam":2,"module":6,"lecture":"L09","topic":"multoral","sub":"oparam","concept":"regimen-parameters","skill":"recall","source":"both","stem":"Which two parameters can be adjusted in developing a dosage regimen?","options":[{"t":"Dose size and dosing interval","correct":true,"why":"How much drug is given and how often are the two things a prescriber decides. Everything else in the equations, such as k, the half-life, clearance and VD, belongs to the drug and the patient."},{"t":"Clearance and volume of distribution","why":"Choosing this treats patient parameters as adjustable. Clearance and VD are what the patient brings; the regimen is designed around them, not by changing them."},{"t":"Half-life and dose","why":"The dose is right and the half-life is not. The half-life follows from k, which the drug and the patient set, so a regimen cannot lengthen or shorten it."},{"t":"Bioavailability and dosing interval","why":"The interval is right and F (bioavailability) is not. F is a property of the drug and its formulation; changing the product might change it, but the regimen does not set it."}],"teach":[{"h":"The idea","list":["A regimen sets two things: the dose and the interval.","The rest of the equation is fixed by the drug and the patient.","Her slides \"Altering Dose\" and \"Altering Dosing Interval\" list the effects of each change."]},{"h":"Her Example 1 three ways","fig":"dose_interval","after":"Her Example 1 (each dose adds 40 mg/L, t½ 4 hours) every 8 hours, every 4 hours, and at double the dose."}],"cite":"6a---Multiple-Oral-Doses.pdf, slide \"Multiple-Dosage Regimens\"; 09.28 lecture","quote":"So the only things that we can change. Are the dose, so the, the size of the dose, how much drug we give, and the dosing intervals. OK. We don't change clearance, we don't change half-life, we don't change volume and distribution."},{"id":"m6b-c14","tier":"new","exam":2,"module":6,"lecture":"L09","topic":"multoral","sub":"oparam","concept":"increase-dose-effects","skill":"apply","source":"both","stem":"Which of the following would be expected at steady state if the oral dose of a drug is doubled with no change to the dosing interval?","options":[{"t":"Higher concentrations and a larger swing between peak and trough","correct":true,"why":"A larger dose raises every concentration in proportion, so the peak, trough and average all rise, and the peak-to-trough gap, a fixed fraction of the peak, grows with them. Compliance usually does not change, because the patient takes the same number of doses."},{"t":"Higher concentrations and a smaller swing between peak and trough","why":"This pairs the right direction for the level with the wrong one for the swing. Doubling the dose doubles the peak and the trough, so the difference between them doubles too."},{"t":"The same average concentration, reached sooner","why":"This confuses the dose with the half-life. The dose sets how high the plateau is, not how fast it is reached; steady state still takes 3 to 5 half-lives."},{"t":"A longer time to peak","why":"Choosing this attaches the dose to tmax. Neither the single-dose tmax nor tmax∞ contains the dose, so doubling it leaves the timing alone."}],"teach":[{"h":"The idea","list":["Method 1 for altering steady state: change the dose, keep the interval.","Fluctuation, or swing, is how far the level falls from the peak to the trough within one dosing interval.","The whole curve scales up: peak, trough and average all double when the dose doubles, and so does the gap; in her Example 1 it doubles from 40 to 80 mg/L.","The trough stays the same fraction of the peak, because that fraction, e^(−kτ), depends on the interval and k, not on the dose.","Her slide \"Altering Dose\" calls this \"increased fluctuation\"."]},{"h":"Her Example 1 three ways","fig":"dose_interval","after":"Her Example 1 (each dose adds 40 mg/L, t½ 4 hours) every 8 hours, every 4 hours, and at double the dose."}],"cite":"6a---Multiple-Oral-Doses.pdf, slides \"Altering Dose\" and \"Altering Dose, second slide\"; 09.28 lecture","quote":"if we increase the dose, we expect increased concentration and increased fluctuation between peaks and troughs"},{"id":"m6b-c15","tier":"new","exam":2,"module":6,"lecture":"L09","topic":"multoral","sub":"oparam","concept":"increase-interval-effects","skill":"apply","source":"both","stem":"A 500-mg oral dose given every 4 hours is changed to 500 mg every 8 hours. What is expected at steady state?","options":[{"t":"Lower concentrations, a larger swing, and better compliance","correct":true,"why":"The same dose half as often halves the input, so the average falls. Each dose also has longer to be eliminated before the next, so the level drops further between doses and the swing grows. Fewer doses a day are easier to keep to."},{"t":"Lower concentrations, a smaller swing, and better compliance","why":"Picking this reads a longer interval as a steadier level. The same 500 mg every 8 hours instead of every 4 gives each dose twice the time to be eliminated before the next, so the trough falls further and the swing grows."},{"t":"Higher concentrations, a smaller swing, and better compliance","why":"Picking this reads a longer interval as more drug. The dose is unchanged at 500 mg and is given half as often, so the input per day halves and Cavg∞ (the average steady-state concentration), {{frac:F D0|Cl τ}}, falls as τ (the dosing interval) doubles."},{"t":"The same concentrations, the same swing, and better compliance","why":"Picking this leaves τ (the dosing interval) out of the average. Cavg∞ is {{frac:F D0|Cl τ}}: with the same 500 mg dose and τ doubled from 4 to 8 hours, the average halves, and the swing grows."}],"steps":[{"k":"algebra","t":"Doses per day: {{frac:24 hr|4 hr}} = 6, so 6 × 500 mg = 3000 mg a day; {{frac:24 hr|8 hr}} = 3, so 3 × 500 mg = 1500 mg a day","why":"Half as many doses a day halves the daily input, from 3000 to 1500 mg; the drug and the patient are unchanged, so clearance is unchanged and the level has to fall."},{"k":"algebra","t":"Cavg∞ = {{frac:F D0|Cl τ}}: τ doubles from 4 to 8 hr, so Cavg∞ falls to {{frac:4|8}} = 0.5 of its value; the steady-state concentrations are lower","why":"The average steady-state concentration carries the interval in its denominator, with the dose, F and clearance unchanged, so doubling τ halves the average."},{"k":"setup","t":"Swing: Cmin∞ = Cmax∞ e^(−kτ); with τ = 8 hr the fraction left at the trough is e^(−8k) = (e^(−4k))², smaller than with τ = 4 hr, so the trough falls further below the peak","why":"Each dose now has 8 hours rather than 4 to be eliminated before the next arrives. The fraction of the peak left at the trough is squared, so the trough is a smaller fraction of the peak: a larger swing."},{"k":"setup","t":"Compare: lower average (half), larger swing (trough fraction squared), 3 doses a day instead of 6: lower concentrations, a larger swing, better compliance","why":"Each part follows from the longer interval: half the daily input gives a lower level, a longer decline gives a larger swing, and three doses a day are easier to keep to than six."}],"givens":[["D0","500-mg","unchanged: the same dose at both intervals"],["τ","every 4 hours","the old interval: 6 doses a day"],["τ new","every 8 hours","the new interval: 3 doses a day; Cavg∞ falls to {{frac:4|8}} = 0.5"]],"check":{"t":"The dose is unchanged, so the level cannot rise: the same 500 mg given half as often, 3 times a day instead of 6, halves the input, and each dose has twice as long to fall before the next. Average and trough both move down, the trough further."},"teach":[{"h":"The idea","list":["Method 2 for altering steady state: change the interval, keep the dose."]},{"h":"What each change does at steady state","table":{"head":["Change","Steady-state concentration","Fluctuation, peak to trough","Patient compliance"],"rows":[["Increase the dose, same τ","Higher","Larger","Usually no change"],["Decrease the dose, same τ","Lower","Smaller","Usually no change"],["Increase τ, same dose (less often)","Lower","Larger","Better"],["Decrease τ, same dose (more often)","Higher","Smaller","Worse"]]}},{"h":"Her Example 1 three ways","fig":"dose_interval","after":"Her Example 1 (each dose adds 40 mg/L, t½ 4 hours) every 8 hours, every 4 hours, and at double the dose."}],"cite":"6a---Multiple-Oral-Doses.pdf, slides \"Altering Dosing Interval\" and \"Altering Dosing Interval, second slide\"; 09.28 lecture","quote":"increasing the dosing interval. Right? Increasing the dosing interval means that we're giving more time in between doses, decreased steady-state concentration, increased fluctuation between peak to trough. Increase patient compliance, generally."},{"id":"m6b-c16","tier":"new","exam":2,"module":6,"lecture":"L09","topic":"multoral","sub":"oparam","concept":"decrease-interval-fluctuation","skill":"apply","source":"both","stem":"The dosing interval of an oral regimen is shortened from 8 hours to 4 hours, same dose. Why does the fluctuation between peak and trough decrease?","options":[{"t":"Less time passes for the level to fall","correct":true,"why":"The trough is where the next dose interrupts the decline. With 4 hours instead of 8, the decline stops earlier, so the trough sits closer to the peak, a larger fraction of it, even though both peak and trough are higher."},{"t":"Less drug accumulates, so the peaks are lower","why":"This has accumulation backwards. A shorter interval leaves more of each dose behind when the next arrives, so more accumulates and the peaks are higher; the swing shrinks because the troughs rise by a larger fraction than the peaks."},{"t":"The elimination rate constant falls","why":"Choosing this changes k. The regimen changes only how often the drug is given; k, the half-life and clearance are unchanged."},{"t":"Absorption becomes slower","why":"Choosing this changes ka. Each dose is absorbed with the same ka whatever the interval; the smaller swing comes from the shorter decline between doses."}],"teach":[{"h":"The idea","list":["Her reasoning: 3 to 5 half-lives clear most of a dose.","A shorter interval cuts into that time, so the level does not get near the bottom of the curve before the next dose arrives.","So Cmax∞ and Cmin∞ both go up; what decreases is how far the level falls between them.","In her Example 1 the trough is a quarter of the peak every 8 hours and half of it every 4 hours."]},{"h":"Her Example 1 three ways","fig":"dose_interval","after":"Her Example 1 (each dose adds 40 mg/L, t½ 4 hours) every 8 hours, every 4 hours, and at double the dose."}],"cite":"6a---Multiple-Oral-Doses.pdf, slide \"Altering Dosing Interval, second slide\"; 09.28 lecture","quote":"if we decrease that, um, dosing interval, then maybe we're cutting into that 3 to 5 half-lives a little bit more, so we're not going all the way to the bottom of that curve"},{"id":"m6b-c17","tier":"new","exam":2,"module":6,"lecture":"L09","topic":"multoral","sub":"oparam","concept":"interval-time-to-ss","skill":"read","source":"both","stem":"Equal oral doses of a drug are given every 6 hours in one regimen and every 8 hours in another; ka and k are the same. What differs between the two curves of amount in the body against time?","options":[{"t":"The 6-hour plateau is higher and is reached in the same time","correct":true,"why":"Dosing more often puts more drug in per day, so the plateau is higher. The time to plateau is set by the half-life, which is the same for one drug in both regimens, so both curves level off over the same time."},{"t":"The 6-hour regimen reaches its plateau sooner","why":"Choosing this ties the time to plateau to the interval. It depends on the elimination half-life alone: more frequent doses raise the plateau but do not bring it earlier."},{"t":"The plateaus are the same height","why":"Choosing this leaves τ out of the steady-state level. Cavg∞ has τ in its denominator, so the regimen with the shorter interval plateaus higher."},{"t":"The 8-hour regimen has a smaller swing between maximum and minimum","why":"This runs the wrong way. The longer interval gives each dose more time to be eliminated before the next, so its swing between maximum and minimum is larger."}],"teach":[{"h":"The idea","list":["The figure is from the chapter: two regimens of equal doses, one every 6 hours and one every 8 hours.","The upper curve is the 6-hour regimen.","Both curves level off over the same time."]},{"h":"Her Example 1 three ways","fig":"dose_interval","after":"Her Example 1 (each dose adds 40 mg/L, t½ 4 hours) every 8 hours, every 4 hours, and at double the dose."}],"cite":"6a---Multiple-Oral-Doses.pdf, slide \"Altering Dosing Interval, third slide\"; Chapter 9, Multiple-Dosage Regimens, section Drug Accumulation","quote":"Equal doses of drug were given every 6 hours (upper curve) and every 8 hours (lower curve). ka and k remain constant."},{"id":"m6b-c19","tier":"new","exam":2,"module":6,"lecture":"L09","topic":"multoral","sub":"oparam","concept":"peak-trough-range","skill":"read","source":"both","stem":"A dosage regimen is judged against the therapeutic range. Which two steady-state values have to lie inside it?","options":[{"t":"The peak and the trough","correct":true,"why":"The concentration swings between peak and trough every interval, so the regimen is safe only if the peak stays below the top of the range, and effective only if the trough stays above the bottom. The average can sit inside the range while the peak or trough falls outside it."},{"t":"The average and the first-dose peak","why":"This uses the wrong pair. The first-dose peak no longer applies once the patient is at steady state, and the average says nothing about how far the concentration swings around it."},{"t":"The concentration at time zero and at infinity","why":"This reads the ∞ sign as a time. At steady state the concentration repeats every interval; the values to check are the highest and lowest points of that repeat."},{"t":"Only the average","why":"Choosing this leaves out the fluctuation. Two regimens can share an average while one swings above the toxic level and below the effective level within every interval."}],"teach":[{"h":"The idea","list":["At steady state the curve swings between a peak and a trough every interval.","The therapeutic range runs from the minimum effective concentration (MEC), below which the drug does not act, to the minimum toxic concentration (MTC), above which adverse effects appear.","Her Multiple IV Bolus Practice 2 sets a window of 2 to 10 mcg/mL and a steady-state peak of 10 mg/L; the trough is 1.576 mg/L, below the floor.","Shortening the interval from 8 to 6 hours lifts the trough to 2.5 mg/L."]}],"cite":"6a---Multiple-Oral-Doses.pdf, slide \"Consider Peak and Trough\"; 09.28 lecture","quote":"We wanna design a regimen that is going to be feasible for our patient to maintain."},{"id":"m7-c01","tier":"new","exam":2,"module":7,"lecture":"L10","topic":"bioavail","sub":"defs","concept":"product-performance","skill":"recall","source":"both","stem":"Which term describes the release of the drug substance from the drug product leading to bioavailability of the drug substance?","options":[{"t":"Drug product performance","correct":true,"why":"Product performance is the first step: the drug has to leave the dosage form before anything else can happen. A tablet that does not release its drug gives no absorption and no plasma concentration–time curve, so the body cannot use the drug."},{"t":"Bioavailability","why":"This reads product performance as bioavailability. The fraction absorbed is what bioavailability data estimate; product performance is the release from the dosage form that has to happen before absorption can start. Choosing this merges the two definitions."},{"t":"Bioequivalence","why":"Picking this reads a one-product property as a two-product comparison. Bioequivalence is the absence of a significant difference in rate and extent between a test and a reference product of the same drug. Product performance describes a single product: whether and how its drug substance is released from the dosage form."},{"t":"Absolute bioavailability","why":"Picking this takes the release step for the measurement that follows it. Absolute bioavailability is the fraction F of an extravascular dose reaching the circulation, measured as its AUC (area under the curve) against the AUC of an IV dose. Product performance is the release from the dosage form that precedes absorption."}],"teach":[{"h":"The idea","list":["Capsules, tablets and sustained- or modified-release forms differ in how they release drug, which is what product performance describes."]},{"h":"The four definitions","list":["Drug product performance: the release of the drug substance from the drug product, leading to bioavailability of the drug substance.","Bioavailability: the rate and extent to which the active ingredient is absorbed from a drug product and becomes available at the site of action.","Absolute bioavailability, Fabs: an extravascular dose compared with the same drug given IV (intravenously).","Relative bioavailability, Frel: one formulation compared with a second formulation of the same drug.","Bioequivalence: no significant difference in rate and extent between two products given at the same molar dose under similar conditions."]}],"cite":"7a---Bioavailability-and-Bioequivalence.pdf, slide \"Drug Product Performance\"; transcript 09-30","quote":"Product performance is basically making sure that the drug releases from the dosage form. If the drug does not release from dosage form, then the drug will not be available for the body to use."},{"id":"m7-c02","tier":"new","exam":2,"module":7,"lecture":"L10","topic":"bioavail","sub":"defs","concept":"bioavail-rate-extent","skill":"recall","source":"both","stem":"Bioavailability is the rate and extent to which the active ingredient or active moiety is absorbed from a drug product and becomes available at the site of action. From a plasma concentration–time curve, which of the following is used to estimate the rate?","options":[{"t":"tmax","correct":true,"why":"The AUC (area under the plasma concentration–time curve) measures how much drug reached the circulation, which is the extent. tmax (the time of the peak) measures how fast it got there, which is the rate. Bioavailability is both, although the calculations use AUC."},{"t":"AUC","why":"This swaps the two. The area under the curve counts the amount of drug that reached the circulation, which is extent; the time at which the curve peaks reports how quickly it was absorbed, which is rate."},{"t":"the elimination half-life","why":"Picking this attaches the rate to the wrong phase of the curve. The half-life belongs to elimination, not to absorption. The rate in the definition is the rate of absorption, read as the time to the peak, tmax."},{"t":"the volume of distribution","why":"Picking this takes a distribution parameter for a measure of absorption. VD (the apparent volume of distribution) relates the amount of drug in the body to its plasma concentration once the drug is in the circulation; it says nothing about how fast the drug arrived. The rate is read from tmax."}],"teach":[{"h":"The idea","list":["Extent: AUC. Rate: tmax.","tmax measures rate because tmax = {{frac:ln(ka/k)|ka − k}} holds the absorption rate constant ka: faster absorption gives an earlier peak, and the dose does not move it.","AUC measures extent because AUC = {{frac:F × D0|Cl}}: with clearance constant, the area is proportional to the amount of drug that reached the circulation.","Absolute and relative bioavailability are calculated from AUCs, so they compare extent; bioequivalence asks about the rate as well."]}],"cite":"7a---Bioavailability-and-Bioequivalence.pdf, slide \"Bioavailability\"; transcript 09-30","quote":"We think about that in terms of our AUC, right? What's the AUC of one dose, one dosage forms relative to another? What is the AUC? What do you think about the rate? So we think about rate in terms of T max."},{"id":"m7-c03","tier":"new","exam":2,"module":7,"lecture":"L10","topic":"bioavail","sub":"defs","concept":"absolute-vs-relative","skill":"tell","dupOf":"cq4-10","source":"both","stem":"What does absolute bioavailability compare?","options":[{"t":"An extravascular dose against an IV dose of the same drug","correct":true,"why":"Absolute means compared with the IV (intravenous) dose, where F is 1 because the whole dose is in the circulation. The oral (extravascular) AUC is set against the IV AUC, with the doses corrected for if they differ."},{"t":"Two different formulations of the same drug","why":"Picking this takes relative bioavailability for absolute. Comparing two formulations of the same drug, neither of them IV (intravenous), is relative bioavailability, with one of the two chosen as the reference. Absolute bioavailability always has the IV dose as the reference, because only an IV dose puts the whole dose in the circulation."},{"t":"A test product with a reference product at the same molar dose","why":"Picking this takes a bioequivalence study for an absolute bioavailability measurement. A test product against a reference product at the same molar dose is the bioequivalence comparison, which asks about rate and extent together. Absolute bioavailability is a single ratio of AUCs (areas under the curve) with the IV AUC in the denominator."},{"t":"The dose given with the amount excreted unchanged in the urine","why":"This reads the fraction excreted unchanged, fe, as bioavailability. fe splits elimination between the kidney and the liver; bioavailability asks how much of a dose reached the circulation at all."}],"teach":[{"h":"The idea","list":["Absolute: compared with the IV dose.","Relative: compared with another formulation of the same drug.","In both, the thing compared with sits in the denominator."]},{"h":"Absolute, relative and bioequivalent, side by side","table":{"head":["","Absolute","Relative","Bioequivalence"],"rows":[["Compared with","the IV dose of the same drug","another formulation of the same drug","a reference product"],["Measures","extent","extent","rate and extent"],["Above 1?","No","Yes","A judgement, not a number"]]},"after":"A bioequivalence study is a specialized type of relative bioavailability study: it adds the rate to the extent."}],"cite":"7a---Bioavailability-and-Bioequivalence.pdf, slide \"Absolute Bioavailability\"; transcript 09-30","quote":"So, absolute says we are comparing basically to the IV."},{"id":"m7-c04","tier":"new","exam":2,"module":7,"lecture":"L10","topic":"bioavail","sub":"defs","concept":"absolute-vs-relative","skill":"tell","source":"both","dupOf":"m7-c03","stem":"A study compares the AUC of a new tablet of a drug with the AUC of the innovator's tablet of the same drug, both at 250 mg. Which term describes this comparison?","options":[{"t":"Relative bioavailability","correct":true,"why":"Two formulations of the same drug are compared and neither is IV (intravenous), so the ratio is relative: Frel, with the innovator product as the reference B in the denominator."},{"t":"Absolute bioavailability","why":"Absolute bioavailability needs the IV dose as the reference, because only an IV dose has F equal to 1. Comparing two oral products gives a value relative to whichever was chosen as the standard, which may itself be incompletely absorbed. Choosing this treats the innovator tablet as if it were the IV dose."},{"t":"Bioequivalence","why":"Picking this reads an AUC ratio as a full bioequivalence judgement. An AUC (area under the curve) ratio reports only the extent of absorption. Bioequivalence needs the rate as well, read from tmax (the time of the peak), which this study has not compared: the tablets could share an AUC and peak at different times."},{"t":"Drug product performance","why":"Picking this takes a property of one product for a comparison of two. Product performance is the release of the drug from a dosage form, assessed product by product. This study sets the AUC (area under the curve) of the new tablet against that of the innovator tablet, two oral products of one drug."}],"teach":[{"h":"The idea","list":["Relative bioavailability compares two drug formulations: a new product against the innovator, a tablet against a solution.","The reference is whatever product set the standard for the drug, and it goes in the denominator of Frel = ({{frac:AUCA|AUCB}})({{frac:DB|DA}})."]},{"h":"Absolute, relative and bioequivalent, side by side","table":{"head":["","Absolute","Relative","Bioequivalence"],"rows":[["Compared with","the IV dose of the same drug","another formulation of the same drug","a reference product"],["Measures","extent","extent","rate and extent"],["Above 1?","No","Yes","A judgement, not a number"]]},"after":"A bioequivalence study is a specialized type of relative bioavailability study: it adds the rate to the extent."}],"cite":"7a---Bioavailability-and-Bioequivalence.pdf, slide \"Relative Bioavailability\"; transcript 09-30","quote":"Relative bioavailability says that we are just comparing two drug formulations. Um, we could be comparing, um, a new product on the market to the innovator part, um, product, etc. but we are comparing two different formulations of the same drug."},{"id":"m7-c05","tier":"new","exam":2,"module":7,"lecture":"L10","topic":"bioavail","sub":"defs","concept":"bioequivalence-def","skill":"recall","source":"both","stem":"Which term describes the absence of a significant difference in the rate and extent to which the active ingredient becomes available at the site of drug action when two products are given at the same molar dose under similar conditions?","options":[{"t":"Bioequivalence","correct":true,"why":"The definition carries both halves of bioavailability, rate and extent, and fixes the conditions: the same molar dose, similar conditions, an appropriately designed study. Absence of a significant difference is the standard, so the two products need not be identical."},{"t":"Relative bioavailability","why":"This stops at extent. Two products with the same AUC at the same dose can still differ in how fast the drug appears, and a difference in rate is enough to make them not bioequivalent."},{"t":"Absolute bioavailability","why":"Picking this takes a comparison against the IV dose for a comparison between two products. Absolute bioavailability is one ratio, the AUC (area under the curve) of an extravascular dose over the IV AUC, and reports extent alone. The stem compares two products at the same molar dose in rate and extent: bioequivalence."},{"t":"Drug product performance","why":"Picking this takes the release step for the comparison that is built on it. Drug product performance is the release of the drug substance from one dosage form. The stem describes two products compared for rate and extent at the same molar dose; products with different excipients are bioequivalent if neither differs significantly."}],"teach":[{"h":"The idea","list":["Bioequivalence compares a test product with a reference product of the same active ingredient.","The two do not have to be exactly the same; they cannot be too different, in rate or in extent."]},{"h":"Absolute, relative and bioequivalent, side by side","table":{"head":["","Absolute","Relative","Bioequivalence"],"rows":[["Compared with","the IV dose of the same drug","another formulation of the same drug","a reference product"],["Measures","extent","extent","rate and extent"],["Above 1?","No","Yes","A judgement, not a number"]]},"after":"A bioequivalence study is a specialized type of relative bioavailability study: it adds the rate to the extent."}],"cite":"7a---Bioavailability-and-Bioequivalence.pdf, slide \"Bioequivalence\"; transcript 09-30","quote":"It's the absence of a significant difference. So they don't have to be exactly the same, but they just can't be too different."},{"id":"m7-c07","tier":"new","exam":2,"module":7,"lecture":"L10","topic":"bioavail","sub":"defs","concept":"f-greater-than-1","skill":"tell","source":"both","stem":"Which bioavailability can be greater than 1?","options":[{"t":"relative bioavailability only","correct":true,"why":"An IV (intravenous) dose is entirely in the circulation, so an oral product cannot deliver more than the IV reference and Fabs is at most 1. A relative F compares two formulations, and the test product can have a larger AUC than the standard, such as an old product like Bayer aspirin."},{"t":"absolute bioavailability only","why":"Picking this gives the cap to the wrong ratio. Absolute F compares an oral AUC (area under the curve) with the IV AUC, and the whole IV dose is in the circulation, so no oral product exceeds it. The relative reference is an ordinary formulation, so a better-absorbed test product gives Frel above 1."},{"t":"both relative and absolute bioavailability","why":"Picking this leaves the dose correction out of the absolute ratio. Fabs = ({{frac:AUCpo|AUCIV}})({{frac:DIV|Dpo}}), and the dose ratio {{frac:DIV|Dpo}} removes the effect of a larger oral dose, so a bigger tablet does not push an absolute F above 1. Only the relative F, whose reference is an ordinary product, can exceed 1."},{"t":"neither relative nor absolute bioavailability","why":"This reverses the two. The absolute F is capped at 1 by the IV reference; the relative F has no such cap because its reference is an ordinary product."}],"teach":[{"h":"The idea","list":["In Practice Problem 2 the tablet came out at 1.03 against the solution: a slightly higher bioavailability than the standard.","Such a value is possible because the standard is whatever product set the standard, not a perfect product.","Against the IV dose, F cannot exceed 1."]},{"h":"Absolute, relative and bioequivalent, side by side","table":{"head":["","Absolute","Relative","Bioequivalence"],"rows":[["Compared with","the IV dose of the same drug","another formulation of the same drug","a reference product"],["Measures","extent","extent","rate and extent"],["Above 1?","No","Yes","A judgement, not a number"]]},"after":"A bioequivalence study is a specialized type of relative bioavailability study: it adds the rate to the extent."}],"cite":"7a---Bioavailability-and-Bioequivalence.pdf, slide \"Practice Problem\" (relative); transcript 09-30","quote":"Can we have an F greater than 1? Yes, For absolute or for relative or either, both? Relative, but what about for absolute?"},{"id":"m7-c08","tier":"new","exam":2,"module":7,"lecture":"L10","topic":"bioavail","sub":"defs","concept":"rel-f-not-bioequivalence","skill":"tell","source":"both","stem":"A tablet and an oral solution of the same drug, both 250 mg, give a relative bioavailability of 1.03. Which of the following is needed to decide whether the two products are bioequivalent and is not given by the AUCs?","options":[{"t":"the rate of absorption","correct":true,"why":"A relative F is a ratio of AUCs (areas under the curve), so it says the two products deliver about the same amount of drug. Bioequivalence is the absence of a significant difference in rate and extent, and the time of the peak of each product is not known from the AUCs."},{"t":"the extent of absorption","why":"Picking this asks for what the AUCs already give. The extent of absorption is read from the AUC (area under the curve), and the relative F of 1.03 is that comparison: the two products deliver about the same amount of drug. What the AUCs do not give is the rate, read from tmax."},{"t":"the dose of each product","why":"Picking this asks for what the stem already gives. Both products were 250 mg, and the same molar dose is a requirement of a bioequivalence study that is met here. Equal doses say nothing about whether the rates were compared."},{"t":"the clearance of the drug","why":"Picking this takes an elimination parameter for the missing half of bioequivalence. Clearance (Cl) belongs to the drug and the patient and is the same whichever product is given, so it cannot separate the tablet from the solution. What the AUCs leave unknown is the rate of absorption, read from tmax."}],"teach":[{"h":"The idea","list":["Similar F values mean similar extent.","Whether the two products peak at the same time is a separate question, and bioequivalence needs both."]},{"h":"Reading the bioequivalence example","fig":"slide_7a---Bioavailabili_p13","list":["AUCA = AUCB and AUCC = 0.5 AUCA.","A and B: same AUC, so same extent; B peaks later, so a different rate. Not bioequivalent.","A and C: same peak time, so same rate; C has half the AUC, so a different extent. Not bioequivalent."]}],"cite":"7a---Bioavailability-and-Bioequivalence.pdf, slides \"Practice Problem\" (relative) and \"Bioequivalence\"; transcript 09-30","quote":"here, these two have similar F's, but you don't know if they're bioequivalent because you don't know about the, the rate. When do, when does it peak, right?"},{"id":"m7-c09","tier":"new","exam":2,"module":7,"lecture":"L10","topic":"bioavail","sub":"factors","concept":"factors-list","skill":"recall","source":"both","stem":"Which of the following can influence the bioavailability of a drug?","options":[{"t":"first-pass metabolism","correct":true,"why":"Drug metabolised in the gut wall or the liver before it reaches the systemic circulation never becomes available, so first-pass metabolism lowers F. It is one of the three factors that come to mind first."},{"t":"the elimination half-life","why":"The half-life describes how fast the body removes drug that has already reached the circulation. Bioavailability is about how much reaches it and how fast; the half-life is a property of elimination, not of the product or the absorption. Choosing this mixes the two phases of the curve."},{"t":"the size of the IV dose used as the reference","why":"Picking this treats the arithmetic of the measurement as a factor acting on the drug. In Fabs = ({{frac:AUCpo|AUCIV}})({{frac:DIV|Dpo}}) the dose ratio corrects for the reference dose, so the IV dose size does not change F. The listed factors act on how much drug reaches the circulation."},{"t":"the apparent volume of distribution","why":"Picking this takes a distribution parameter for a determinant of absorption. VD (the apparent volume of distribution) relates the amount of drug in the body to the plasma concentration once the drug is in the circulation. It does not decide how much of an oral dose gets there, so it does not influence bioavailability."}],"teach":[{"h":"Factors influencing bioavailability","list":["Physicochemical properties of the drug and formulation: solubility, polymorphic form and particle size, and the excipients and manufacture that control release.","Drug stability and pH effects.","Pre-systemic and first-pass metabolism: metabolism of an oral dose, mainly in the liver, before it reaches the general circulation; that drug never becomes available, so F falls.","Also: prodrugs, food effects, drug–drug interactions, efflux transporters, age and disease state."]},{"h":"The idea","t":"The first three, physicochemical properties, stability and pH, and first-pass metabolism, are the ones that come to mind most often."}],"cite":"7a---Bioavailability-and-Bioequivalence.pdf, slide \"Factors Influencing Bioavailability\"; transcript 09-30","quote":"Probably the one that comes to our minds most often are kind of these first couple of things here. 1st 3 actually."},{"id":"m7-c10","tier":"new","exam":2,"module":7,"lecture":"L10","topic":"bioavail","sub":"factors","concept":"low-f-reasons","skill":"recall","source":"both","stem":"Which of the following can cause a drug or drug product to show low bioavailability?","options":[{"t":"formulation factors and the first-pass effect","correct":true,"why":"The summary names formulation factors, which belong to the product (release, physicochemical properties, stability), and the first-pass effect, which belongs to the body (metabolism before the drug reaches the circulation). They are the two reasons the summary slide names."},{"t":"a large volume of distribution and a long half-life","why":"These describe where the drug goes and how long it stays once it is in the circulation. They do not alter how much of an oral dose gets there, so they do not lower F. Choosing this attaches distribution and elimination to absorption."},{"t":"a low clearance and a high AUC","why":"Picking this reads a large AUC (area under the curve) as a sign of high bioavailability. A low clearance raises the AUC of any dose, oral or IV alike, so the ratio of the two areas, which is F, is unchanged. F is lowered by what happens before the drug reaches the circulation, not afterwards."},{"t":"too small an IV reference dose","why":"Picking this treats the reference dose as a cause of low bioavailability. In Fabs = ({{frac:AUCpo|AUCIV}})({{frac:DIV|Dpo}}) the dose ratio removes the effect of the reference dose, so a small IV dose does not lower F. The summary slide names formulation factors and the first pass."}],"teach":[{"h":"The idea","t":"Low bioavailability comes from formulation factors, from the first-pass effect, and from the other items on the factors list (her slide \"Summary\")."},{"h":"Factors influencing bioavailability","list":["Physicochemical properties of the drug and formulation: solubility, polymorphic form and particle size, and the excipients and manufacture that control release.","Drug stability and pH effects.","Pre-systemic and first-pass metabolism: metabolism of an oral dose, mainly in the liver, before it reaches the general circulation; that drug never becomes available, so F falls.","Also: prodrugs, food effects, drug–drug interactions, efflux transporters, age and disease state."]}],"cite":"7a---Bioavailability-and-Bioequivalence.pdf, slide \"Summary\"; transcript 09-30","quote":"Drugs and drug products can exhibit low bioavailability for a variety of reasons including formulation factors and first-pass effect."},{"id":"m7-c15","tier":"new","exam":2,"module":7,"lecture":"L10","topic":"bioavail","sub":"fabs","concept":"fabs-two-aucs","skill":"bioavail","source":"both","stem":"What is the bioavailability of a 500 mg tablet which yielded an AUC of 115 (mg/L)hr compared to a 400 mg IV bolus dose that yielded an AUC of 132 (mg/L)hr?","options":[{"t":"50%","why":"Picking this cuts the tablet area by more than the dose correction allows. The AUC ratio is {{frac:115|132}} = 0.871, and the dose ratio {{frac:400|500}} = 0.8 scales it once: 0.871 × 0.8 = 0.697, about 70 per cent, not 50."},{"t":"70%","correct":true,"why":"F = ({{frac:115|132}})({{frac:400|500}}) = 0.871 × 0.8 = 0.697, which is 70 per cent. The IV AUC is the denominator, and the IV dose is on top of the dose ratio because the tablet was the larger dose."},{"t":"85%","why":"Picking this stops at the AUC ratio. {{frac:115|132}} = 0.871 compares the areas but not the doses: the tablet area came from 500 mg against 400 mg IV, so it is scaled by {{frac:400|500}} = 0.8, giving 0.697, about 70 per cent."},{"t":"92%","why":"Picking this moves F up for the larger tablet dose instead of down. Inverting the dose ratio gives ({{frac:115|132}})({{frac:500|400}}) = 1.09, above 1, which an absolute F cannot be. The IV dose goes on top; a larger oral dose makes F smaller, not larger: 0.697."}],"steps":[{"k":"setup","t":"F = ({{frac:AUCpo|AUCIV}})({{frac:DIV|Dpo}}) = ({{frac:115|132}})({{frac:400 mg|500 mg}})","why":"Absolute bioavailability compares the tablet with the IV bolus, so the IV AUC is the denominator of the AUC ratio. The doses differ, 500 mg oral against 400 mg IV, so the dose ratio is needed, with the IV dose on top to remove the larger tablet dose."},{"k":"unit","t":"Both AUCs are in (mg/L)hr and both doses in mg, so every unit cancels and F is dimensionless","why":"The AUC ratio is (mg/L)hr over (mg/L)hr and the dose ratio is mg over mg; nothing remains, so F is a pure fraction between 0 and 1 and can be written as a decimal or as a per cent."},{"k":"algebra","t":"{{frac:115|132}} = 0.871; {{frac:400|500}} = 0.8; F = 0.871 × 0.8 = 0.697","why":"The tablet area is 0.871 of the IV area, but it came from a larger dose, 500 mg against 400 mg, so the area is scaled by 0.8 to what a 400 mg tablet would have given: 0.697 of the IV area."},{"k":"round","t":"F = 0.697 = 69.7%, rounded to 70%; the AUC ratio alone would be 87%, and ({{frac:115|132}})({{frac:500|400}}) = 1.089 is over 1","why":"The options are in whole per cents, so 0.697 is rounded to 70 per cent. Inverting the dose ratio gives 109 per cent, more than all of the dose, which is impossible."}],"givens":[["Dpo","500 mg","the denominator of the dose ratio"],["AUCpo","115 (mg/L)hr","the numerator of the AUC ratio"],["DIV","400 mg","the numerator of the dose ratio"],["AUCIV","132 (mg/L)hr","the denominator of the AUC ratio"]],"check":{"t":"F cannot exceed 1, so the dose ratio must make the tablet area smaller, not larger: 400 over 500, not 500 over 400, which gives 1.089. The AUC ratio alone, 0.871, ignores that the tablet dose was larger; 0.697 lies below it."},"teach":[{"h":"The idea","t":"Compare the AUCs with the IV AUC underneath, then correct for the doses with the IV dose on top."}],"cite":"7a---Bioavailability-and-Bioequivalence.pdf, PollEv question page 19; transcript 09-30","quote":"Most of you guys thought 70%. OK. OK. Straightforward. OK. So, If I change up the numbers, we're all gonna get this, right? Cause there's not a whole lot I can do with the wording here.","audit":"Her PollEv question with its four options; the class answer she confirmed was 70%. (115/132)(400/500) = 0.69697."},{"id":"cq2-4","tier":"new","exam":1,"module":3,"lecture":"L04","topic":"infusion","sub":"load","concept":"loading-purpose","skill":"recall","dupOf":"inf-c11","stem":"Why is a loading dose used?","options":[{"t":"To immediately obtain a therapeutic plasma concentration","correct":true,"why":"An infusion alone takes three to five half-lives to reach steady state. A loading dose puts the steady-state amount, Css × VD (the steady-state concentration times the apparent volume of distribution), into the body at once, so the therapeutic level is there from the start and the infusion then holds it."},{"t":"To reduce the adverse effects associated with the drug","correct":false,"why":"Picking this reads a dosing device as a safety device. A loading dose raises the concentration faster, which brings any concentration-related adverse effect forward rather than reducing it. The plateau Css = {{frac:R|Cl}} depends on the infusion rate R and clearance Cl, not on the loading dose."},{"t":"To improve patient adherence","correct":false,"why":"This answer confuses a kinetic quantity with a behavioural one. Adherence concerns how reliably a patient takes a regimen over days or weeks. A loading dose is a one-time amount, Css × VD, chosen so the target level exists from the first minute; it says nothing about how reliably later doses are taken."},{"t":"To reduce the elimination half-life","correct":false,"why":"Picking this reads the half-life as something a dose can shorten. The half-life is a property of the drug and the patient, set by k = {{frac:Cl|VD}}, where k is the elimination rate constant. No dose changes k, Cl or VD; a loading dose only changes how soon the target concentration is reached."}],"teach":[{"h":"The idea","list":["The time to steady state is set by the half-life alone: three to five half-lives, whatever the rate.","When that wait is too long, a loading dose DL = Css × VD supplies the steady-state amount at once.","DL = Css × VD because Cp = {{frac:DB|VD}}: the amount in the body at the plateau is the target concentration times the volume it spreads through.","With the right loading dose the level stays flat at Css: the bolus part falls as C0e^(−kt) while the infusion part rises as Css(1 − e^(−kt)), and the two add to Css at every time."]}],"cite":"Canvas Quiz 2 (Modules 2–3), question 4; 3IntravenousInfusions.pdf, slide \"IV Bolus Loading Dose and Continuous IV Infusion\""},{"id":"cq3-2","tier":"new","exam":2,"module":4,"lecture":"L05","topic":"clearance","sub":"clcalc","concept":"clearance-halflife-inverse","skill":"apply","stem":"If there is an increase in the total body clearance of an agent due to renal dysfunction, what is the expected change to the elimination half-life of that agent?","options":[{"t":"The elimination half-life will decrease.","correct":true,"why":"t½ = {{frac:0.693 × VD|Cl}}. With VD unchanged, a larger clearance means a shorter half-life. The item asks for the direction that follows from the stated change in clearance, whatever caused it."},{"t":"The elimination half-life will increase.","correct":false,"why":"A longer half-life goes with a smaller clearance. Renal dysfunction usually lowers clearance, which is what makes this option tempting; the stem states that clearance increased, and the half-life follows the clearance."},{"t":"The elimination half-life will not change.","correct":false,"why":"Picking this treats the half-life as an independent property of the drug. It is set by two quantities: t½ = {{frac:0.693 × VD|Cl}}, with VD the volume of distribution and Cl the total body clearance. With VD held fixed, a change in Cl must move t½, and an increase in Cl shortens it."}],"note":"The stem pairs renal dysfunction with an increase in clearance. Her keyed answer follows the stated increase in clearance; it is the Cl to t½ relation that is tested, not the usual direction of renal disease.","teach":[{"h":"The idea","list":["k = {{frac:Cl|VD}} and t½ = {{frac:0.693|k}}, so t½ = {{frac:0.693 × VD|Cl}}.","Clearance up, half-life down; clearance down, half-life up, as long as VD holds.","The half-life is the time to remove half of the drug and clearance is how fast drug is removed, so faster removal takes less time."]}],"cite":"Canvas Quiz 3 (Modules 4–5), question 2; 4---Clearance-and-Elimination.pdf slide 21"},{"id":"cq3-4","tier":"new","exam":2,"module":5,"lecture":"L06","topic":"oral","sub":"peak","concept":"rates-equal-at-cmax","skill":"recall","dupOf":"fig-oral-3","stem":"Which of the following is true regarding the Cmax following oral administration?","options":[{"t":"the rate of drug absorption equals the rate of drug elimination","correct":true,"why":"At the peak the concentration is momentarily not changing, so drug is entering the body exactly as fast as it is leaving. That balance is what defines the maximum."},{"t":"the rate of drug elimination is faster than the rate of drug absorption","correct":false,"why":"Picking this takes the whole falling limb for the peak itself. Elimination faster than absorption describes every moment after the peak, when the concentration is falling. At the peak, tmax, the two rates are exactly equal; that is why the concentration stops rising there and starts to fall only afterwards."},{"t":"the rate of drug absorption is faster than the rate of drug elimination","correct":false,"why":"Picking this takes the rising limb for the peak. Absorption faster than elimination describes every moment before the peak, when more drug enters each hour than leaves and the concentration rises. At Cmax (the peak concentration) the two rates have just become equal, so the concentration is neither rising nor falling."},{"t":"drug at the absorption site has become depleted","correct":false,"why":"Picking this places the end of absorption at the peak. Absorption is still running at tmax: drug remains at the absorption site and keeps entering, which is why the fall after the peak is slower than pure elimination would be. The site empties later, and only then is the curve elimination alone."}],"teach":[{"h":"The idea","list":["Before tmax, absorption outpaces elimination and the curve rises. After tmax, elimination outpaces absorption and the curve falls.","At tmax the two rates are equal and the curve is flat for an instant.","The amount in the body changes at the rate in minus the rate out, dDB/dt = rate of absorption − rate of elimination (slide \"First-Order Absorption Model\"); at the peak that difference is zero.","Both are first order: absorption at ka times the amount at the absorption site, elimination at k times the amount in the body. The first falls as the second rises, so they cross once."]}],"cite":"Canvas Quiz 3 (Modules 4–5), question 4; 5---Pharmacokinetics-of-Oral-Absorption.pdf, slide \"Plasma Level–Time Curve\""},{"id":"cq4-3","tier":"new","exam":2,"module":6,"lecture":"L09","topic":"multoral","sub":"oparam","concept":"raise-css-by-regimen","skill":"apply","dupOf":"m6b-c16","source":"both","stem":"Which is the best option to increase the steady-state concentration in a dosing regimen?","options":[{"t":"increase the dosing interval","correct":false,"why":"A longer interval gives elimination more time between doses, so the steady-state level falls and the swing between peak and trough grows. This is the direction many pick; it is the opposite of what is asked."},{"t":"decrease the dosing interval","correct":true,"why":"Dosing more often puts the next dose in before as much of the last has left, so the plateau rises. Of the two things a regimen can change, the dose and the interval, this is the interval change that raises the level."},{"t":"increase the clearance","correct":false,"why":"Picking this treats clearance as a dosing choice. Clearance (Cl) belongs to the patient; a regimen can change only the dose and the interval. A higher clearance would lower the level: Cavg∞ (the average steady-state concentration) = {{frac:F D0|Cl × τ}}, with F the bioavailable fraction, D0 the dose and τ the interval."},{"t":"decrease the elimination half-life","correct":false,"why":"Picking this treats the half-life as something the prescriber sets. The half-life is a property of the drug in the patient, {{frac:0.693|k}} with k the elimination rate constant, not a dosing choice. A shorter half-life would also mean faster loss between doses and a lower steady-state level, the opposite of what is asked."}],"teach":[{"h":"The idea","list":["Her rule: the only things a regimen can change are the size of the dose and the dosing interval; clearance and half-life are not choices.","Slide \"Altering Dosing Interval\": decreasing the interval increases steady-state concentrations and decreases the peak-to-trough fluctuation, at the cost of compliance.","Cmax∞, Cmin∞ and Cavg∞ all go up; the trough sits closer to the peak because the next dose arrives before the level has fallen as far.","Cavg∞ = {{frac:F D0|Cl × τ}} has τ in the denominator, and a shorter interval leaves more of each dose when the next arrives, so the accumulation factor {{frac:1|1 − e^(−kτ)}} rises."]},{"h":"Her Example 1 three ways","fig":"dose_interval","list":["Every 8 hours, every 4 hours, and double the dose every 8 hours: the shorter interval raises all three lines and pulls the trough toward the peak."]}],"cite":"Canvas Quiz 4 (Modules 6–7a), question 3; 6a---Multiple-Oral-Doses.pdf, slides \"Altering Steady-State Concentrations\" and \"Altering Dosing Interval\"; 09.28 lecture"},{"id":"cq4-5","tier":"new","exam":2,"module":6,"lecture":"L09","topic":"multoral","sub":"oparam","concept":"increase-dose-effects","skill":"apply","dupOf":"m6b-c14","source":"both","stem":"Which of the following results if the dose is increased on a medication that is to be administered orally at regularly repeating intervals?","options":[{"t":"Increased steady-state tmax","correct":false,"why":"Picking this reads a larger dose as a slower climb to the peak. tmax∞ (the time of the peak within an interval at steady state) depends on ka (the absorption rate constant), k (the elimination rate constant) and τ (the dosing interval) only. The dose scales the curve, not the peak time."},{"t":"Decreased rate of absorption","correct":false,"why":"Picking this treats the absorption rate constant as adjustable by the dose. ka (the absorption rate constant) is a property of the drug and the dosage form. A larger dose means more drug absorbed per hour at the same ka, since the rate is ka × the amount at the absorption site."},{"t":"Increased steady-state Cmax","correct":true,"why":"Every concentration in the regimen scales with the dose, so the steady-state peak rises in proportion. Slide \"Altering Dose\": increasing the dose increases steady-state concentrations and the peak-to-trough fluctuation."},{"t":"Decreased clearance","correct":false,"why":"Picking this takes the amount cleared per hour for the clearance. Clearance (Cl) is the volume of plasma cleared of drug per hour, a property of the patient and the drug. A larger dose raises the concentration and so the amount removed per hour, Cl × concentration, but Cl itself does not change."}],"teach":[{"h":"The idea","list":["Dose up: higher Cmax, Cmin and Cavg, a bigger swing between peak and trough, usually no change in compliance.","Dose does not move tmax, ka or clearance.","The swing grows because Dmax∞ − Dmin∞ equals the dose, so the gap between peak and trough scales with the dose. The trough stays the same fraction of the peak."]}],"cite":"Canvas Quiz 4 (Modules 6–7a), question 5; 6a---Multiple-Oral-Doses.pdf, slides \"Poll EV\" (page 1) and \"Altering Dose\"; 09.28 lecture"},{"id":"cq4-7","tier":"new","exam":2,"module":6,"lecture":"L08","topic":"intermit","sub":"why","concept":"intermittent-assumptions","skill":"recall","source":"both","stem":"Which of the following best describes the assumptions associated with intermittent IV infusions?","options":[{"t":"all drugs are better tolerated as IV bolus doses compared to IV infusion","correct":false,"why":"The rationale slide says the reverse: many drugs are better tolerated when infused slowly over time than as an IV bolus. The word \"all\" also overstates it."},{"t":"intermittent IV infusions decrease elimination half-life which leads to increased efficacy","correct":false,"why":"Picking this treats a route of administration as a change to a drug property. The elimination half-life is {{frac:0.693|k}}, with k (the elimination rate constant) set by clearance and volume of distribution, both properties of the drug in the patient. Infusing rather than injecting changes how fast drug enters, not how fast it leaves."},{"t":"concentrations of drug in the body following multiple infusions are additive","correct":true,"why":"This is superposition applied to infusions: each infusion is worked as a single infusion, decays from its own end, and the concentrations are added. It is the assumption behind every two-infusion calculation."},{"t":"intermittent IV infusion is the best way to very rapidly achieve high drug concentrations","correct":false,"why":"Picking this reverses the rationale for infusing. Spreading a dose over time is done to prevent high concentrations and their side effects; the concentration at the end of an infusion is lower than the peak the same dose would give as a bolus. A loading bolus, not an infusion, reaches a high level quickly."}],"teach":[{"h":"The idea","list":["Rationale slide: prevent high drug concentrations and accompanying side effects; many drugs are better tolerated when infused slowly over time than by IV bolus.","Assumption: concentrations from successive infusions add (superposition), and each infusion follows the single-infusion equation with the same R, k and VD.","They add because elimination is first order: drug from each infusion is removed at the same fraction per hour whether or not the other is present (slide \"Superposition\")."]}],"cite":"Canvas Quiz 4 (Modules 6–7a), question 7; 6---Repetitive-IV-Bolus-and-Intermittent-IV-Infusions.pdf, slides \"Rationale\" and \"Administering One or More Doses by IV Infusion\"; 09.28 lecture"},{"id":"cq4-10","tier":"new","exam":2,"module":7,"lecture":"L10","topic":"bioavail","sub":"defs","concept":"absolute-vs-relative","skill":"recall","dupOf":"m7-c03","source":"slide","stem":"Which term describes the comparison of the bioavailability of the active drug in the systemic circulation following extravascular administration with the bioavailability of the same drug following intravenous administration?","options":[{"t":"Absolute Bioavailability","correct":true,"why":"The stem is the slide definition word for word. Absolute means measured against the intravenous dose, where all of the drug is in the circulation."},{"t":"Bioequivalence","correct":false,"why":"Picking this takes a two-product comparison for the comparison against IV. Bioequivalence compares a test product with a reference product of the same drug in both rate and extent, and neither product is the IV dose. The stem names intravenous administration as the comparator, which is the mark of absolute bioavailability."},{"t":"Relative Bioavailability","correct":false,"why":"Picking this reads the IV comparison as a comparison between two ordinary products. Relative bioavailability compares two formulations or routes against a reference that is not the IV dose, such as a tablet against an oral solution. The stem sets the extravascular dose against the same drug given intravenously, which makes the comparison absolute."},{"t":"Drug Product Performance","correct":false,"why":"Picking this takes the broad opening term for the specific comparison. Drug product performance is the release of the drug substance from the drug product leading to bioavailability, and it describes one product on its own. The stem describes a ratio between an extravascular route and the IV route, which is absolute bioavailability."}],"teach":[{"h":"The idea","list":["Absolute: against IV. Relative: against another product or route. Bioequivalence: two products of the same drug compared in both rate and extent.","The IV dose is the reference because the whole IV dose enters the circulation, so its F is 1; Fabs = {{frac:AUCpo|AUCIV}} × {{frac:DIV|Dpo}} cannot come out above 1.","She quotes the slide definition and asks for the term; the words \"intravenous administration\" settle this one."]}],"cite":"Canvas Quiz 4 (Modules 6–7a), question 10; 7a---Bioavailability-and-Bioequivalence.pdf, slide \"Absolute Bioavailability\" (page 5)"},{"id":"cq5-1","tier":"new","exam":3,"module":9,"lecture":"L11","topic":"pkpd","sub":"thalf","concept":"thalf-double-teff","skill":"apply","dupOf":"pd-c20","source":"slide","stem":"For a drug that displays linear, first-order pharmacokinetics, what is the impact on duration of activity if there is an increase in elimination half-life?","options":[{"t":"There is a no change to the duration of activity.","correct":false,"why":"Picking this treats the duration as set by the dose alone. In teff = 1.44 t½ ln({{frac:D0|VD × Ceff}}) the half-life multiplies the whole expression, so a longer t½ with the same dose and volume keeps the level above the minimum effective concentration (MEC) for longer."},{"t":"Duration of activity will increase.","correct":true,"why":"A longer half-life means slower elimination, so the level takes longer to fall from C0 to the MEC. teff is in direct proportion to t½: twice the half-life, twice the duration, as when decreased renal or hepatic function prolongs t½."},{"t":"Duration of activity will decrease.","correct":false,"why":"Picking this reverses the direction. A longer t½ means a smaller elimination rate constant k, so the level falls more slowly and stays at or above the MEC for longer, not shorter."}],"teach":[{"h":"The idea","list":["teff = 1.44 t½ ln({{frac:D0|VD × Ceff}}): t½ multiplies everything, so teff changes in direct proportion to the half-life.","The dose sits inside the logarithm: doubling the dose adds one half-life to teff; it does not double it.","Decreased renal or hepatic elimination prolongs t½, prolongs the effect, and raises the possibility of toxicity."]}],"cite":"Canvas Quiz 5 (Modules 7b and 8), question 1; 7b---Pharmacokinetics-and-Pharmacodynamics.pdf, slides 9 \"Effect of Dose and Elimination Half-life on Duration of Activity\" and 10 \"Effect of Elimination Half-life on Duration of Activity\""},{"id":"cq5-6","tier":"new","exam":3,"module":8,"lecture":"L12","topic":"nonlin","sub":"linear","concept":"nl-saturation-features","skill":"recall","dupOf":"nl-c04","source":"slide","stem":"Which of the following is true regarding drugs that display nonlinear pharmacokinetics?","options":[{"t":"Parameters do not change when different or multiple doses of a drug are given","correct":false,"why":"Picking this takes the definition of linear pharmacokinetics for nonlinear. With a nonlinear drug an increased dose or chronic administration changes the parameters: clearance falls and the half-life lengthens as the concentration rises."},{"t":"Half-life changes as dose is increased","correct":true,"why":"With saturable elimination t½ = VD({{frac:0.693|Vmax}})(KM + Cp), so a larger dose, giving a higher Cp, gives a longer half-life. It is one of the characteristics of saturation kinetics."},{"t":"The principle of superposition applies at steady-state.","correct":false,"why":"Picking this carries a linear rule into saturation kinetics. Superposition adds the curves of separate doses, which needs each dose to lose the same fraction per hour; once elimination saturates, a later dose is cleared more slowly, so the curves do not simply add."},{"t":"The AUC is proportional to the amount of bioavailable drug.","correct":false,"why":"Picking this describes dose-independent kinetics. With saturable elimination the AUC (area under the curve) is disproportional to the amount of bioavailable drug: past a certain dose it rises more than in proportion."}],"teach":[{"h":"The idea","list":["Linear: parameters such as half-life and clearance do not change when different or multiple doses are given.","Saturation kinetics: half-life changes as dose is increased, and the AUC is disproportional to the amount of bioavailable drug.","t½ = VD({{frac:0.693|Vmax}})(KM + Cp) rises with Cp; Cl = {{frac:Vmax|KM + Cp}} falls with Cp."]}],"cite":"Canvas Quiz 5 (Modules 7b and 8), question 6; 8 - Nonlinear PK.pdf, slides 3 \"Linear vs. Nonlinear Pharmacokinetics\" and 6 \"Saturation Kinetics\""},{"id":"fig-ord-3","skill":"read","tier":"new","exam":1,"module":1,"lecture":"L01","topic":"orders","sub":"plots","concept":"order-from-semilog-straight","source":"both","stem":"Plasma concentration is plotted against time on the axis shown, and the points fall on a straight line. What does this indicate about the process removing the drug?","img":"ord_semilog_straight","options":[{"t":"It is first order","correct":true,"why":"The concentration axis runs 1, 10, 100, 1000, so each equal step up the axis multiplies the concentration by ten. A straight line on a multiplying axis means a constant fraction is lost per hour, which is first order."},{"t":"It is zero order","correct":false,"why":"This comes from reading the line as straight without reading the axis, and the axis is not evenly spaced: 1 to 10 covers the same distance as 100 to 1000. Her instruction is to look at the scale before judging the line."},{"t":"It is first order only if the axis is labelled as logarithmic","correct":false,"why":"The word is usually absent, which she flags directly, so this answer means waiting for a label that never arrives and classifying nothing. The tick values are the evidence: 1, 10, 100, 1000 is a decade scale whether or not anything on the figure says so."},{"t":"The order cannot be decided from a graph alone","correct":false,"why":"The shape on a stated axis is exactly what settles it, and she says a data set or a curve will be given for this purpose. Picking this treats the graph as decoration rather than as the evidence, when the axis and the line together carry the answer."}],"teach":[{"h":"The idea","list":["Read the tick values, not the line. The ticks are 1, 10, 100 and 1000, so each equal distance up the axis multiplies the concentration by ten.","First order gives ln C = ln C0 − kt, where C0 is the concentration at time zero and k the elimination rate constant.","So plotting the logarithm of concentration against time gives a straight line. An axis whose ticks step by tens plots that logarithm for you."]},{"h":"The relation","list":["On an axis of base-ten decades the relation is log C = log C0 − {{frac:kt|2.3}}, so the slope read off the figure is −{{frac:k|2.3}}, not −k.","Multiplying that slope by 2.3 recovers the elimination rate constant."]}],"quote":"I expect for you, because you will see graphs like this, and this word will not be over here most of the time. you’ve got to pay attention to the axis","audit":"Redrawn from the points on her semi-logarithmic slide: 200, 93, 44, 21, 10, 4.9 and 2.3 at hours 0 to 6.","teachImg":"slide_Introduction_p24","cite":"Introduction.pdf slide 21"},{"id":"fig-ord-4","skill":"order","tier":"new","exam":1,"module":1,"lecture":"L01","topic":"orders","sub":"plots","concept":"order-from-semilog-curve","source":"both","stem":"Plasma concentration is plotted against time on the axis shown. What does the shape of this line indicate about the process removing the drug?","img":"ord_semilog_curve","options":[{"t":"It is zero order","correct":true,"why":"The axis steps by factors of ten, which is the axis that straightens a first-order decline. This line bends away downward instead, so the process is not first order; a constant amount lost per hour drops through the lower decades faster and faster, giving exactly this plunge."},{"t":"It is first order","correct":false,"why":"First order is what this axis straightens, so a first-order decline would be a straight line here. Choosing this reads the axis correctly and then ignores what the line does on it, which reverses the test: on a decade axis, straight means first order and bent means it is not."},{"t":"The drug follows a two-compartment model","correct":false,"why":"A two-compartment decline bends the other way, steep first and then shallower, because the fast distribution phase finishes and the slower elimination phase takes over. This line does the opposite, starting shallow and steepening, so reading it as two compartments has the direction backwards."},{"t":"The concentrations were measured incorrectly","correct":false,"why":"A smooth, regular bend is a kinetic signal rather than noise; measurement error scatters points about a line instead of curving them consistently in one direction. Reaching for this dismisses the shape of the curve, which is the evidence."}],"teach":[{"h":"The idea","list":["A decade axis, with ticks that step by tens, plots the logarithm of concentration.","First order becomes a straight line on it, because ln C falls by a constant amount each hour. Zero order does not, because C itself falls by a constant amount each hour."]},{"h":"Why zero order plunges at the end","list":["Under C = C0 − k0t the same amount leaves every hour, so the last of the drug disappears over the same time as the first of it.","Near the bottom of the axis, that fixed amount is a huge fraction of what is left. On a multiplying axis, a huge fraction lost is a long way down, so the line steepens."]},{"h":"The two-step test","list":["Read the axis, then read the line. Evenly spaced axis plus straight line: zero order. Decade axis plus straight line: first order. Either axis with a bend: the other order."]}],"audit":"A constant-rate decline on the same decade axis as the straight-line figure.","teachImg":"slide_Introduction_p20","cite":"Introduction.pdf slides 17–21"},{"id":"fig-ord-5","skill":"read","tier":"new","exam":1,"module":1,"lecture":"L01","topic":"orders","sub":"plots","concept":"semilog-axis-recognition","source":"transcript","stem":"A concentration axis is marked 1, 10, 100, 1000 at equal spacing, with no other label. Which statement about that axis is correct?","img":"ord_semilog_straight","options":[{"t":"a straight line on this axis indicates a first-order process","correct":true,"why":"Moving one tick multiplies the value by ten every time, from 1 to 10 and again from 100 to 1000. That is what a logarithmic axis does: it turns multiplication into equal distance, which is why a fixed-fraction process draws a straight line on it."},{"t":"the axis is evenly spaced in concentration","why":"Selecting this reads the evenly spaced tick marks as evenly spaced values. The marks are equally far apart, but the values at them multiply by ten at each step: 1 to 10 adds nine units and 100 to 1000 adds nine hundred, so equal distances are equal multiples, not equal amounts."},{"t":"the axis cannot be treated as logarithmic unless it is labelled as such","why":"Picking this waits for a label that is usually missing. The tick values are the evidence: 1, 10, 100, 1000 step by a factor of ten, which only a logarithmic axis does, so the axis is treated as logarithmic whether or not the word log is printed beside it."},{"t":"a straight line on this axis indicates a zero-order process","why":"This answer reads the straightness without reading the axis. Zero order loses the same amount per hour and is straight only where equal distances are equal amounts; on this axis equal distances are equal multiples, so a straight line means a fixed fraction lost per hour, which is first order."}],"teach":[{"h":"The idea","list":["Read two neighbouring tick values and divide. If the answer is the same multiple each time, such as ten, the axis is logarithmic.","If the difference is the same each time, such as twenty-five, the axis is evenly spaced.","The word will not be printed on most figures; the tick values are always there, so they are the reliable evidence."]},{"h":"What follows once it is recognised","list":["On a decade axis, a straight line means first order. The slope is −{{frac:k|2.3}} for base-ten decades, where k is the elimination rate constant.","On an evenly spaced axis, a straight line means zero order. The slope is −k0 directly, where k0 is the zero-order rate constant."]}],"quote":"Notice that it doesn’t say. Log","audit":"Drawn with no axis label, the case she describes.","teachImg":"slide_Introduction_p23","cite":"Introduction.pdf slides 20–21"},{"id":"fig-oral-2","skill":"read","tier":"new","exam":2,"module":5,"lecture":"L06","topic":"oral","sub":"conc","concept":"oral-terminal-slope","source":"both","stem":"The concentrations after a single oral dose are plotted on the axis shown. What can be obtained from the straight portion at the right-hand end of the curve?","img":"oral_semilog","options":[{"t":"The elimination rate constant","correct":true,"why":"By the right-hand end absorption is essentially complete, so the only process still changing the concentration is elimination. On an axis whose ticks step by ten, that single first-order process draws a straight line whose slope carries k."},{"t":"The absorption rate constant","correct":false,"why":"Absorption governs the rising portion and has finished by the time the tail is straight. Selecting this swaps the two constants; ka is obtained from the early part of the curve, usually by subtracting the extrapolated terminal line from the measured points."},{"t":"The bioavailable fraction","correct":false,"why":"F scales the whole curve up or down and cannot be recovered from a slope, which is unchanged by scaling. This answer comes from reading a height question off a steepness, and F is normally obtained by comparing areas under the curve."},{"t":"The time of the peak","correct":false,"why":"tmax is read on the horizontal axis where the curve turns over, well to the left of the straight tail. Reaching for this takes a feature of the rising part of the curve from the part where the rise is long finished."}],"teach":[{"h":"The idea","list":["The curve is the difference of two exponentials. The absorption term dies away faster than the elimination term.","Once the absorption term has gone, only the elimination term is left, and a single exponential is a straight line on a decade axis."]},{"h":"The relation","list":["In the tail, ln C falls in a straight line with time, at slope −k. Applying t1/2 = {{frac:0.693|k}} gives the elimination half-life.","A half-life written with no subscript means the elimination half-life; the absorption half-life is always labelled."]}],"quote":"If it’s just T1/2, then your assumption is that I’m looking for the half-life of elimination","audit":"The same parameters as the peak figure, replotted on a decade axis.","cite":"5---Pharmacokinetics-of-Oral-Absorption.pdf, slide \"Plasma Level–Time Curve\""},{"id":"fig-oral-3","skill":"apply","dupOf":"cq3-4","tier":"new","exam":2,"module":5,"lecture":"L06","topic":"oral","sub":"peak","concept":"rates-equal-at-cmax","source":"both","stem":"At the marked peak of the curve shown, what is true of the rates of absorption and elimination?","img":"oral_peak","options":[{"t":"They are equal","correct":true,"why":"The concentration stops rising and starts falling at the peak, so at that instant the amount entering per unit time matches the amount leaving. A maximum is exactly the point where the net change is zero."},{"t":"Absorption is faster than elimination","correct":false,"why":"That describes the rising portion to the left of the peak, where more drug is arriving than leaving. Choosing this reads the condition that produced the climb as though it still held at the top of it, but the climb has stopped there."},{"t":"Elimination is faster than absorption","correct":false,"why":"That describes the falling portion to the right of the peak. Selecting this reads the condition ahead of the peak rather than at it, so the direction is right but the instant is wrong."},{"t":"Absorption has finished","correct":false,"why":"Absorption is still running at the peak and continues for some time afterwards; what has happened is that elimination has caught up with it. This confuses the rates being equal with the input having stopped, which are different events at different times."}],"teach":[{"h":"The idea","list":["The curve is the net of two opposing processes. To the left of the peak, absorption outpaces elimination; to the right, elimination outpaces absorption.","At Cmax, the peak concentration, the rate of absorption equals the rate of elimination."]},{"h":"The relation","list":["Setting the rate of change to zero gives tmax = {{frac:ln(ka/k)|ka - k}}, where tmax is the time of the peak, ka the absorption rate constant and k the elimination rate constant.","Just after tmax there is still drug at the absorption site. The tail becomes elimination alone later, once the site is depleted."]}],"quote":"Right at CMax, the rate N is going to be equal to the rate out.","audit":"Drawn from her worked parameters, with the peak at 2.0 hours and 12.17 mg/L.","cite":"5---Pharmacokinetics-of-Oral-Absorption.pdf, slide \"Plasma Level–Time Curve\""},{"id":"e2r-2m","tier":"new","exam":2,"module":4,"lecture":"L05","topic":"clearance","sub":"renalmech","concept":"mechanism-from-clr","skill":"apply","source":"slide","stem":"A drug was administered as a single IV bolus dose of 10 mg/kg to a 75-kg male volunteer. The drug has an elimination half-life of approximately 5 hours and volume of distribution of 2.3 L/kg. Urine samples were collected for 48 hours and upon analysis, 630 mg was recovered. What is the probable mechanism of renal elimination?","options":[{"t":"Filtration with active secretion","correct":true,"why":"The renal clearance works out to 334.7 mL/min, well above the glomerular filtration rate of about 120 mL/min. Filtration cannot clear more plasma than it filters, so a transporter must be carrying extra drug from the blood into the tubule."},{"t":"Filtration only","why":"Picking this reads any drug found in urine as filtered. Filtration only would give a renal clearance close to 120 mL/min; 334.7 mL/min is almost three times that, so filtration alone cannot account for it."},{"t":"Filtration with tubular reabsorption","why":"Picking this compares in the wrong direction, often after leaving ClR in L/hr (20.08) instead of converting to mL/min. Reabsorption returns filtered drug to the blood and pulls renal clearance below 120 mL/min; 334.7 mL/min is above it."}],"steps":[{"k":"setup","t":"ClR = fe × ClT = 0.84 × 23.91 L/hr = 20.08 L/hr = 334.7 mL/min","why":"fe = {{frac:630|750}} = 0.84 and ClT = kVD = 0.1386 × 172.5 = 23.91 L/hr, as in the calculation for this stem. The mechanism is read in mL/min."},{"k":"algebra","t":"334.7 mL/min against GFR ≈ 120 mL/min: greater","why":"Above the filtration rate means a second process adds drug to the urine: active secretion. Filtration alone cannot clear more plasma than the glomeruli filter, about 120 mL/min."}],"teach":[{"h":"Reading the mechanism","list":["Renal clearance equal to about 120 mL/min: filtration only. Above it: filtration with active secretion. Below it: filtration with tubular reabsorption.","Convert to mL/min before comparing; 20.08 L/hr read as 20.08 points to the wrong answer."]}],"cite":"Exam 2 In-Class Review (handed out 7 Oct 2026), question 2; 4---Clearance-and-Elimination.pdf, slides \"Renal Excretion\", \"Active Secretion\" and \"Tubular Reabsorption\""},{"id":"e2r-5","tier":"new","exam":2,"module":4,"lecture":"L05","topic":"clearance","sub":"crclcalc","concept":"crcl-estimates-renal-function","skill":"recall","source":"slide","stem":"What is creatinine clearance used to estimate?","options":[{"t":"apparent volume of distribution","why":"Picking this confuses a clearance with a volume. VD is litres and describes how widely a drug spreads; creatinine clearance is mL/min and describes how much plasma the kidneys clear of creatinine each minute."},{"t":"metabolic function","why":"Picking this takes creatinine, a product of muscle metabolism, for a test of metabolism. Its clearance measures how well the kidneys remove it, and hepatic metabolism is not part of that number."},{"t":"renal function","correct":true,"why":"Creatinine is filtered by the glomerulus, so its clearance estimates the glomerular filtration rate, the usual measure of how well the kidneys work. Her slide gives 120 to 130 mL/min as normal."},{"t":"tubular reabsorption","why":"Picking this names one renal process instead of the overall function. Creatinine is filtered and also partly secreted, and its clearance estimates filtration, not the reabsorption of a particular drug."}],"teach":[{"h":"Creatinine clearance","list":["Her slide \"Creatinine Clearance/GFR\": creatinine clearance is commonly used as an estimate of GFR, the glomerular filtration rate, and is calculated by the Cockcroft-Gault equation, with 120 to 130 mL/min considered normal.","Creatinine clearance describes the patient's kidneys; a drug's renal clearance describes the drug."]}],"cite":"Exam 2 In-Class Review (handed out 7 Oct 2026), question 5; 4---Clearance-and-Elimination.pdf, slides \"Creatinine Clearance/GFR\""},{"id":"e2r-6","tier":"new","exam":2,"module":5,"lecture":"L06","multi":true,"topic":"oral","sub":"peak","concept":"oral-dose-doubling","skill":"apply","source":"slide","stem":"Which of the following would you expect with a 2-fold increase in oral dose? (Select all that apply)","options":[{"t":"Decreased AUC","why":"Picking this reverses the direction. With first-order kinetics AUC = {{frac:F D0|Cl}}, so doubling D0 doubles the area."},{"t":"Increased AUC","correct":true,"why":"AUC = {{frac:F D0|Cl}}: the dose is in the numerator and nothing else changes, so the area doubles. Her slide \"Changing Dose\" shows AUC rising in proportion to the dose."},{"t":"Decreased Cmax","why":"Picking this reverses the direction. The dose multiplies the whole oral curve, Cp = {{frac:F ka D0|VD(ka − k)}}(e^(−kt) − e^(−ka t)), so the peak rises."},{"t":"Increased Cmax","correct":true,"why":"D0 multiplies the whole curve, Cp = {{frac:F ka D0|VD(ka − k)}}(e^(−kt) − e^(−ka t)), so the peak doubles along with every other point while its time stays the same."},{"t":"Decreased tmax","why":"Picking this lets the dose move the time of the peak. tmax = {{frac:ln(ka ÷ k)|ka − k}} holds only the two rate constants, so a larger dose leaves it where it was."},{"t":"Increased tmax","why":"Picking this reads a bigger dose as taking longer to reach its peak. tmax holds only ka and k; the dose scales the curve up without shifting it in time."}],"teach":[{"h":"Changing the oral dose","list":["Cmax and AUC rise in proportion to the dose; tmax does not change, because tmax = {{frac:ln(ka ÷ k)|ka − k}} has no dose in it (her slide \"Changing Dose\").","Her Quiz 3, question 3, asked the same point as \"the time needed to reach the maximum concentration depends on the rate constants for absorption and elimination\"."]}],"cite":"Exam 2 In-Class Review (handed out 7 Oct 2026), question 6; 5---Pharmacokinetics-of-Oral-Absorption.pdf, slide \"Changing Dose\""},{"id":"e2r-8","tier":"new","exam":2,"module":7,"lecture":"L10","topic":"bioavail","sub":"defs","concept":"bioavail-rate-extent","skill":"recall","source":"slide","stem":"Which term describes the rate and extent to which the active ingredient or active moiety is absorbed from a drug product and becomes available at the site of action?","options":[{"t":"bioavailability","correct":true,"why":"This is her slide definition of bioavailability word for word: rate and extent of absorption from a drug product to the site of action."},{"t":"bioequivalence","why":"Picking this takes the comparison for the property. Bioequivalence is the absence of a significant difference in that rate and extent between two products; it needs two products, and this definition describes one."},{"t":"pharmacodynamics","why":"Picking this moves from what the body does to the drug to what the drug does to the body. Pharmacodynamics is the effect at the site of action, not how much drug arrives there."},{"t":"product performance","why":"Picking this takes the step before for the whole. Drug product performance is the release of the drug substance from the product, which leads to bioavailability; it is not the absorption itself."}],"teach":[{"h":"Her four definitions","list":["Drug product performance: the release of the drug substance from the drug product leading to bioavailability.","Bioavailability: the rate and extent to which the active ingredient or active moiety is absorbed from a drug product and becomes available at the site of action. Extent is read from AUC, rate from tmax.","Absolute bioavailability compares extravascular with IV; relative bioavailability compares two extravascular products.","Bioequivalence: no significant difference in rate and extent between two products."]}],"cite":"Exam 2 In-Class Review (handed out 7 Oct 2026), question 8; 7a---Bioavailability-and-Bioequivalence.pdf, slide \"Bioavailability\""},{"id":"e2r-9","tier":"new","exam":2,"module":6,"lecture":"L09","topic":"multoral","sub":"oparam","concept":"raise-css-by-regimen","skill":"apply","source":"slide","stem":"Which of the following would be expected following a decrease in the dosing interval with no change to the dose?","options":[{"t":"decreased MTC","why":"Picking this treats the toxic threshold as something the regimen moves. MTC, the minimum toxic concentration, belongs to the drug; a regimen changes where the levels sit relative to it, not the threshold itself."},{"t":"increased fluctuations between peak to trough concentrations","why":"Picking this takes the bullet for increasing the interval. A shorter interval leaves less time for the level to fall, so the trough sits closer to the peak and fluctuation decreases."},{"t":"increased patient compliance","why":"Picking this reverses her slide: more frequent doses decrease patient compliance. A longer interval is the change that increases compliance."},{"t":"increased steady-state concentrations","correct":true,"why":"Her slide \"Altering Dosing Interval\": decreasing the dosing interval increases steady-state concentrations. Each dose arrives before as much of the last has left, so Cmax∞, Cmin∞ and Cavg∞ all rise."}],"teach":[{"h":"Her slide \"Altering Dosing Interval\"","list":["Increasing the interval: decreased steady-state concentrations, increased fluctuations between peak and trough, increased patient compliance.","Decreasing the interval: increased steady-state concentrations, decreased fluctuations between peak and trough, decreased patient compliance.","She builds the distractors from the opposite list, so each wrong option here is a bullet from the other half of the slide or a property of the drug."]}],"cite":"Exam 2 In-Class Review (handed out 7 Oct 2026), question 9; 6a---Multiple-Oral-Doses.pdf, slide \"Altering Dosing Interval\""},{"id":"e2r-12","tier":"new","exam":2,"module":5,"lecture":"L06","topic":"oral","sub":"conc","concept":"oral-curve-phases","skill":"recall","source":"slide","stem":"Which of the following is true regarding the absorption phase following oral administration?","options":[{"t":"drug at the absorption site has become depleted","why":"Picking this names the elimination phase, after absorption is complete. During the absorption phase drug is still arriving from the gut faster than it leaves."},{"t":"the rate of drug elimination is faster than the rate of drug absorption","why":"Picking this describes the post-absorption phase after the peak, when the concentration falls although some drug is still being absorbed."},{"t":"the rate of drug absorption is faster than the rate of drug elimination","correct":true,"why":"Before the peak more drug enters from the absorption site each hour than is eliminated, so the concentration rises. That rising limb is the absorption phase."},{"t":"the rate of drug absorption equals the rate of drug elimination","why":"Picking this takes one instant for a phase. The two rates are equal only at tmax, the peak; the absorption phase is the whole stretch before it."}],"teach":[{"h":"The three phases of the oral curve","list":["Absorption phase, before the peak: absorption faster than elimination, so the level rises.","At the peak, tmax: the two rates are equal.","Post-absorption phase, after the peak: elimination faster, with some drug still being absorbed. Elimination phase: absorption site depleted, elimination only.","Her Quiz 3, question 4, asked the peak: at Cmax the rate of absorption equals the rate of elimination."]}],"cite":"Exam 2 In-Class Review (handed out 7 Oct 2026), question 12; 5---Pharmacokinetics-of-Oral-Absorption.pdf, slide \"Example of a concentration-time profile following extravascular administration\""},{"id":"e2r-14","tier":"new","exam":2,"module":4,"lecture":"L05","topic":"clearance","sub":"clcalc","concept":"clearance-halflife-inverse","skill":"apply","source":"slide","stem":"If there is an decrease in the total body clearance of an agent due to renal dysfunction, what is the expected change to the elimination half-life of that agent?","options":[{"t":"the elimination half-life will decrease","why":"Picking this moves the half-life with clearance instead of against it. t½ = {{frac:0.693 × VD|Cl}}: clearance is in the denominator, so a smaller clearance gives a longer half-life."},{"t":"the elimination half-life will increase","correct":true,"why":"t½ = {{frac:0.693 × VD|Cl}}. With VD unchanged, lower clearance means slower removal, so it takes longer for half of the drug to leave."},{"t":"the elimination half-life will not change","why":"Picking this treats the half-life as fixed for a drug. It depends on clearance and VD, so a fall in clearance must lengthen it."}],"teach":[{"h":"Clearance and half-life","list":["k = {{frac:Cl|VD}} and t½ = {{frac:0.693|k}}, so t½ = {{frac:0.693 × VD|Cl}}: clearance down, half-life up.","Her Quiz 3, question 2, asked the reverse wording, an increase in clearance due to renal dysfunction, keyed \"decrease\". She varies the direction, so read the stem."]}],"cite":"Exam 2 In-Class Review (handed out 7 Oct 2026), question 14; 4---Clearance-and-Elimination.pdf slide 21"},{"id":"pd-c01","tier":"new","exam":3,"module":9,"lecture":"L11","topic":"pkpd","sub":"pd","concept":"pd-definition","skill":"recall","source":"slide","stem":"Which term describes the relationship between drug concentration at the site of action (receptor) and the observed pharmacologic response?","options":[{"t":"Pharmacodynamics","correct":true,"why":"Pharmacodynamics starts where pharmacokinetics stops: it takes the concentration at the receptor and links it to the response that concentration produces, which is what the drug does to the body once it arrives."},{"t":"Pharmacokinetics","why":"Choosing this takes the half of the relationship that comes first. Pharmacokinetics describes how the dose becomes a concentration over time; the response that concentration produces at the receptor is pharmacodynamics."},{"t":"Bioavailability","why":"Choosing this takes the arrival of the drug for its effect. Bioavailability is the rate and extent to which the active ingredient is absorbed and becomes available at the site of action; it ends where the receptor response begins."},{"t":"Duration of activity","why":"Choosing this takes one measure of the response for the whole relationship. Duration of activity, teff, is the time the plasma level stays at or above the minimum effective concentration; pharmacodynamics is the concentration–response link itself."}],"teach":[{"h":"Pharmacodynamics and exposure–response","list":["Pharmacodynamics (PD): the relationship between drug concentration at the site of action, the receptor, and the observed pharmacologic response.","Pharmacokinetics (PK) turns the dose into a concentration over time; PD turns that concentration into a response.","The PK–PD relationship is also called the exposure–response, concentration–response or concentration–effect relationship.","Exposure–response information is used to determine safety and efficacy in drug approval, to understand benefit–risk, and to derive dosing information."]}],"cite":"7b---Pharmacokinetics-and-Pharmacodynamics.pdf, slide 3 \"Pharmacodynamics\""},{"id":"pd-c02","tier":"new","exam":3,"module":9,"lecture":"L11","multi":true,"topic":"pkpd","sub":"pd","concept":"exposure-response-names","skill":"recall","source":"slide","stem":"The relationship between pharmacokinetics (PK) and pharmacodynamics (PD) is also referred to as which of the following? (Select all that apply)","options":[{"t":"exposure–response relationship","correct":true,"why":"Exposure is the pharmacokinetic side and response the pharmacologic observation. Joining them is the PK–PD relationship under its most common name."},{"t":"concentration–response relationship","correct":true,"why":"This names the same link with the plasma concentration as the measure of exposure: as the concentration at the receptor rises, the response rises toward its maximum."},{"t":"concentration–effect relationship","correct":true,"why":"Effect is the change in response that the concentration produces, so this third name again joins a PK quantity, the concentration, to a PD one, the effect."},{"t":"concentration–time relationship","why":"Choosing this takes the pharmacokinetic curve alone for the PK–PD link. Concentration against time, C = C0e^(−kt) after an IV bolus, has no response in it; PK–PD joins that concentration to an effect."},{"t":"rate–extent relationship","why":"Choosing this carries over the two parts of bioavailability, rate (read from tmax) and extent (read from AUC). Both describe how drug reaches the circulation, not the response it then produces."}],"teach":[{"h":"Pharmacodynamics and exposure–response","list":["Pharmacodynamics (PD): the relationship between drug concentration at the site of action, the receptor, and the observed pharmacologic response.","Pharmacokinetics (PK) turns the dose into a concentration over time; PD turns that concentration into a response.","The PK–PD relationship is also called the exposure–response, concentration–response or concentration–effect relationship.","Exposure–response information is used to determine safety and efficacy in drug approval, to understand benefit–risk, and to derive dosing information."]}],"cite":"7b---Pharmacokinetics-and-Pharmacodynamics.pdf, slide 3 \"Pharmacodynamics\""},{"id":"pd-c03","tier":"new","exam":3,"module":9,"lecture":"L11","multi":true,"topic":"pkpd","sub":"pd","concept":"exposure-response-uses","skill":"recall","source":"slide","stem":"Exposure–response information is used for which of the following? (Select all that apply)","options":[{"t":"to determine the safety and efficacy of drugs in the process of drug approval","correct":true,"why":"Exposure–response data show which exposures give the wanted effect and which give toxicity, which is the safety and efficacy evidence a drug needs for approval."},{"t":"to understand the benefit–risk of drugs during the drug approval process","correct":true,"why":"Benefit–risk weighs the effect gained at an exposure against the toxicity risked at it; both sides come from relating exposure to response, so the same data serve it."},{"t":"to derive dosing information","correct":true,"why":"A dose gives an exposure through the pharmacokinetics, and the exposure gives a response, so the dose for a target response can be worked back from the exposure–response relationship."},{"t":"to measure the absolute bioavailability of a tablet","why":"Choosing this takes a pharmacokinetic comparison for an exposure–response use. Absolute bioavailability, F = ({{frac:AUCpo|AUCIV}})({{frac:DIV|Dpo}}), compares two exposures with each other and never involves a response."},{"t":"to determine the elimination half-life of a drug","why":"Choosing this takes a pharmacokinetic parameter for a PD use. The half-life, t½ = {{frac:0.693|k}}, comes from concentrations over time alone; exposure–response information adds the response to those concentrations."}],"teach":[{"h":"Pharmacodynamics and exposure–response","list":["Pharmacodynamics (PD): the relationship between drug concentration at the site of action, the receptor, and the observed pharmacologic response.","Pharmacokinetics (PK) turns the dose into a concentration over time; PD turns that concentration into a response.","The PK–PD relationship is also called the exposure–response, concentration–response or concentration–effect relationship.","Exposure–response information is used to determine safety and efficacy in drug approval, to understand benefit–risk, and to derive dosing information."]}],"cite":"7b---Pharmacokinetics-and-Pharmacodynamics.pdf, slide 3 \"Pharmacodynamics\""},{"id":"pd-c04","tier":"new","exam":3,"module":9,"lecture":"L11","topic":"pkpd","sub":"doseresp","concept":"response-up-to-max","skill":"recall","source":"slide","stem":"Which of the following is true regarding the relationship of dose to pharmacologic effect?","options":[{"t":"Response rises with dose up to a maximum effect","correct":true,"why":"More dose puts more drug at the receptor, so more receptors are occupied and the response grows; once all are occupied the response cannot rise further, which sets the maximum effect."},{"t":"The response increases in direct proportion to the dose at every dose.","why":"Choosing this extends the steep low-dose part of the curve to every dose. Near the top a further dose change gives only a small increase, and the response levels off at its maximum."},{"t":"The onset, intensity, and duration of the effect depend on the dose alone, not on the pharmacokinetics.","why":"Choosing this drops half of the statement: onset, intensity and duration depend on the dose and the pharmacokinetics. The same dose acts longer when elimination is slower, because the level stays above the MEC longer."},{"t":"The response falls once the dose passes the dose that gives the maximum response.","why":"Choosing this reads the plateau as a peak. The curve rises to the maximum response and stays there; added dose finds no free receptors, so it adds no response, but it does not take response away."}],"teach":[{"h":"Dose, concentration and response","list":["As the dose increases, the concentration at the receptor site increases, and the response increases up to a maximum effect.","Response against dose on a linear scale rises steeply, then flattens: the same dose change gives a large increase at low doses and a small one near the maximum.","Response against log dose is a sigmoid (S-shaped) curve; the maximum is reached when all receptors become saturated.","Its middle portion is close to a straight line: effect against log concentration, with slope m.","Onset, intensity and duration of the effect depend on the dose and on the pharmacokinetics of the drug."]}],"cite":"7b---Pharmacokinetics-and-Pharmacodynamics.pdf, slide 4 \"Relationship of Dose to Pharmacologic Effect\""},{"id":"pd-c05","tier":"new","exam":3,"module":9,"lecture":"L11","topic":"pkpd","sub":"doseresp","concept":"dose-response-linear-plot","skill":"read","source":"slide","stem":"On a plot of pharmacologic response against drug dose on a linear scale, where does a given change in dose produce the smallest increase in response?","options":[{"t":"Near the maximum response","correct":true,"why":"Near the top most receptors are already saturated, so extra drug finds few receptors left to act on and the curve flattens; the dose change that gave a large rise early gives a small one here."},{"t":"At the lowest doses","why":"Choosing this reverses the two regions of the curve. At low doses the curve is steep, so a given dose change gives a large increase in response; the small increase comes near the top, where the curve flattens."},{"t":"Equally at every dose","why":"Choosing this treats the curve as a straight line. A straight line gives the same rise for the same dose step everywhere; this curve is steep early and then plateaus, so the same step does less and less."},{"t":"At the dose giving half of the maximum response","why":"Choosing this picks the middle of the curve, where it is still rising. The smallest gain per dose step is where the curve is flattest, at the top near the maximum response."}],"teach":[{"h":"Dose, concentration and response","list":["As the dose increases, the concentration at the receptor site increases, and the response increases up to a maximum effect.","Response against dose on a linear scale rises steeply, then flattens: the same dose change gives a large increase at low doses and a small one near the maximum.","Response against log dose is a sigmoid (S-shaped) curve; the maximum is reached when all receptors become saturated.","Its middle portion is close to a straight line: effect against log concentration, with slope m.","Onset, intensity and duration of the effect depend on the dose and on the pharmacokinetics of the drug."]}],"cite":"7b---Pharmacokinetics-and-Pharmacodynamics.pdf, slide 4 \"Relationship of Dose to Pharmacologic Effect\" (left figure)"},{"id":"pd-c06","tier":"new","exam":3,"module":9,"lecture":"L11","topic":"pkpd","sub":"teff","concept":"duration-term","skill":"recall","source":"slide","stem":"Which term describes the time that the plasma drug level stays at or above the minimum effective concentration (MEC) after a single dose?","options":[{"t":"Duration of action","correct":true,"why":"Duration is read along the time axis between the two crossings of the MEC: from the onset, where the rising level first reaches the MEC, to the time it falls back below it. This is teff, the duration of activity."},{"t":"Onset time","why":"Choosing this takes the start of the effect for its length. Onset time is the single moment the rising curve first reaches the MEC; duration is the whole span from there until the level falls back below the MEC."},{"t":"Intensity","why":"Choosing this reads the vertical measure for the horizontal one. Intensity is how far the peak rises above the MEC, a concentration difference; duration is a time, read along the time axis."},{"t":"Elimination half-life","why":"Choosing this takes a pharmacokinetic constant for a pharmacodynamic span. The half-life is the time for the level to fall by one-half; duration also depends on the MEC and the dose: teff = 1.44 t½ ln({{frac:D0|VD × Ceff}})."}],"teach":[{"h":"Reading the plasma level–time curve","list":["MEC (minimum effective concentration, Ceff): the lowest plasma level that gives the effect. MTC (minimum toxic concentration): the level above which toxicity appears.","Onset time: when the rising level first reaches the MEC.","Duration (teff): the time the level stays at or above the MEC.","Intensity: how far the peak rises above the MEC."]}],"cite":"7b---Pharmacokinetics-and-Pharmacodynamics.pdf, slide 4 \"Relationship of Dose to Pharmacologic Effect\" (right figure)"},{"id":"pd-c07","tier":"new","exam":3,"module":9,"lecture":"L11","topic":"pkpd","sub":"doseresp","concept":"intensity-term","skill":"read","source":"slide","stem":"On a plasma level–time curve after a single dose, which term describes how far the peak plasma level rises above the minimum effective concentration (MEC)?","options":[{"t":"Intensity","correct":true,"why":"Intensity is read vertically, from the MEC up to the peak: the higher the peak above the threshold for effect, the stronger the effect. A larger dose raises the peak and so the intensity."},{"t":"Duration","why":"Choosing this reads the horizontal measure for the vertical one. Duration is the time the level stays at or above the MEC, read along the time axis; the height of the peak above the MEC is intensity."},{"t":"Onset time","why":"Choosing this takes a time for a height. Onset time is when the rising curve first reaches the MEC, a point on the time axis; how far the peak climbs above the MEC is intensity."},{"t":"Minimum toxic concentration (MTC)","why":"Choosing this takes a fixed threshold for a measured distance. The MTC is the line above which toxicity appears; intensity is the distance from the MEC to the peak, which is kept below the MTC."}],"teach":[{"h":"Reading the plasma level–time curve","list":["MEC (minimum effective concentration, Ceff): the lowest plasma level that gives the effect. MTC (minimum toxic concentration): the level above which toxicity appears.","Onset time: when the rising level first reaches the MEC.","Duration (teff): the time the level stays at or above the MEC.","Intensity: how far the peak rises above the MEC."]}],"cite":"7b---Pharmacokinetics-and-Pharmacodynamics.pdf, slide 4 \"Relationship of Dose to Pharmacologic Effect\" (right figure)"},{"id":"pd-c08","tier":"new","exam":3,"module":9,"lecture":"L11","topic":"pkpd","sub":"doseresp","concept":"log-dose-sigmoid","skill":"read","source":"slide","stem":"Which of the following describes a plot of pharmacologic response against log dose?","options":[{"t":"A sigmoid (S-shaped) curve","correct":true,"why":"A log axis spreads out the low doses and compresses the high ones, so the response curve becomes an S: flat at the bottom, near straight in the middle, flat at the top where all receptors are saturated."},{"t":"A curve that rises steeply from zero and flattens to a plateau","why":"Choosing this describes the same data on a linear dose axis. Against dose itself the response rises steeply and flattens; taking the logarithm of the dose turns that curve into an S shape."},{"t":"A straight line at every dose","why":"Choosing this extends the middle of the curve to its ends. Only the middle portion is close to a straight line; the curve flattens at the bottom and at the top."},{"t":"A curve that rises to a peak and falls back to zero","why":"Choosing this takes the plasma level–time curve for the dose–response curve. Concentration against time rises and falls after a dose; response against log dose rises and stays at its maximum."}],"teach":[{"h":"Dose, concentration and response","list":["As the dose increases, the concentration at the receptor site increases, and the response increases up to a maximum effect.","Response against dose on a linear scale rises steeply, then flattens: the same dose change gives a large increase at low doses and a small one near the maximum.","Response against log dose is a sigmoid (S-shaped) curve; the maximum is reached when all receptors become saturated.","Its middle portion is close to a straight line: effect against log concentration, with slope m.","Onset, intensity and duration of the effect depend on the dose and on the pharmacokinetics of the drug."]}],"cite":"7b---Pharmacokinetics-and-Pharmacodynamics.pdf, slides 5 \"Typical Log Dose-versus-Pharmacologic Response Curves\" and 11 \"Summary\""},{"id":"pd-c09","tier":"new","exam":3,"module":9,"lecture":"L11","topic":"pkpd","sub":"doseresp","concept":"receptor-saturation","skill":"apply","source":"slide","stem":"What is the probable reason the pharmacologic response stops increasing at high doses?","options":[{"t":"All receptors at the site of action are saturated","correct":true,"why":"The response comes from drug acting on receptors. Once every receptor is occupied, added drug has nothing left to act on, so the response stays at its maximum however high the dose goes."},{"t":"The drug is eliminated faster at high doses","why":"Choosing this moves the plateau into the pharmacokinetics. With first-order elimination k is the same at every dose, so a larger dose still gives a proportionally higher concentration; the ceiling is at the receptor."},{"t":"The concentration at the receptor site stops rising with dose","why":"Choosing this places the limit on the concentration. As the dose increases the concentration at the receptor site keeps increasing; it is the response to that concentration that cannot rise once every receptor is occupied."},{"t":"The minimum effective concentration rises with the dose","why":"Choosing this treats the MEC as moving with the dose. The MEC is the threshold for effect and does not change with dose; a larger dose clears it by more but cannot push the response past the maximum."}],"teach":[{"h":"Dose, concentration and response","list":["As the dose increases, the concentration at the receptor site increases, and the response increases up to a maximum effect.","Response against dose on a linear scale rises steeply, then flattens: the same dose change gives a large increase at low doses and a small one near the maximum.","Response against log dose is a sigmoid (S-shaped) curve; the maximum is reached when all receptors become saturated.","Its middle portion is close to a straight line: effect against log concentration, with slope m.","Onset, intensity and duration of the effect depend on the dose and on the pharmacokinetics of the drug."]}],"cite":"7b---Pharmacokinetics-and-Pharmacodynamics.pdf, slide 11 \"Summary\""},{"id":"pd-c10","tier":"new","exam":3,"module":9,"lecture":"L11","topic":"pkpd","sub":"doseresp","concept":"effect-slope-m","skill":"read","source":"slide","stem":"In the equation E = E0 − {{frac:kmt|2.3}}, what does m represent?","options":[{"t":"The slope of effect against log concentration","correct":true,"why":"In the straight middle portion of the log curve, E = m log C + e, with m the slope. Putting in log C = log C0 − {{frac:kt|2.3}} carries m into the time equation, so the effect falls at slope {{frac:km|2.3}}."},{"t":"The mass of drug in the body at time t","why":"Choosing this reads m as an amount. The amount in the body is DB; m is a slope, the change in effect per unit change in log concentration, carried over from E = m log C + e."},{"t":"The minimum effective concentration","why":"Choosing this takes a threshold for a slope. The minimum effective concentration, Ceff, appears in the duration equation; m measures how steeply the effect changes with log concentration."},{"t":"The elimination rate constant in base-10 logarithms","why":"Choosing this folds the 2.3 into m. k is already the elimination rate constant and 2.3 converts it to base-10 logarithms; m is a separate, pharmacodynamic slope belonging to the response."}],"teach":[{"h":"Effect against time after an IV bolus","list":["E = E0 − {{frac:kmt|2.3}}: E is the effect at time t, E0 the effect at time zero, k the elimination rate constant, m the slope of effect against log concentration.","It joins the straight middle of the curve, E = m log C + e, to the first-order decline, log C = log C0 − {{frac:kt|2.3}}.","So the effect falls in a straight line with time, at slope {{frac:km|2.3}}; the 2.3 converts natural to base-10 logarithms.","A larger k or a larger m makes the effect fall faster; a longer half-life keeps it longer."]}],"cite":"7b---Pharmacokinetics-and-Pharmacodynamics.pdf, slide 5 \"Typical Log Dose-versus-Pharmacologic Response Curves\""},{"id":"pd-c11","tier":"new","exam":3,"module":9,"lecture":"L11","topic":"pkpd","sub":"doseresp","concept":"effect-declines-linearly","skill":"apply","source":"slide","stem":"Which of the following is true regarding the decline of pharmacologic effect with time after a single IV bolus dose, as described by E = E0 − {{frac:kmt|2.3}}?","options":[{"t":"It falls in a straight line, faster with a larger k","correct":true,"why":"E = E0 − ({{frac:km|2.3}})t is a straight line in t with slope {{frac:km|2.3}}. A larger k (faster elimination) or a larger m (a steeper response) makes it fall faster; a longer half-life keeps the effect longer."},{"t":"The effect declines exponentially, by the same fraction each hour","why":"Choosing this carries the concentration curve over to the effect. Concentration falls by the same fraction each hour; the effect follows log concentration, which falls in a straight line, so the effect does too."},{"t":"The rate of decline of the effect depends on m only, not on k","why":"Choosing this drops the pharmacokinetics from the slope. The slope is {{frac:km|2.3}}: k, the elimination rate constant, multiplies m, so faster elimination makes the effect fall faster."},{"t":"The effect stays at E0 until the concentration falls below Ceff","why":"Choosing this reads the minimum effective concentration as a switch on the effect. In this equation E falls steadily from E0 as t rises; Ceff instead marks the end of the duration of activity, teff."}],"teach":[{"h":"Effect against time after an IV bolus","list":["E = E0 − {{frac:kmt|2.3}}: E is the effect at time t, E0 the effect at time zero, k the elimination rate constant, m the slope of effect against log concentration.","It joins the straight middle of the curve, E = m log C + e, to the first-order decline, log C = log C0 − {{frac:kt|2.3}}.","So the effect falls in a straight line with time, at slope {{frac:km|2.3}}; the 2.3 converts natural to base-10 logarithms.","A larger k or a larger m makes the effect fall faster; a longer half-life keeps it longer."]}],"cite":"7b---Pharmacokinetics-and-Pharmacodynamics.pdf, slide 5 \"Typical Log Dose-versus-Pharmacologic Response Curves\""},{"id":"pd-c12","tier":"new","exam":3,"module":9,"lecture":"L11","topic":"pkpd","sub":"teff","concept":"ceff-meaning","skill":"read","source":"slide","stem":"In the duration-of-activity equation teff = {{frac:ln C0 − ln Ceff|k}}, with C0 = {{frac:D0|VD}}, what does Ceff represent?","options":[{"t":"The minimum effective concentration","correct":true,"why":"Ceff is the lowest plasma level that gives the effect. teff is the time C = C0e^(−kt) takes to fall from C0 to Ceff, because below Ceff the drug no longer acts."},{"t":"The minimum toxic concentration (MTC)","why":"Choosing this takes the upper threshold for the lower one. The MTC is the level above which toxicity appears; the effect lasts while the level is at or above the MEC, so the MEC is where the duration ends."},{"t":"The initial plasma concentration after the bolus","why":"Choosing this takes the start of the decline for its end. The concentration at time zero is C0 = {{frac:D0|VD}}, in the first logarithm; Ceff is the level the decline ends at."},{"t":"The steady-state concentration","why":"Choosing this carries an infusion or multiple-dose quantity into a single-dose equation. Css belongs to repeated dosing; teff is written for one IV bolus whose level falls from C0 to Ceff."}],"teach":[{"h":"Duration of activity, teff","list":["teff: the time one IV bolus keeps the plasma level at or above Ceff, the minimum effective concentration.","From C = C0e^(−kt) with C = Ceff: teff = {{frac:ln C0 − ln Ceff|k}}, where C0 = {{frac:D0|VD}}, the level just after the bolus.","With k = {{frac:0.693|t½}}: teff = 1.44 t½ ln({{frac:D0|VD × Ceff}}); 1.44 is {{frac:1|0.693}}.","The dose is inside the logarithm, so doubling it adds {{frac:ln 2|k}}, one half-life, to teff; it does not double teff.","Built for a single IV bolus, a one-compartment open model and first-order elimination."]}],"cite":"7b---Pharmacokinetics-and-Pharmacodynamics.pdf, slides 6 \"Relationship Between Dose and Duration of Activity (teff)\" and 7 \"Practice Problem\""},{"id":"pd-c15","tier":"new","exam":3,"module":9,"lecture":"L11","topic":"pkpd","sub":"teff","concept":"teff-dose-curve","skill":"read","source":"slide","stem":"On a plot of duration of activity (teff) against IV bolus dose, which of the following describes the curve?","options":[{"t":"It rises steeply, then flattens","correct":true,"why":"teff = 1.44 t½ ln({{frac:D0|VD × Ceff}}) is a logarithm of the dose: steep while doses are small, then flatter. For one such drug, teff passes 4 hours by about 4 mg/kg but is still under 6 hours at 16 mg/kg."},{"t":"A straight line through the origin","why":"Choosing this treats teff as proportional to dose. teff follows ln D0, so equal increases in dose add less and less duration."},{"t":"A sigmoid curve that levels off at a maximum duration","why":"Choosing this carries the log dose–response S-curve over to duration. Duration has no ceiling set by receptors: ln D0 keeps rising slowly, so teff keeps growing by one half-life per doubling of the dose."},{"t":"A curve that falls as the dose increases","why":"Choosing this reverses the direction. A larger dose gives a higher C0, which takes longer to fall to Ceff, so teff rises with dose; only the size of each gain shrinks."}],"teach":[{"h":"Duration of activity, teff","list":["teff: the time one IV bolus keeps the plasma level at or above Ceff, the minimum effective concentration.","From C = C0e^(−kt) with C = Ceff: teff = {{frac:ln C0 − ln Ceff|k}}, where C0 = {{frac:D0|VD}}, the level just after the bolus.","With k = {{frac:0.693|t½}}: teff = 1.44 t½ ln({{frac:D0|VD × Ceff}}); 1.44 is {{frac:1|0.693}}.","The dose is inside the logarithm, so doubling it adds {{frac:ln 2|k}}, one half-life, to teff; it does not double teff.","Built for a single IV bolus, a one-compartment open model and first-order elimination."]}],"cite":"7b---Pharmacokinetics-and-Pharmacodynamics.pdf, slide 9 \"Effect of Dose and Elimination Half-life on Duration of Activity\" (figure)"},{"id":"pd-c16","tier":"new","exam":3,"module":9,"lecture":"L11","topic":"pkpd","sub":"teff","concept":"teff-derivation","skill":"read","source":"slide","stem":"The duration-of-activity equation is C = C0e^(−kt) solved for t. Which substitutions turn it into teff = {{frac:ln C0 − ln Ceff|k}}?","options":[{"t":"C is set to Ceff, and C0 to {{frac:D0|VD}}","correct":true,"why":"Ceff = C0e^(−k teff), so e^(k teff) = {{frac:C0|Ceff}} and k teff = ln C0 − ln Ceff. C0 = {{frac:D0|VD}} because the whole bolus is in VD at time zero."},{"t":"C is set to the MTC, and C0 to {{frac:D0|VD}}","why":"Choosing this ends the duration at the toxic threshold. The effect lasts until the level falls to the minimum effective concentration; the MTC is the ceiling the peak is kept under."},{"t":"C is set to Ceff, and C0 to D0 × VD","why":"Choosing this inverts the volume relation. Concentration is amount over volume, C0 = {{frac:D0|VD}}; multiplying gives mg × L, which is not a concentration."},{"t":"C is set to half of C0, and t to t½","why":"Choosing this derives the half-life, t½ = {{frac:0.693|k}}, instead of the duration. Setting C to half of C0 gives the half-life; setting C to Ceff gives the time the drug stays effective."}],"teach":[{"h":"Duration of activity, teff","list":["teff: the time one IV bolus keeps the plasma level at or above Ceff, the minimum effective concentration.","From C = C0e^(−kt) with C = Ceff: teff = {{frac:ln C0 − ln Ceff|k}}, where C0 = {{frac:D0|VD}}, the level just after the bolus.","With k = {{frac:0.693|t½}}: teff = 1.44 t½ ln({{frac:D0|VD × Ceff}}); 1.44 is {{frac:1|0.693}}.","The dose is inside the logarithm, so doubling it adds {{frac:ln 2|k}}, one half-life, to teff; it does not double teff.","Built for a single IV bolus, a one-compartment open model and first-order elimination."]}],"cite":"7b---Pharmacokinetics-and-Pharmacodynamics.pdf, slides 6 \"Relationship Between Dose and Duration of Activity (teff)\" and 8"},{"id":"pd-c17","tier":"new","exam":3,"module":9,"lecture":"L11","multi":true,"topic":"pkpd","sub":"teff","concept":"teff-three-forms","skill":"read","source":"slide","stem":"Which of the following are true regarding the three duration-of-activity equations, teff = {{frac:2.3(log C0 − log Ceff)|k}}, teff = {{frac:ln C0 − ln Ceff|k}} and teff = 1.44 t½ ln({{frac:C0|Ceff}}), with C0 = {{frac:D0|VD}}? (Select all that apply)","options":[{"t":"All three give the same teff for the same drug and dose","correct":true,"why":"They are one relation written three ways: ln x = 2.3 log x, and {{frac:1|k}} = {{frac:t½|0.693}} = 1.44 t½. Any of them gives the same number; the choice follows whether k or t½ is given."},{"t":"The 2.3 converts base-10 logarithms to natural logarithms","correct":true,"why":"ln x = 2.303 log x, so 2.3 times a difference of base-10 logarithms is the difference of natural logarithms; the base-10 form is the natural-log form rewritten, not a different model."},{"t":"1.44 t½ equals {{frac:1|k}}","correct":true,"why":"k = {{frac:0.693|t½}}, so dividing by k is multiplying by {{frac:t½|0.693}} = 1.44 t½; that is why the third form takes the half-life directly."},{"t":"teff is directly proportional to the dose","why":"Choosing this takes the dose out of the logarithm. D0 sits inside ln, so doubling it adds one half-life to teff; doubling the dose does not double the duration."},{"t":"They apply to any route, including a single oral dose","why":"Choosing this drops the conditions they are built on. They solve C = C0e^(−kt) with C0 = {{frac:D0|VD}}, which holds for a single IV bolus in a one-compartment model, not for a dose with an absorption phase."}],"teach":[{"h":"Three forms, one relation","list":["teff = {{frac:ln C0 − ln Ceff|k}}, with C0 = {{frac:D0|VD}}: the time for the level to fall from C0 to Ceff, the minimum effective concentration.","Base-10 form: multiply by 2.3, because ln x = 2.3 log x.","Half-life form: {{frac:1|k}} = 1.44 t½, so teff = 1.44 t½ ln({{frac:D0|VD × Ceff}})."]}],"cite":"7b---Pharmacokinetics-and-Pharmacodynamics.pdf, slides 6 \"Relationship Between Dose and Duration of Activity (teff)\" and 9 \"Effect of Dose and Elimination Half-life on Duration of Activity\""},{"id":"pd-c18","tier":"new","exam":3,"module":9,"lecture":"L11","topic":"pkpd","sub":"teff","concept":"teff-conditions","skill":"recall","source":"slide","stem":"Which of the following is true regarding the conditions under which teff = 1.44 t½ ln({{frac:D0|VD × Ceff}}) gives the duration of activity?","options":[{"t":"One IV bolus, one compartment, first order","correct":true,"why":"teff is solved from C = C0e^(−kt), with C0 = {{frac:D0|VD}}. That curve holds when a single IV bolus puts the whole dose in at time zero, the drug follows a one-compartment open model, and elimination is first order with one constant k."},{"t":"A single oral dose, with F included in the dose","why":"Choosing this assumes the oral curve can be read the same way. An oral dose has an absorption phase, so the level does not start at {{frac:D0|VD}} and fall from time zero; the equation is built on the IV bolus decline."},{"t":"A constant IV infusion at steady state","why":"Choosing this carries an infusion level into a single-dose equation. At steady state the level holds at Css while the infusion runs; teff measures how long one bolus stays above Ceff as it falls."},{"t":"Any drug, whatever the order of its elimination","why":"Choosing this drops first-order elimination. The equation needs one constant k so that C = C0e^(−kt) holds; the rule that each doubling of the dose adds one half-life also rests on linear, first-order pharmacokinetics."}],"teach":[{"h":"Duration of activity, teff","list":["teff: the time one IV bolus keeps the plasma level at or above Ceff, the minimum effective concentration.","From C = C0e^(−kt) with C = Ceff: teff = {{frac:ln C0 − ln Ceff|k}}, where C0 = {{frac:D0|VD}}, the level just after the bolus.","With k = {{frac:0.693|t½}}: teff = 1.44 t½ ln({{frac:D0|VD × Ceff}}); 1.44 is {{frac:1|0.693}}.","The dose is inside the logarithm, so doubling it adds {{frac:ln 2|k}}, one half-life, to teff; it does not double teff.","Built for a single IV bolus, a one-compartment open model and first-order elimination."]}],"cite":"7b---Pharmacokinetics-and-Pharmacodynamics.pdf, slides 7 \"Practice Problem\", 9 and 12"},{"id":"pd-c19","tier":"new","exam":3,"module":9,"lecture":"L11","multi":true,"topic":"pkpd","sub":"teff","concept":"what-moves-teff","skill":"apply","source":"slide","stem":"Which of the following would be expected to lengthen the duration of activity (teff) of a single IV bolus dose? Each option changes only the quantity it names; the half-life is unchanged unless the option says otherwise. (Select all that apply)","options":[{"t":"Increasing the dose","correct":true,"why":"A larger dose raises C0 = {{frac:D0|VD}}, so the level starts further above Ceff and takes longer to fall to it: one more half-life of duration for every doubling of the dose."},{"t":"A decrease in renal function that prolongs the elimination half-life","correct":true,"why":"Decreased renal elimination prolongs t½, and teff = 1.44 t½ ln({{frac:D0|VD × Ceff}}) rises in direct proportion to t½; the possibility of toxicity rises with it."},{"t":"A decrease in hepatic function that prolongs the elimination half-life","correct":true,"why":"Metabolism in the liver is the other elimination process; less of it prolongs t½ just as decreased renal function does, so the drug is retained and teff increases in proportion."},{"t":"A higher minimum effective concentration","why":"Choosing this reverses the effect of the threshold. A higher Ceff is reached sooner on the falling curve, because ln({{frac:D0|VD × Ceff}}) gets smaller, so teff shortens."},{"t":"A larger apparent volume of distribution","why":"Choosing this reads VD as a store that holds the effect. A larger VD spreads the same dose more thinly: C0 = {{frac:D0|VD}} falls, so the level reaches Ceff sooner and teff shortens."}],"teach":[{"h":"What moves teff","list":["teff = 1.44 t½ ln({{frac:D0|VD × Ceff}}).","Longer: a larger dose (one t½ per doubling) or a longer t½ (in direct proportion), as when hepatic or renal function is decreased.","Shorter: a larger VD or a higher Ceff, each of which makes the ratio inside the logarithm smaller."]}],"cite":"7b---Pharmacokinetics-and-Pharmacodynamics.pdf, slides 9 \"Effect of Dose and Elimination Half-life on Duration of Activity\" and 10 \"Effect of Elimination Half-life on Duration of Activity\""},{"id":"pd-c20","tier":"new","exam":3,"module":9,"lecture":"L11","topic":"pkpd","sub":"thalf","concept":"thalf-double-teff","skill":"apply","source":"slide","stem":"What is the expected change in the duration of activity of a single IV bolus dose if decreased elimination doubles the elimination half-life, with the dose and the volume of distribution unchanged?","options":[{"t":"teff doubles","correct":true,"why":"In teff = 1.44 t½ ln({{frac:D0|VD × Ceff}}), t½ multiplies the whole expression and nothing else changes, so teff is directly proportional to t½: twice the half-life, twice the duration."},{"t":"teff increases by one half-life","why":"Choosing this carries the dose rule over to the half-life. Doubling the dose adds one t½ because the dose is inside the logarithm; t½ multiplies the whole expression, so doubling it doubles teff."},{"t":"teff is halved","why":"Choosing this reverses the direction. A longer half-life means slower elimination, so the level takes longer to fall to Ceff and the drug acts longer, not shorter."},{"t":"teff does not change, because the dose is the same","why":"Choosing this ties duration to the dose alone. Onset, intensity and duration depend on the dose and on the pharmacokinetics; from the same C0, a slower decline keeps the level above Ceff longer."}],"teach":[{"h":"Elimination half-life and duration","list":["Alteration of the elimination processes, excretion and metabolism, changes the t½ of the drug.","In certain disease states, pathophysiologic changes in hepatic or renal function decrease elimination, seen as a prolonged t½.","The prolonged t½ retains drug in the body, increasing the duration of activity and the possibility of toxicity.","teff = 1.44 t½ ln({{frac:D0|VD × Ceff}}): teff is directly proportional to t½, but not to the dose."]}],"cite":"7b---Pharmacokinetics-and-Pharmacodynamics.pdf, slide 9 \"Effect of Dose and Elimination Half-life on Duration of Activity\""},{"id":"pd-c21","tier":"new","exam":3,"module":9,"lecture":"L11","multi":true,"dupOf":"pd-c19","topic":"pkpd","sub":"thalf","concept":"disease-prolongs-thalf","skill":"apply","source":"slide","stem":"In certain disease states, pathophysiologic changes in hepatic or renal function decrease the elimination of a drug. Which of the following would be expected? (Select all that apply)","options":[{"t":"A prolonged elimination half-life","correct":true,"why":"Less elimination means a smaller k, and t½ = {{frac:0.693|k}}, so the half-life is prolonged; this is how the decreased elimination shows in the pharmacokinetics."},{"t":"Retention of the drug in the body","correct":true,"why":"With elimination slowed, drug leaves more slowly than before, so more of each dose remains in the body at every time after it is given."},{"t":"An increased duration of activity","correct":true,"why":"Retained drug keeps the plasma level above Ceff for longer, and teff = 1.44 t½ ln({{frac:D0|VD × Ceff}}) rises in proportion to the prolonged t½."},{"t":"An increased possibility of drug toxicity","correct":true,"why":"The same retention that lengthens the effect raises the levels that follow each dose, so the possibility of toxicity increases along with the duration of activity."},{"t":"A shorter duration of activity","why":"Choosing this reverses the direction. Decreased elimination prolongs t½, and a longer t½ lengthens teff; a shorter duration would need faster elimination, the opposite of this change."},{"t":"An increased elimination rate constant","why":"Choosing this reverses the link between elimination and k. k is the fraction eliminated per unit time; decreased elimination lowers k, which is what prolongs t½ = {{frac:0.693|k}}."}],"teach":[{"h":"Elimination half-life and duration","list":["Alteration of the elimination processes, excretion and metabolism, changes the t½ of the drug.","In certain disease states, pathophysiologic changes in hepatic or renal function decrease elimination, seen as a prolonged t½.","The prolonged t½ retains drug in the body, increasing the duration of activity and the possibility of toxicity.","teff = 1.44 t½ ln({{frac:D0|VD × Ceff}}): teff is directly proportional to t½, but not to the dose."]}],"cite":"7b---Pharmacokinetics-and-Pharmacodynamics.pdf, slide 10 \"Effect of Elimination Half-life on Duration of Activity\""},{"id":"pd-c22","tier":"new","exam":3,"module":9,"lecture":"L11","topic":"pkpd","sub":"dosefor","concept":"dose-to-double-teff","skill":"apply","source":"slide","stem":"Which of the following is true regarding the IV bolus dose needed to double the duration of activity (teff) of a drug?","options":[{"t":"The dose doubles per added half-life of teff","correct":true,"why":"D0 = Ceff × VD × e^(k teff), so each added half-life of duration doubles the dose. For an antibiotic with VD 24 L, k 0.15 hr⁻¹ and Ceff 0.2 mcg/mL, 250 mg gives 26.35 hr, about 5.7 half-lives of 4.62 hr; doubling it to 52.7 hr needs about 52 times the dose, 13 g."},{"t":"Twice the dose doubles teff","why":"Choosing this treats teff as proportional to dose. Twice the dose adds only one half-life to teff: for that antibiotic, 4.62 hr on top of a 26.35-hr duration."},{"t":"It is found from D0 = {{frac:Ceff × VD|e^(k teff)}}","why":"Choosing this inverts the exponential. From Ceff = {{frac:D0|VD}}e^(−k teff), multiplying both sides by VD e^(k teff) gives D0 = Ceff × VD × e^(k teff); dividing would make a longer teff need a smaller dose."},{"t":"The dose needed does not depend on the half-life","why":"Choosing this leaves k out of the dose line. In D0 = Ceff × VD × e^(k teff), a small k (a long half-life) keeps the exponent small, so a drug with a long half-life needs a far smaller dose for the same teff."}],"teach":[{"h":"The dose for a target duration","list":["Ceff = {{frac:D0|VD}} e^(−k teff), rearranged: D0 = Ceff × VD × e^(k teff).","The target time is in the exponent, so each extra half-life of duration doubles the dose.","Check: put the dose back into teff = {{frac:ln C0 − ln Ceff|k}} and the target time returns."]}],"cite":"7b---Pharmacokinetics-and-Pharmacodynamics.pdf, slide 8 (dose to double teff)"},{"id":"pd-c23","tier":"new","exam":3,"module":9,"lecture":"L11","topic":"pkpd","sub":"teff","concept":"teff-form-choice","skill":"apply","source":"slide","stem":"A single IV bolus dose, the apparent volume of distribution, the minimum effective concentration and the elimination half-life are given, but not k. Which form of the duration-of-activity equation takes these quantities as they are given?","options":[{"t":"The 1.44 t½ form","correct":true,"why":"teff = 1.44 t½ ln({{frac:D0|VD × Ceff}}) takes the half-life directly, because 1.44 = {{frac:1|0.693}} stands in for {{frac:1|k}}. No k has to be worked out first."},{"t":"The natural-log form, divided by k","why":"Choosing this skips a step the stem leaves open. teff = {{frac:ln C0 − ln Ceff|k}} needs k, so k = {{frac:0.693|t½}} would have to come first; it gives the same teff, by one more line."},{"t":"The base-10 log form, divided by k","why":"Choosing this adds two conversions. The 2.3 turns base-10 logarithms into natural ones and the division still needs k, which the stem does not give."},{"t":"D0 = Ceff × VD × e^(k teff)","why":"Choosing this solves for the wrong quantity. That line gives the dose for a chosen duration; here the dose is given and the duration is asked."}],"teach":[{"h":"Picking the teff form","list":["A k in the stem: teff = {{frac:ln C0 − ln Ceff|k}}, with C0 = {{frac:D0|VD}}.","A half-life in the stem: teff = 1.44 t½ ln({{frac:D0|VD × Ceff}}), or k = {{frac:0.693|t½}} first.","All forms give the same duration; the base-10 form needs the 2.3."]}],"cite":"7b---Pharmacokinetics-and-Pharmacodynamics.pdf, slides 6 \"Relationship Between Dose and Duration of Activity (teff)\" and 9 \"Effect of Dose and Elimination Half-life on Duration of Activity\""},{"id":"pd-c24","tier":"new","exam":3,"module":9,"lecture":"L11","topic":"pkpd","sub":"teff","concept":"double-dose-c0","skill":"apply","source":"slide","stem":"The IV bolus dose of a drug that follows linear, first-order, one-compartment pharmacokinetics is doubled, from 250 mg to 500 mg, with VD = 24 L. What happens to C0, the plasma concentration just after the dose?","options":[{"t":"It doubles, from 10.42 to 20.83 mg/L","correct":true,"why":"C0 = {{frac:D0|VD}}: {{frac:250 mg|24 L}} = 10.42 mg/L and {{frac:500 mg|24 L}} = 20.83 mg/L. The level is in proportion to the dose; it is the duration that gains only one half-life."},{"t":"It rises by one half-life's worth","why":"Choosing this moves the duration rule onto the level. teff gains one half-life when the dose doubles because the dose sits inside a logarithm; C0 has no logarithm, so it doubles."},{"t":"It stays the same; only the duration changes","why":"Choosing this keeps VD in mind and drops the dose. VD is unchanged, but C0 = {{frac:D0|VD}} has the dose on top, so twice the dose gives twice the level."},{"t":"It rises by a factor of ln 2","why":"Choosing this takes the ln 2 from the duration. Doubling adds {{frac:ln 2|k}} to teff; the level itself rises by a factor of 2."}],"teach":[{"h":"Doubling an IV bolus","list":["C0 = {{frac:D0|VD}}: twice the dose, twice the level just after the dose.","teff = {{frac:ln C0 − ln Ceff|k}}: twice C0 adds {{frac:ln 2|k}}, one half-life, to the duration.","Her slide problem: 26.35 hr at 250 mg, 30.97 hr at 500 mg."]}],"cite":"7b---Pharmacokinetics-and-Pharmacodynamics.pdf, slides 6 and 8 (her working of the slide 7 \"Practice Problem\", 250 mg and 500 mg into 24 L)"},{"id":"nl-c02","tier":"new","exam":3,"module":8,"lecture":"L12","topic":"nonlin","sub":"linear","concept":"nl-linear-vs-nonlinear","skill":"tell","source":"both","stem":"2. What is the difference between linear and non-linear pharmacokinetics?","options":[{"t":"Linear parameters stay fixed with dose; nonlinear ones change with dose","correct":true,"why":"In linear pharmacokinetics the parameters do not change when different or multiple doses are given, so half-life and clearance stay fixed. In nonlinear pharmacokinetics a larger dose or chronic administration changes them, and a small dose change can give a large concentration change."},{"t":"Linear pharmacokinetics is zero order and nonlinear pharmacokinetics is first order","why":"Choosing this reverses the labels. Linear pharmacokinetics is the first-order elimination of most drugs; a saturable, nonlinear drug looks first order at low concentrations and zero order at high ones."},{"t":"In nonlinear pharmacokinetics the AUC rises in direct proportion to the dose","why":"Choosing this attaches the linear property to the wrong model. Proportional AUC (area under the curve) is curve C, dose-independent kinetics; with saturable elimination the AUC deviates from proportionality once the dose passes a certain point."},{"t":"Nonlinear processes affect absorption only, never elimination","why":"Choosing this narrows saturation to one step. A saturable process can occur anywhere in absorption, distribution, metabolism and excretion, and phenytoin, the usual example, shows saturable elimination."}],"teach":[{"h":"Linear and nonlinear","list":["Linear: parameters such as half-life and clearance do not change when different or multiple doses of a drug are given. Most drugs follow this.","Nonlinear (saturable, dose-dependent, capacity-limited): increased doses or chronic administration cause deviations from the single-dose profile. Example: phenytoin.","Clearance and half-life are usually not constant within nonlinear processes."]}],"cite":"Nonlinear-Solutions-2.pdf, question 2; 8 - Nonlinear PK.pdf, slides 3 \"Linear vs. Nonlinear Pharmacokinetics\" and 19 \"Summary\"; transcript 10-14"},{"id":"nl-c03","tier":"new","exam":3,"module":8,"lecture":"L12","topic":"nonlin","sub":"kmcp","concept":"nl-thalf-cl-trend","skill":"apply","source":"both","stem":"3. What changes in t½ and ClT are usually observed with increased concentrations of drugs that exhibit nonlinear pharmacokinetics?","options":[{"t":"t½ increases and ClT decreases","correct":true,"why":"t½ = VD(0.693/Vmax)(KM + Cp) grows as Cp grows, and ClT = Vmax/(KM + Cp) shrinks as Cp grows. In one phenytoin patient, going from 15 to 21 mg/L took the half-life from 1.87 to 2.34 days and clearance from 20.8 to 16.7 L/day."},{"t":"t½ decreases and ClT increases","why":"Choosing this runs both lines the opposite direction. Cp is added to KM in the numerator of the half-life line and in the denominator of the clearance line, so a higher concentration lengthens the half-life and lowers the clearance."},{"t":"Neither changes, because Vmax and KM are constants","why":"Choosing this treats the half-life and clearance as constants because Vmax and KM are. Both lines also contain Cp, which changes with dose, so neither stays fixed; that is what makes the drug nonlinear."},{"t":"t½ increases and ClT increases","why":"Choosing this gets the half-life right but moves clearance with it. Cp is in the denominator of ClT = Vmax/(KM + Cp), so clearance falls; a longer half-life with an unchanged volume also requires a lower clearance."}],"teach":[{"h":"Half-life and clearance depend on concentration","list":["t½ = VD({{frac:0.693|Vmax}})(KM + Cp): the half-life rises as Cp rises.","ClT = {{frac:Vmax|KM + Cp}}: clearance falls as Cp rises, because Cp is in the denominator.","VD in L/kg is multiplied by the weight first. With Vmax in mg/day, t½ comes out in days and ClT in L/day."]}],"cite":"Nonlinear-Solutions-2.pdf, question 3; 8 - Nonlinear PK.pdf, slides 17 and 18"},{"id":"nl-c04","tier":"new","exam":3,"module":8,"lecture":"L12","topic":"nonlin","sub":"linear","concept":"nl-saturation-features","skill":"recall","source":"slide","multi":true,"stem":"Which of the following are characteristics of saturation kinetics? (Select all that apply)","options":[{"t":"Elimination half-life changes as dose is increased","correct":true,"why":"With saturable elimination t½ = VD(0.693/Vmax)(KM + Cp), so a higher dose, giving a higher Cp, gives a longer half-life. In linear kinetics the half-life does not change with dose."},{"t":"AUC is disproportional to the amount of bioavailable drug","correct":true,"why":"Once elimination saturates, a larger dose is cleared more slowly, so the AUC (area under the curve) rises more than in proportion to the dose, curve A against the straight curve C."},{"t":"Other drugs using the same enzyme or carrier can affect saturation","correct":true,"why":"Two drugs that need the same enzyme or carrier compete for its limited capacity, so one can push the other toward saturation: a drug–drug interaction through a shared system."},{"t":"Metabolite ratios may change with dose","correct":true,"why":"If one metabolic route saturates at a higher dose while others do not, the share of drug going down each route changes, and so does the mix of metabolites."},{"t":"Clearance stays constant as the dose is increased, whatever the concentration","why":"Choosing this carries the linear rule into saturation kinetics. ClT = Vmax/(KM + Cp) falls as Cp rises, so clearance is usually not constant within nonlinear processes."},{"t":"AUC increases in direct proportion to the dose at every dose given","why":"Choosing this describes curve C, dose-independent kinetics, rather than saturable kinetics. With saturation the AUC versus dose line bends upward once the dose passes a certain point."}],"teach":[{"h":"Saturation kinetics","list":["Elimination kinetics is nonlinear, and the elimination half-life changes as dose is increased.","AUC is disproportional to the amount of bioavailable drug.","Saturation of capacity-limited processes may be affected by other drugs requiring the same enzyme or carrier-mediated system.","The composition or ratio of the metabolites may be affected by a change in the dose."]}],"cite":"8 - Nonlinear PK.pdf, slide 6 \"Saturation Kinetics\""},{"id":"nl-c05","tier":"new","exam":3,"module":8,"lecture":"L12","topic":"nonlin","sub":"linear","concept":"nl-phenytoin","skill":"recall","source":"both","stem":"Which of the following drugs is the prototypical example of nonlinear pharmacokinetics?","options":[{"t":"Phenytoin","correct":true,"why":"Phenytoin shows saturable elimination: once its level passes a certain point, small changes in dose lead to big changes in concentration. It also has a narrow therapeutic window, so its dose is set from the patient's own KM and Vmax."},{"t":"Procainamide","why":"Choosing this picks a drug worked with first-order lines. Procainamide is given a fixed half-life and volume of distribution, which is linear pharmacokinetics; phenytoin is the example of saturable elimination."},{"t":"Ciprofloxacin","why":"Choosing this picks a drug worked with linear lines. Ciprofloxacin is given an equivalent oral dose from F, the bioavailable fraction, a linear calculation; it is not the example of saturable elimination."},{"t":"Cefprozil","why":"Choosing this picks a drug dosed from creatinine clearance. Cefprozil is dosed with first-order lines, its renal elimination treated as linear, not saturable."}],"teach":[{"h":"Phenytoin","list":["The usual example of nonlinear pharmacokinetics: small changes in dose lead to big changes in concentration once a certain level is reached.","It has a narrow therapeutic window, so the dose rate is set from the patient's KM and Vmax, found from two dose rates and their steady-state levels."]}],"cite":"8 - Nonlinear PK.pdf, slide 3 \"Linear vs. Nonlinear Pharmacokinetics\" (\"Ex. phenytoin\"); transcript 10-14"},{"id":"nl-c06","tier":"new","exam":3,"module":8,"lecture":"L12","topic":"nonlin","sub":"kmcp","concept":"nl-vmax-def","skill":"recall","source":"slide","stem":"Which term describes the maximum elimination rate of a saturable elimination process?","options":[{"t":"Vmax","correct":true,"why":"Vmax is the maximum elimination rate: with nothing else going on, the fastest the enzyme system can remove the drug. It is a rate, an amount or concentration per unit time, such as mg/day."},{"t":"KM","why":"Choosing this swaps the two Michaelis-Menten parameters. KM, the Michaelis constant, reflects the capacity of the enzyme system and is a concentration, mg/L; it is not a rate."},{"t":"k′","why":"Choosing this takes the low-concentration constant for the maximum. k′ = {{frac:Vmax|KM}} is the first-order constant that applies only when Cp is much less than KM; it is not the top rate."},{"t":"R","why":"Choosing this mixes the dose rate with the elimination ceiling. R is the amount given per unit time; at steady state it equals the elimination rate at Css, which is always below Vmax."}],"teach":[{"h":"The two parameters","list":["Vmax: maximum elimination rate, units of concentration (or amount) per time.","KM: Michaelis constant, reflecting the capacity of the enzyme system, units of concentration.","For a given drug in a given patient both are constants; they differ from one patient to another."]}],"cite":"8 - Nonlinear PK.pdf, slides 7 \"Parameters\" and 8"},{"id":"nl-c07","tier":"new","exam":3,"module":8,"lecture":"L12","topic":"nonlin","sub":"kmcp","concept":"nl-km-def","skill":"recall","source":"both","stem":"Which term describes the constant, in units of concentration, that reflects the capacity of the enzyme system in Michaelis-Menten kinetics?","options":[{"t":"KM","correct":true,"why":"KM, the Michaelis constant, reflects the capacity of the enzyme system and carries units of concentration, such as mg/L. Because Cp is also a concentration, the two can be compared to tell first-order from zero-order behaviour."},{"t":"Vmax","why":"Choosing this swaps the two parameters. Vmax is the maximum elimination rate, in concentration or amount per time, such as mg/day; KM is the one in concentration units."},{"t":"Css","why":"Choosing this takes a patient's measured level for a property of the enzyme. Css is the steady-state concentration a dose rate produces and changes with the dose; KM stays the same for that drug and patient."},{"t":"VD","why":"Choosing this reaches for a familiar linear parameter. VD is the apparent volume of distribution, in litres; it appears in the nonlinear half-life line but says nothing about enzyme capacity."}],"teach":[{"h":"KM","list":["KM is the Michaelis constant: it reflects the capacity of the enzyme system and has units of concentration.","KM and Cp share units, so they can be compared: Cp far below KM gives first-order behaviour, Cp far above KM gives zero-order behaviour."]}],"audit":"Slide 8 prints KM = Michaelis constant (units of concentration), keyed here. The 10.14 lecture says of KM \"the units here ... are gonna be concentration per unit time\" and calls it \"not really a constant ... a hybrid constant\"; later in the same lecture she says KM is \"in concentration terms, so milligrams per liter\". Slide printed text keyed.","cite":"8 - Nonlinear PK.pdf, slides 7 \"Parameters\" and 8; transcript 10-14"},{"id":"nl-c11","tier":"new","exam":3,"module":8,"lecture":"L12","topic":"nonlin","sub":"linear","concept":"nl-auc-dose","skill":"read","source":"slide","stem":"Area under the plasma level–time curve versus dose: curve A is a drug that exhibits a saturable elimination process and curve C represents dose-independent kinetics. Which of the following is true regarding these curves?","options":[{"t":"Above a certain dose the AUC of curve A rises more than proportionally","correct":true,"why":"At low doses the saturable drug is eliminated first order, so its AUC is proportional to dose like curve C. Past the saturation point clearance falls, so each extra milligram adds more area and curve A bends upward."},{"t":"The AUC of curve A rises in direct proportion to the dose at every dose","why":"Choosing this describes curve C, dose-independent kinetics. Curve A follows the straight line only until a certain dose and then deviates from it."},{"t":"Above a certain dose the AUC of curve A rises less than in proportion to the dose","why":"Choosing this bends curve A the wrong way. Saturated elimination removes drug more slowly, which enlarges the AUC; curve A lies above line C at high doses, not below it."},{"t":"The two curves differ at every dose, including the lowest","why":"Choosing this misses where the curves start. At low doses Cp is well below KM, the saturable drug behaves first order, and the two lines run together."}],"teach":[{"h":"AUC and dose","list":["Dose-independent (linear) kinetics: AUC proportional to dose, a straight line (curve C).","Saturable elimination (curve A): the same line at low doses; past a certain point the AUC is no longer directly proportional and rises steeply.","Because of this, the AUC of a saturable drug cannot be read through a fixed clearance."]}],"cite":"8 - Nonlinear PK.pdf, slide 5 (AUC versus dose for a saturable elimination process); transcript 10-14"},{"id":"nl-c12","tier":"new","exam":3,"module":8,"lecture":"L12","topic":"nonlin","sub":"kmcp","concept":"nl-vmax-effect","skill":"apply","source":"slide","stem":"The amount of drug in the body versus time for a capacity-limited drug following an IV dose was generated using a maximum elimination rate (Vmax) of 100 mg/hr and of 200 mg/hr, with the Michaelis constant (KM) kept constant. What is the probable result of the higher Vmax?","options":[{"t":"The amount of drug in the body falls faster","correct":true,"why":"Vmax is the maximum elimination rate, so doubling it lets the enzyme system remove drug faster at every amount; the 200 mg/hr curve reaches low amounts in about half the time of the 100 mg/hr curve."},{"t":"The amount of drug in the body falls more slowly","why":"Choosing this runs the effect the wrong direction. A larger Vmax is a larger elimination capacity, so the drug leaves faster, not more slowly."},{"t":"The elimination is unchanged, because KM is kept constant","why":"Choosing this treats KM as the only parameter that matters. The rate is Vmax × Cp/(KM + Cp), so with KM fixed, a larger Vmax still gives a larger rate at every concentration."},{"t":"The elimination becomes first order at every amount","why":"Choosing this mixes the size of Vmax with the order. Whether elimination looks first or zero order depends on Cp against KM, not on how large Vmax is."}],"teach":[{"h":"Vmax and the rate","list":["−{{frac:dCp|dt}} = {{frac:Vmax × Cp|KM + Cp}}: with KM fixed, the rate at any concentration scales with Vmax.","The higher the Vmax, the faster the drug leaves the body."]}],"cite":"8 - Nonlinear PK.pdf, slide 9 (amount of drug versus time, Vmax 100 and 200 mg/hr); transcript 10-14"},{"id":"nl-c13","tier":"new","exam":3,"module":8,"lecture":"L12","topic":"nonlin","sub":"dose","concept":"nl-ss-time","skill":"recall","source":"transcript","stem":"Which of the following is true regarding steady state for a nonlinear drug such as phenytoin?","options":[{"t":"It can take 2 to 3 weeks, depending on the drug","correct":true,"why":"The steady state of a nonlinear drug differs from the linear one: depending on the drug, it takes about 2 to 3 weeks to reach what is clinically taken as steady state, rather than 3 to 5 half-lives."},{"t":"It is reached after 3 to 5 half-lives, as with a constant infusion","why":"Choosing this carries the linear rule into nonlinear kinetics. The 3 to 5 half-life rule assumes a fixed half-life; here the half-life changes with concentration and steady state takes longer."},{"t":"It is never reached at any dose rate","why":"Choosing this overextends saturation. Any dose rate below Vmax reaches a steady state, Css = R × KM/(Vmax − R); only a dose rate at or above Vmax keeps accumulating."},{"t":"It is reached after the first dose","why":"Choosing this mixes steady state with the first-dose peak. Steady state needs repeated dosing until the rate in equals the rate out, which for a saturable drug takes weeks."}],"teach":[{"h":"Steady state, nonlinear","list":["R = {{frac:Vmax × Css|KM + Css}} applies at steady state, which for a nonlinear drug can take 2 to 3 weeks, not 3 to 5 half-lives.","A dose rate at or above Vmax has no steady state: the drug accumulates."]}],"cite":"transcript 10-14 (on 8 - Nonlinear PK.pdf, slide 11 \"In Vivo Determination of KM and Vmax\")"},{"id":"nl-c14","tier":"new","exam":3,"module":8,"lecture":"L12","topic":"nonlin","sub":"dose","concept":"nl-r-def","skill":"recall","source":"both","stem":"Which of the following describes R in R = {{frac:Vmax × Css|KM + Css}}?","options":[{"t":"The dose rate, an amount per unit time","correct":true,"why":"R is how fast drug is put into the body, an amount per unit time. At steady state it equals the rate of elimination, which is why it sits on the left of the Michaelis-Menten line with Css in place of Cp."},{"t":"A single dose, in mg","why":"Choosing this drops the time from the rate. A dose with no interval cannot set a steady state; R is reported as, for example, 430 mg/day, never as 430 mg alone."},{"t":"The first-order elimination rate constant, in day⁻¹","why":"Choosing this treats R as a rate constant. A rate constant is a fraction per unit time; R is an amount per unit time, with the units of Vmax."},{"t":"The ratio of the two steady-state concentrations","why":"Choosing this mixes R with the direct method. R1 and R2 there are two dose rates; the concentrations are C1 and C2, and their ratio is not R."}],"teach":[{"h":"The nonlinear dose-rate line","list":["R = {{frac:Vmax × Css|KM + Css}}. R is the dose rate, an amount per unit time; Vmax (maximum elimination rate) has the units of R; KM (Michaelis constant) and Css are concentrations.","A Vmax in mg/kg/day gives R in mg/kg/day, which is multiplied by the weight for mg/day.","Report a dose rate, such as mg/day, not an amount alone."]}],"cite":"8 - Nonlinear PK.pdf, slide 11 \"In Vivo Determination of KM and Vmax\"; transcript 10-14"},{"id":"nl-c15","tier":"new","exam":3,"module":8,"lecture":"L12","topic":"nonlin","sub":"kmvmax","concept":"nl-direct-needs","skill":"recall","source":"both","stem":"Which of the following is needed to calculate a patient's KM by the direct method?","options":[{"t":"Two dose rates and the steady-state level each gave","correct":true,"why":"KM and Vmax are both unknown, so two equations are needed: R1 with C1 and R2 with C2, written for the same patient and the same drug, combine to give KM = (R2 − R1)/((R1/C1) − (R2/C2))."},{"t":"One dose rate and the steady-state concentration it produced","why":"Choosing this stops one step short. One pair gives one equation with two unknowns, Vmax and KM; it gives Vmax only once KM is known."},{"t":"The half-life and the volume of distribution","why":"Choosing this reaches for the linear route to a rate constant. KM is not built from a half-life; the nonlinear half-life itself needs KM first."},{"t":"A plot of 1/v against 1/C from test-tube experiments","why":"Choosing this mixes the in vitro determination with the in vivo one. The reciprocal plot is a laboratory method; in a patient, KM comes from two dose rates and their steady-state levels."}],"teach":[{"h":"The direct method","list":["Two dose rates in the same patient, each with the steady-state concentration it produced: KM = {{frac:R2 − R1|(R1/C1) − (R2/C2)}}.","The rate units cancel, so KM is a concentration, mg/L.","Then Vmax = {{frac:R(KM + Css)|Css}} with either pair; both pairs give the same Vmax."]}],"cite":"8 - Nonlinear PK.pdf, slides 10 \"In Vitro Determination of KM and Vmax\" and 13 \"Determination of KM and Vmax by Direct Method\"; transcript 10-14"},{"id":"nl-c16","tier":"new","exam":3,"module":8,"lecture":"L12","topic":"nonlin","sub":"dose","concept":"nl-small-dose-change","skill":"apply","source":"both","stem":"What is the probable result of a small increase in the daily dose of phenytoin in a patient whose elimination is near saturation?","options":[{"t":"A disproportionately large rise in steady-state level","correct":true,"why":"Css = R × KM/(Vmax − R). As R nears Vmax the denominator shrinks fast, so a small rise in R gives a large rise in Css: in one phenytoin patient, 300 to 500 mg/day took Css from 5.1 to 20 mg/L."},{"t":"A proportional increase in the steady-state concentration","why":"Choosing this carries linear pharmacokinetics into a saturable drug. Proportional change needs constant clearance; here clearance falls as the concentration rises."},{"t":"No change, because elimination is zero order","why":"Choosing this reads zero order as a ceiling on concentration. A fixed elimination rate means extra drug is not removed any faster, so it accumulates and the concentration rises."},{"t":"A smaller increase than expected, because clearance rises with dose","why":"Choosing this runs clearance the wrong direction. ClT = Vmax/(KM + Cp) falls as Cp rises, which makes the rise in concentration larger, not smaller."}],"teach":[{"h":"Css from a dose rate","list":["Multiply out R = {{frac:Vmax × Css|KM + Css}}: R × KM + R × Css = Vmax × Css.","Gather the Css terms: R × KM = Css(Vmax − R), so Css = {{frac:R × KM|Vmax − R}}.","Valid only while R is below Vmax; as R nears Vmax, a small increase in dose gives a large rise in Css."]}],"cite":"8 - Nonlinear PK.pdf, slide 3 \"Linear vs. Nonlinear Pharmacokinetics\"; Nonlinear-Solutions-1.pdf; transcript 10-14"},{"id":"nl-c17","tier":"new","exam":3,"module":8,"lecture":"L12","topic":"nonlin","sub":"kmvmax","concept":"nl-params-constant","skill":"recall","source":"transcript","stem":"Which of the following is true regarding Vmax and KM?","options":[{"t":"Constant for one patient, different between patients","correct":true,"why":"Vmax and KM describe the patient's enzyme system for that drug, so they stay fixed for that patient. They vary between patients, which is why they are found from the patient's own dose rates and levels."},{"t":"They change with every dose, like the half-life and clearance","why":"Choosing this mixes the parameters with the quantities built from them. Half-life and clearance change with Cp; Vmax and KM, the constants in those lines, do not."},{"t":"They are the same in every patient taking the drug","why":"Choosing this treats published ranges as one value. Ranges are published, but each patient has his or her own Vmax and KM, found from two dose rates."},{"t":"KM is a rate, in units of concentration per time","why":"Choosing this swaps KM with Vmax. Vmax is the rate, concentration or amount per time; KM is in units of concentration, which is why it can be compared with Cp."}],"teach":[{"h":"Constants of the patient","list":["Vmax and KM are constants for a given drug in a given patient and differ between patients.","Published ranges give an estimate; the direct method finds the patient's own values from two dose rates and their steady-state concentrations."]}],"audit":"Distractor \"KM is a rate, in units of concentration per time\" matches the 10.14 lecture saying KM units \"are gonna be concentration per unit time\"; slide 8 prints KM in units of concentration, and she later says KM is in concentration terms, mg/L. Slide keyed.","cite":"transcript 10-14 (on 8 - Nonlinear PK.pdf, slides 7 \"Parameters\" and 11)"},{"id":"nl-c19","tier":"new","exam":3,"module":8,"lecture":"L12","topic":"nonlin","sub":"kmvmax","concept":"nl-vmax-either-pair","skill":"apply","source":"both","stem":"A patient reached a steady state of 10 mg/L on 6 mg/kg/day and 20 mg/L on 8 mg/kg/day, and KM was found to be 10 mg/L. Which dose and concentration are used to calculate Vmax?","options":[{"t":"Either pair, kept together; both give 12 mg/kg/day","correct":true,"why":"Vmax = {{frac:R(KM + Css)|Css}}: {{frac:8(10 + 20)|20}} = 12 and {{frac:6(10 + 10)|10}} = 12 mg/kg/day. The second pair is a check on the first."},{"t":"Only the higher dose with its concentration","why":"Choosing this treats one pair as the right one. Both pairs satisfy the same Michaelis-Menten line for the same patient, so each gives the same Vmax."},{"t":"One pair's dose with the other pair's concentration","why":"Choosing this mixes the pairs. A dose belongs with the steady state it produced: 8 with 10 mg/L gives 16 and 6 with 20 mg/L gives 9 mg/kg/day, neither of them Vmax."},{"t":"The average dose with the average concentration","why":"Choosing this treats the line as linear. Css rises out of proportion to R: 7 mg/kg/day gives {{frac:7 × 10|12 − 7}} = 14 mg/L, not 15, so only a measured pair can be used."}],"teach":[{"h":"The direct method","list":["Two dose rates in the same patient, each with the steady-state concentration it produced: KM = {{frac:R2 − R1|(R1/C1) − (R2/C2)}}.","The rate units cancel, so KM is a concentration, mg/L.","Then Vmax = {{frac:R(KM + Css)|Css}} with either pair; both pairs give the same Vmax."]}],"quote":"you should get the same answer regardless of which way you use it","cite":"8 - Nonlinear PK.pdf, slides 14 and 15 (her second Example); transcript 10-14"},{"id":"fr-4","tier":"new","exam":2,"module":4,"lecture":"L05","topic":"clearance","sub":"renalmech","concept":"reabsorption-inference","skill":"apply","source":"both","stem":"The renal clearance of an antibiotic was estimated to be 45 mL/min. What can be inferred from this information?","options":[{"t":"The drug is filtered and actively secreted.","why":"Picking this reads the comparison the wrong way round. Active secretion adds drug to the urine and lifts renal clearance above the glomerular filtration rate of about 120 mL/min; 45 mL/min is below it."},{"t":"The drug is filtered and reabsorbed.","correct":true,"why":"45 mL/min is below the glomerular filtration rate of about 120 mL/min. The drug is filtered, and some of it returns from the tubule to the blood, so less plasma is cleared than is filtered."},{"t":"There is some evidence of renal impairment.","why":"Picking this reads the renal clearance of a drug as the patient's kidney function. Kidney function is estimated with creatinine clearance; a drug's renal clearance describes how the kidney handles that drug, and a value below 120 mL/min points to reabsorption."}],"steps":[{"k":"setup","t":"ClR = 45 mL/min; GFR ≈ 120 mL/min","why":"Renal clearance is compared with the glomerular filtration rate, the plasma that filtration alone clears each minute."},{"k":"algebra","t":"{{frac:45 mL/min|120 mL/min}} = 0.375, so ClR is less than GFR: filtration with tubular reabsorption","why":"Below the filtration rate means drug that was filtered is not all leaving in the urine: some is reabsorbed back into the blood."}],"teach":[{"h":"Reading the mechanism from renal clearance","list":["ClR about equal to 120 mL/min: filtration only. Greater: filtration with active secretion. Less: filtration with tubular reabsorption.","Creatinine clearance, from Cockcroft-Gault with the ideal body weight, estimates the patient's renal function.","Hepatic clearance is approximated as total clearance minus renal clearance."]}],"quote":"So the drug is filtered and reabsorbed, OK? The inference is that we've got reabsorption going on.","audit":"PollEv on page 10, 63 responses on the capture, no distribution shown. Keyed B (transcript 10-19). 45 < 120.","cite":"Final-Exam-Review-10.19.pdf slide 10 (PollEv); 4---Clearance-and-Elimination.pdf, slide \"Tubular Reabsorption\""},{"id":"fr-6a","tier":"new","exam":2,"module":6,"lecture":"L07","topic":"multi","sub":"ssbolus","concept":"cmax-ss","skill":"multidose","source":"both","stem":"What is the expected maximum steady state plasma concentration following multiple IV bolus dosing every 12 hours of 300 mg of a drug with a t½ of 4 hours and VD of 16 L?","options":[{"t":"18.7 mg/L","why":"Picking this stops at the first dose. {{frac:300 mg|16 L}} = 18.75 mg/L is the peak after one dose; at steady state each dose lands on what is left of the earlier ones, so the peak is higher by the accumulation factor."},{"t":"21.4 mg/L","correct":true,"why":"C0 = 18.75 mg/L, k = 0.17325 hr⁻¹, and e^(−kτ) = 0.1251 for τ = 12 hr. Cmax∞ = {{frac:18.75|1 − 0.1251}} = 21.43 mg/L."},{"t":"32.6 mg/L","why":"Picking this overstates accumulation. 32.6 mg/L is 1.74 times the first-dose peak, which would need about 42% of each dose left at the next dose, as with dosing about every 5 hours. Every 12 hours is 3 half-lives, so only 12.5% is left and the factor is 1.14."},{"t":"None of the above","why":"Picking this usually follows a slip in the exponent, such as using t½ in place of k. With k = {{frac:0.693|4 hr}}, the steady-state peak works out to 21.4 mg/L, which is listed."}],"steps":[{"k":"unit","t":"k = {{frac:0.693|4 hr}} = 0.17325 hr⁻¹; C0 = {{frac:300 mg|16 L}} = 18.75 mg/L","why":"The rate constant from the half-life, and the first-dose peak from dose over volume: for an IV bolus the whole dose is in the body at once."},{"k":"algebra","t":"kτ = 0.17325 × 12 = 2.079; e^(−2.079) = 0.1251 (12.5% of a dose left after 3 half-lives)","why":"τ is the dosing interval, 12 hr. kτ has no units, and e^(−kτ) is the fraction of each dose still in the body when the next is given."},{"k":"algebra","t":"Cmax∞ = {{frac:C0|1 − e^(−kτ)}} = {{frac:18.75|1 − 0.1251}} = {{frac:18.75|0.8749}} = 21.43 mg/L","why":"The principle of superposition: the first-dose peak is carried to steady state by the accumulation factor, {{frac:1|0.8749}} = 1.14, because each dose adds to what remains."},{"k":"round","t":"Cmax∞ = 21.4 mg/L","why":"21.43 mg/L to one decimal place, her value. It is the steady-state peak, reached just after each dose is given, and it is 1.14 times the first-dose peak of 18.75 mg/L."}],"teach":[{"h":"Peaks, troughs and steady state with repeated IV bolus doses","list":["Cmax of the first dose: C0 = {{frac:D0|VD}}.","Cmax∞ = {{frac:C0|1 − e^(−kτ)}}: the first-dose peak times the accumulation factor. The maximum occurs when each dose is given.","Cmin∞ = Cmax∞ e^(−kτ), at the end of the interval, just before the next dose.","Steady state is reached in 3 to 5 half-lives. tmax is needed only for oral dosing."]}],"quote":"You should have gotten 21.4 mg per liter. What is the minimum? At steady state. 2.7, OK.","audit":"PollEv on page 13, locked, no count on the capture. Keyed 21.4 mg/L (transcript 10-19). Recompute: 18.75/(1 − e^(−2.079)) = 21.430. 32.6 = 18.75/(1 − 0.4248), e^(−kτ) = 0.4248 at τ = 4.94 hr. The same poll ran on 30 Sep (TRANSCRIPT_CUES 9.3).","cite":"Final-Exam-Review-10.19.pdf slide 13 (PollEv); 6---Repetitive-IV-Bolus-and-Intermittent-IV-Infusions.pdf, slide \"Concentration of Drug in the Body at Steady-State Following Repeated IV Bolus Injections\""},{"id":"fr-8a","tier":"new","exam":2,"module":7,"lecture":"L10","dupOf":"m7-c15","topic":"bioavail","sub":"fabs","concept":"fabs-two-aucs","skill":"bioavail","source":"both","stem":"What is the bioavailability of a 500 mg tablet which yielded an AUC of 115 (mg/L)hr compared to a 400 mg IV bolus dose that yielded an AUC of 132 (mg/L)hr?","options":[{"t":"50%","why":"Picking this corrects for the doses more than once. The AUC ratio {{frac:115|132}} = 0.871 is scaled once by the dose ratio {{frac:400|500}} = 0.8, giving 0.697, about 70%."},{"t":"70%","correct":true,"why":"F = ({{frac:AUCpo|AUCIV}})({{frac:DIV|Dpo}}) = ({{frac:115|132}})({{frac:400|500}}) = 0.871 × 0.8 = 0.697, which is 70%. The IV AUC is in the denominator; the IV dose is on top of the dose ratio."},{"t":"85%","why":"Picking this stops at the AUC ratio, {{frac:115|132}} = 0.871. The tablet area came from 500 mg against 400 mg IV, so it is scaled by {{frac:400|500}} = 0.8 to compare equal doses."},{"t":"92%","why":"Picking this inverts a ratio. With the doses upside down, ({{frac:115|132}})({{frac:500|400}}) = 1.089, more than all of the dose; a larger oral dose makes F smaller, not larger."}],"steps":[{"k":"setup","t":"Fabs = ({{frac:AUCpo|AUCIV}})({{frac:DIV|Dpo}})","why":"Absolute bioavailability compares the tablet with the IV bolus, so the IV AUC is the denominator. The doses differ, so the dose ratio corrects for them with the IV dose on top."},{"k":"algebra","t":"{{frac:115|132}} = 0.871; {{frac:400|500}} = 0.8; F = 0.871 × 0.8 = 0.697","why":"Absolute bioavailability is the AUC ratio scaled by the dose ratio. The units cancel in both ratios, (mg/L)hr over (mg/L)hr and mg over mg, so F is dimensionless."},{"k":"round","t":"F = 0.697, which is 70%","why":"0.697 rounds to 0.70, written as 70% or 0.70, never .70. F is a fraction with no units; below 1 it means about 30% of the oral dose does not reach the systemic circulation."}],"teach":[{"h":"Absolute bioavailability","list":["F = ({{frac:AUCpo|AUCIV}})({{frac:DIV|Dpo}}): the IV AUC is in the denominator, the IV dose on top.","AUC tells the extent of drug available for the body to use, the extent absorbed.","The oral dose that gives the same AUC as an IV dose is Dpo = {{frac:DIV|F}}."]}],"quote":"OK, most of you guys thought 70%.","audit":"PollEv on page 17, 0 votes on the capture (taken before voting). The same poll ran on 30 Sep (m7-c15). Keyed 70% (transcript 10-19). Recompute (115/132)(400/500) = 0.69697.","cite":"Final-Exam-Review-10.19.pdf slide 17 (PollEv); 7a---Bioavailability-and-Bioequivalence.pdf, slide \"Absolute Bioavailability\""},{"id":"fr-11a","tier":"new","exam":3,"module":9,"lecture":"L11","topic":"pkpd","sub":"teff","concept":"teff-calc","skill":"pkpd","source":"both","stem":"What is the duration of action for a 1 g IV bolus dose with a VD = 12.5 L, t½ = 4hr and MEC= 20 mg/L ?","options":[{"t":"4 hours","why":"Picking this counts one half-life, 80 to 40 mg/L, and stops above the MEC. The level falls from 80 to 20 mg/L, a factor of 4, which takes two half-lives. Four hours is the duration of a 500 mg dose."},{"t":"8 hours","correct":true,"why":"C0 = {{frac:1000 mg|12.5 L}} = 80 mg/L, four times the MEC. The level halves every 4 hours, so 80 to 40 to 20 mg/L takes two half-lives: 8 hours."},{"t":"12 hours","why":"Picking this counts one half-life too many. Three half-lives take the level from 80 to 10 mg/L, half the MEC; the effect ends when the level reaches 20 mg/L, after two."},{"t":"None of the above","why":"Picking this usually follows leaving the dose in grams: 1 g has to be 1000 mg before it is divided by 12.5 L. Done in mg, the duration is 8 hours, which is listed."}],"steps":[{"k":"unit","t":"1 g = 1000 mg; C0 = {{frac:1000 mg|12.5 L}} = 80 mg/L; k = {{frac:0.693|4 hr}} = 0.17325 hr⁻¹","why":"The concentration just after the bolus is the dose over the volume, in the same units as the MEC. k comes from the half-life."},{"k":"algebra","t":"teff = {{frac:ln C0 − ln MEC|k}} = {{frac:ln(80 ÷ 20)|0.17325}} = {{frac:1.3863|0.17325}} = 8.00 hr","why":"C = C0e^(−kt) solved for the time the level reaches the MEC. 80 ÷ 20 = 4, two doublings, so the duration is two half-lives."},{"k":"round","t":"teff = 8 hours","why":"8.00 hr is two half-lives of 4 hours, 80 to 40 to 20 mg/L. The effect lasts while the level is at or above the MEC of 20 mg/L, so the duration of action is 8 hours."}],"teach":[{"h":"Duration of action","list":["teff = {{frac:ln C0 − ln MEC|k}} = {{frac:2.3(log C0 − log MEC)|k}}, with C0 = {{frac:D0|VD}}.","Each doubling of the dose adds one half-life to the duration; halving it takes one away.","Rearrange the same first-order line to solve for any time: duration of action, time to reach steady state (3 to 5 half-lives), time to most of the drug eliminated."]}],"quote":"And most of you guys thought that it was 8 hours, and that is the correct answer.","audit":"PollEv on page 23, locked, no count on the capture. Keyed 8 hours (transcript 10-19). Recompute ln(4)/0.17325 = 8.0017 hr.","cite":"Final-Exam-Review-10.19.pdf slide 23 (PollEv); 7b---Pharmacokinetics-and-Pharmacodynamics.pdf slide 7 \"Practice Problem\""},{"id":"fr-12a","tier":"new","exam":1,"module":3,"lecture":"L04","topic":"infusion","sub":"pre","concept":"cp-before-steady-state","skill":"infusion","source":"both","stem":"What is the plasma concentration at the end of a 2 hour infusion of a drug with a t½ of 3 hours and a VD of 18 L at a rate of 50 mg/hr?","options":[{"t":"3.03 mg/L","why":"Picking this undercounts how far the level has climbed. 3.03 mg/L is 25% of the 12.025 mg/L steady state; 2 hours at k = 0.231 hr⁻¹ reaches 37.0% of it, 4.45 mg/L."},{"t":"4.45 mg/L","correct":true,"why":"Css = {{frac:R|kVD}} = {{frac:50|0.231 × 18}} = 12.025 mg/L, and after 2 hours the level is 12.025 × (1 − e^(−0.462)) = 12.025 × 0.3700 = 4.449 mg/L."},{"t":"4.81 mg/L","why":"Picking this overcounts the climb. 4.81 mg/L is 40% of the steady state, more than the 37.0% that 1 − e^(−kt) gives for 2 hours with k = 0.231 hr⁻¹."},{"t":"31.5 mg/L","why":"Picking this puts the level above the steady state it climbs toward. An infusion approaches {{frac:R|Cl}} = 12.025 mg/L from below and never passes it."}],"steps":[{"k":"unit","t":"k = {{frac:0.693|3 hr}} = 0.231 hr⁻¹; Cl = kVD = 0.231 × 18 = 4.158 L/hr","why":"No clearance is given, so it is built from the half-life and the volume: k is 0.693 over t½ for a first-order process, and Cl = kVD. hr⁻¹ × L leaves L/hr."},{"k":"algebra","t":"{{frac:R|Cl}} = {{frac:50 mg/hr|4.158 L/hr}} = 12.025 mg/L","why":"At steady state the rate in, R, equals the rate out, Cl × Css, so Css is R over Cl, the level the infusion climbs toward. mg/hr over L/hr leaves mg/L; the hours cancel."},{"k":"algebra","t":"1 − e^(−0.231 × 2) = 1 − e^(−0.462) = 1 − 0.6300 = 0.3700","why":"During an infusion Cp = Css(1 − e^(−kt)), so 1 − e^(−kt) is the fraction of steady state reached after 2 hours. hr⁻¹ × hr cancels, so kt and the fraction have no units."},{"k":"algebra","t":"Cp = 12.025 × 0.3700 = 4.449 mg/L","why":"Cp = Css(1 − e^(−kt)): the steady-state level times the fraction reached. mg/L times a pure number stays mg/L. The answer must lie below 12.025 mg/L, and it does."},{"k":"round","t":"Cp = 4.45 mg/L","why":"4.449 mg/L to two decimal places, her value. Two hours is less than one half-life of 3 hours, so the level is still below half of the 12.025 mg/L steady state."}],"teach":[{"h":"An infusion, start to finish","list":["During the infusion: Cp = {{frac:R|Cl}}(1 − e^(−kt)), where {{frac:R|Cl}} is the steady-state concentration it climbs toward.","After it stops there is only first-order elimination: Cp = Cend e^(−kt), with t counted from the end of the infusion.","Two infusions add: the level at any time is the sum of what is left of each.","Changing the rate changes the steady-state concentration in proportion; the time to reach it stays 3 to 5 half-lives."]}],"quote":"OK, still going? All right, still working, are we done? OK. 4.45 mg per liter.","audit":"PollEv on page 25, 1 response on the capture. Keyed 4.45 mg/L (transcript 10-19). Recompute 12.025 × 0.36998 = 4.4490.","cite":"Final-Exam-Review-10.19.pdf slide 25 (PollEv); 3IntravenousInfusions.pdf, slide \"Drug Concentration at Steady-State\""},{"id":"x3-a-kpos","tier":"new","exam":1,"module":1,"lecture":"L01","topic":"orders","sub":"first","concept":"first-order-properties","skill":"recall","source":"transcript","stem":"Which of the following is true about the rate constant k of a zero-order or a first-order process?","options":[{"t":"It is never a negative number","correct":true,"why":"The concentration falls, so the slope of the line is negative, and k is the slope with its sign reversed. The minus sign is written into the equations, C = C0 − kt and C = C0e^(−kt), so k itself is always reported as a positive number."},{"t":"It is negative for a falling concentration","why":"Picking this puts the decline into k twice. The fall is already the minus sign in the equation; a negative k there would make the concentration rise. A negative k from two points means they were subtracted in the wrong order."},{"t":"It has units of reciprocal time in both orders","why":"Only the first-order constant is reciprocal time, such as hr⁻¹. A zero-order k is itself a rate, in concentration or amount per unit time, such as mg/mL/hr."},{"t":"It changes with the starting concentration in first order","why":"The first-order k is a fixed fraction per unit time and holds no concentration, which is why the first-order half-life, {{frac:0.693|k}}, is constant. The starting concentration enters the zero-order half-life, {{frac:C0|2k}}, not k."}],"teach":[{"h":"Signs and units of k","list":["Both orders report k as a positive number; the minus sign lives in the equations.","First order: k = {{frac:ln(C1 ÷ C2)|t2 − t1}}, the earlier, larger concentration on top; units of reciprocal time.","Zero order: k = {{frac:C1 − C2|t2 − t1}}, earlier minus later; units of concentration or amount per time."]}],"quote":"our rate constant K, whether we're talking 1st order or zero order, our rate constant is never going to be a negative. It's never gonna be a negative number","audit":"Spoken 19 Aug (transcript 08-19) while deriving C = C0 - kt from the negative slope; the annotated Introduction deck page 20 carries the same note in the student's hand.","cite":"Introduction.pdf slides 17 and 18"},{"id":"x3-b-mech120","tier":"new","exam":2,"module":4,"lecture":"L05","topic":"clearance","sub":"renalmech","concept":"mechanism-from-clr","skill":"apply","source":"both","stem":"A new antibiotic is excreted by the kidney and has a renal clearance that is approximately 120 mL/min. What is the probable mechanism of renal excretion of this drug?","options":[{"t":"Filtration only","correct":true,"why":"A renal clearance at the glomerular filtration rate, about 120 mL/min, is what filtration alone produces. Nothing is added beyond what is filtered and nothing filtered is missing, so no second process is inferred. A value a few mL/min either side, such as 119 or 121 mL/min, is read the same way."},{"t":"Filtration with active secretion","why":"Picking this reads secretion into a value that does not exceed the filtration rate. Secretion is inferred only when renal clearance is greater than the GFR, as at 300 or 350 mL/min, because a transporter then adds drug to the lumen. At about 120 mL/min there is no excess for secretion to explain."},{"t":"Filtration with tubular reabsorption","why":"Picking this reads reabsorption into a value that is not below the filtration rate. Reabsorption is inferred only when renal clearance is less than the GFR, as at 45 mL/min, because filtered drug then returns to the blood. At about 120 mL/min none of the filtered drug is missing from the urine."}],"steps":[{"k":"setup","t":"GFR ≈ 120 mL/min; ClR ≈ 120 mL/min","why":"Renal clearance is read against the glomerular filtration rate (GFR), the plasma that filtration alone clears each minute, about 120 mL/min."},{"k":"algebra","t":"{{frac:120 mL/min|120 mL/min}} = 1, so ClR equals the GFR: filtration only","why":"Equal to the filtration rate means filtration accounts for all of the renal clearance; above it would mean secretion, below it reabsorption."}],"teach":[{"h":"Reading the mechanism from renal clearance","list":["Renal clearance about equal to 120 mL/min, the glomerular filtration rate: filtration only.","Greater than 120 mL/min: filtration with active secretion.","Less than 120 mL/min: filtration with tubular reabsorption.","The comparison is made in mL/min: a renal clearance in L/hr is converted first, and 7.2 L/hr is 120 mL/min."]}],"quote":"And I'm saying 120. If it's 119, 121, OK, let's call that filtration. If it's 250, then let's assume that we've got some active secretion going on.","audit":"Stem frame and the three options are her Exam 2 In-Class Review item 7 (300 mL/min, keyed filtration with active secretion, 5 Oct) with the clearance set at 120 mL/min, which her 14 Sep rule reads as filtration. No item of hers keys \"Filtration only\". 120 x 60 / 1000 = 7.2 L/hr.","cite":"Exam 2 In-Class Review (handed out 7 Oct 2026), question 7 format; 4---Clearance-and-Elimination.pdf, slide 13 \"Renal Excretion\" (glomerular filtration avg. 120 mL/min); 09.14 lecture"},{"id":"x3-b-mechlhr","tier":"new","exam":2,"module":4,"lecture":"L05","topic":"clearance","sub":"renalmech","concept":"mechanism-from-clr","skill":"apply","source":"both","stem":"The renal clearance of procainamide in a normal healthy subject is 21.02 L/hr. What is the probable mechanism of renal excretion of this drug?","options":[{"t":"Filtration only","why":"Picking this treats 21.02 L/hr as a value close to the filtration rate without converting it. In mL/min it is 350.3 mL/min, nearly three times 120 mL/min, so filtration cannot account for all of it. Filtration only fits a renal clearance of about 120 mL/min, which is 7.2 L/hr."},{"t":"Filtration with active secretion","correct":true,"why":"Renal clearance is compared with the glomerular filtration rate in the same units. 21.02 L/hr is 21.02 × 1000 ÷ 60 = 350.3 mL/min, well above 120 mL/min. A renal clearance above the filtration rate means drug is being added to the lumen by active tubular secretion as well as by filtration."},{"t":"Filtration with tubular reabsorption","why":"Picking this compares the number 21.02 with 120 although the two are in different units. 120 mL/min is 7.2 L/hr, and 21.02 L/hr is almost three times that. Reabsorption would put the renal clearance below 7.2 L/hr, not above it."}],"steps":[{"k":"unit","t":"ClR = {{frac:21.02 × 1000|60}} = 350.3 mL/min","why":"Litres per hour become millilitres per minute by multiplying by 1000 mL per litre and dividing by 60 minutes per hour, so the value can be set against the filtration rate in its own unit."},{"k":"setup","t":"GFR ≈ 120 mL/min; ClR = 350.3 mL/min is greater, so filtration with active secretion","why":"Above the filtration rate means a process is adding drug to the tubular fluid beyond what filtration delivers: active secretion."}],"teach":[{"h":"Same units before the comparison","list":["The filtration rate is about 120 mL/min, which is 7.2 L/hr.","Renal clearance from fe × ClT usually comes out in L/hr, because ClT = k × VD uses k in hr⁻¹ and VD in L.","Convert renal clearance to mL/min, multiplying by 1000 and dividing by 60, before reading the mechanism.","Above 120 mL/min: filtration with active secretion. Below: filtration with tubular reabsorption. About equal: filtration only."]}],"quote":"So, here we are comparing this to just GFR, right? So we're comparing the renal clearance to 120 mL per minute. So if it's more than 120, we assume active secretion, less than 120, we assume um reabsorption.","audit":"21.02 L/hr is her key to Single Oral Practice 1, part 1 (procainamide, ClT 32.34 L/hr x 0.65). The unit step is the one her Exam 2 In-Class Review item 2 asks for (\"renal clearance in mL/min\"). Shargel Ch 15, learning question 9 answer: \"GFR ~ 120 mL/min or 7.2 L/h\". 21.02 x 1000 / 60 = 350.33 mL/min.","cite":"Single Oral Practice 1 (procainamide), part 1; Exam 2 In-Class Review (handed out 7 Oct 2026), question 2; 4---Clearance-and-Elimination.pdf, slide 18 \"Active Secretion\""},{"id":"x3-b-urineph","tier":"new","exam":2,"module":4,"lecture":"L05","topic":"clearance","sub":"ionization","concept":"urine-ph-reabsorption","skill":"apply","source":"both","stem":"A weakly acidic drug is filtered at the glomerulus and partly reabsorbed from the renal tubule. Which of the following would be expected if the urine is made more alkaline?","options":[{"t":"Increased renal excretion of the drug","correct":true,"why":"A weak acid loses a proton as the pH rises, so in alkaline urine a larger share of it is ionized. The ionized form is not lipid soluble and does not cross the tubule wall back into the blood, so less drug is reabsorbed and more leaves in the urine."},{"t":"Decreased renal excretion of the drug","why":"Picking this reverses the effect of pH on a weak acid. Raising the pH ionizes a weak acid, and it is the nonionized form that is reabsorbed, so reabsorption falls and excretion rises. A weak base behaves the other way: alkaline urine leaves more of it nonionized and reabsorbed."},{"t":"No change in renal excretion of the drug","why":"Picking this treats renal excretion as filtration alone. The reabsorption of weak acids and weak bases depends on the pH of the fluid in the renal tubule and on the pKa of the drug. A drug that is partly reabsorbed therefore responds to a change in urine pH."},{"t":"Increased glomerular filtration of the drug","why":"Picking this places the pH effect at the glomerulus. Glomerular filtration is passive diffusion across the glomerulus at about 120 mL/min and does not depend on how much of the drug is ionized in the urine. Urine pH acts on reabsorption, the step after filtration."}],"teach":[{"h":"Urine pH and tubular reabsorption","list":["Only the nonionized form of a weak acid or weak base is lipid soluble enough to cross from the tubule back into the blood.","Weak acid (pKa 3 to 8): alkaline urine ionizes more of it, so less is reabsorbed and more is excreted.","Weak base (pKa 7.5 to 10.5): acidic urine ionizes more of it, with the same result.","Weak acid: pH = pKa + log{{frac:ionized|nonionized}}. Weak base: pH = pKa + log{{frac:nonionized|ionized}}."]}],"quote":"We talked about that that matters when we're looking at tubular reabsorption and what happens if we adjust the, the pH of the urine, what happens to the rate at which we expect the drug to be excreted from the body.","audit":"Her slide 20 gives the two factors (tubular pH and pKa) and the pKa ranges; her 5 Oct Exam 2 objectives name the question; the 14 Sep lecture ends on this slide before the direction is stated. Direction (weak acid, alkaline urine, more ionized, not lipid soluble, less reabsorbed, more excreted) from Shargel Ch 15, learning question 9 answer (ciprofloxacin). No item of hers on this objective exists.","cite":"4---Clearance-and-Elimination.pdf, slide 20 \"Effect of Urine pH on the Reabsorption of Weakly Acidic and Basic Drugs\"; Exam 2 objectives (10.05 lecture); Shargel Ch 15, learning question 9"},{"id":"x3-b-urphbase","tier":"new","exam":2,"module":4,"lecture":"L05","dupOf":"x3-b-urineph","topic":"clearance","sub":"ionization","concept":"urine-ph-reabsorption","skill":"apply","source":"both","stem":"A weakly basic drug is filtered at the glomerulus and partly reabsorbed from the renal tubule. Which of the following would be expected if the urine is made more acidic?","options":[{"t":"Increased renal excretion of the drug","correct":true,"why":"For a weak base, pH = pKa + log{{frac:nonionized|ionized}}, so a lower urine pH leaves a larger share of the drug ionized. The ionized form does not cross the tubule wall back into the blood, so less is reabsorbed and more leaves in the urine."},{"t":"Decreased renal excretion of the drug","why":"Picking this applies the weak-acid direction to a weak base. Acidic urine leaves more of a weak acid nonionized and reabsorbed, but it ionizes a weak base, so for a base reabsorption falls and excretion rises."},{"t":"No change in renal excretion of the drug","why":"Picking this treats renal excretion as filtration alone. The reabsorption of weak acids and weak bases depends on the pH of the fluid in the renal tubule and on the pKa of the drug, so a drug that is partly reabsorbed responds to a change in urine pH."},{"t":"Increased glomerular filtration of the drug","why":"Picking this places the pH effect at the glomerulus. Filtration is passive diffusion across the glomerulus and does not depend on how much of the drug is ionized in the urine. Urine pH acts on reabsorption, the step after filtration."}],"teach":[{"h":"Urine pH and tubular reabsorption","list":["Only the nonionized form of a weak acid or weak base crosses from the tubule back into the blood.","Weak base (pKa 7.5 to 10.5): acidic urine ionizes more of it, so less is reabsorbed and more is excreted; alkaline urine does the opposite.","Weak acid (pKa 3 to 8): alkaline urine ionizes more of it, so less is reabsorbed and more is excreted; acidic urine does the opposite.","Weak acid: pH = pKa + log{{frac:ionized|nonionized}}. Weak base: pH = pKa + log{{frac:nonionized|ionized}}."]}],"quote":"We talked about that that matters when we're looking at tubular reabsorption and what happens if we adjust the, the pH of the urine, what happens to the rate at which we expect the drug to be excreted from the body.","audit":"Built on x3-b-urineph with the drug made a weak base. Her slide 20 prints the weak-base form, pH = pKa + log(nonionized/ionized); a lower pH therefore means a larger ionized share. That the nonionized form is the one reabsorbed is the premise x3-b-urineph takes from Shargel Ch 15, learning question 9. No item of hers on this objective exists.","cite":"4---Clearance-and-Elimination.pdf, slide 20 \"Effect of Urine pH on the Reabsorption of Weakly Acidic and Basic Drugs\"; Exam 2 objectives (10.05 lecture); Shargel Ch 15, learning question 9"},{"id":"x3-b-urphacid","tier":"new","exam":2,"module":4,"lecture":"L05","dupOf":"x3-b-urineph","topic":"clearance","sub":"ionization","concept":"urine-ph-reabsorption","skill":"apply","source":"both","stem":"A weakly acidic drug is filtered at the glomerulus and partly reabsorbed from the renal tubule. Which of the following would be expected if the urine is made more acidic?","options":[{"t":"Decreased renal excretion of the drug","correct":true,"why":"For a weak acid, pH = pKa + log{{frac:ionized|nonionized}}, so a lower urine pH leaves a larger share of the drug nonionized. The nonionized form crosses back into the blood, so more is reabsorbed and less leaves in the urine."},{"t":"Increased renal excretion of the drug","why":"Picking this applies the weak-base direction to a weak acid. Acidic urine ionizes a weak base and raises its excretion, but it keeps a weak acid nonionized, so for an acid reabsorption rises and excretion falls."},{"t":"No change in renal excretion of the drug","why":"Picking this treats renal excretion as filtration alone. The reabsorption of weak acids and weak bases depends on the pH of the fluid in the renal tubule and on the pKa of the drug, so a drug that is partly reabsorbed responds to a change in urine pH."},{"t":"Decreased glomerular filtration of the drug","why":"Picking this places the pH effect at the glomerulus. Filtration is passive diffusion across the glomerulus and does not depend on how much of the drug is ionized in the urine. Urine pH acts on reabsorption, the step after filtration."}],"teach":[{"h":"Urine pH and tubular reabsorption","list":["Only the nonionized form of a weak acid or weak base crosses from the tubule back into the blood.","A drug in urine of its own kind (an acid in acidic urine, a base in alkaline urine) is mostly nonionized and reabsorbed; in urine of the opposite kind it is ionized and excreted.","Weak acid: pH = pKa + log{{frac:ionized|nonionized}}. Weak base: pH = pKa + log{{frac:nonionized|ionized}}."]}],"quote":"We talked about that that matters when we're looking at tubular reabsorption and what happens if we adjust the, the pH of the urine, what happens to the rate at which we expect the drug to be excreted from the body.","audit":"Built on x3-b-urineph with the urine made acidic instead of alkaline. Her slide 20 prints the weak-acid form, pH = pKa + log(ionized/nonionized); a lower pH therefore means a larger nonionized share. That the nonionized form is the one reabsorbed is the premise x3-b-urineph takes from Shargel Ch 15, learning question 9. No item of hers on this objective exists.","cite":"4---Clearance-and-Elimination.pdf, slide 20 \"Effect of Urine pH on the Reabsorption of Weakly Acidic and Basic Drugs\"; Exam 2 objectives (10.05 lecture); Shargel Ch 15, learning question 9"},{"id":"x3-b-cg085","tier":"new","exam":2,"module":4,"lecture":"L05","topic":"clearance","sub":"crclcalc","concept":"female-factor","skill":"recall","source":"both","stem":"Why does the Cockcroft-Gault equation multiply the estimate by 0.85 for a female patient?","options":[{"t":"Women are assumed to have less muscle mass","correct":true,"why":"Creatinine comes from the breakdown of muscle. The equation assumes that women are smaller and less muscular than men, so the same serum creatinine is read as a creatinine clearance 15% lower in a woman."},{"t":"Women are assumed to have a higher serum creatinine","why":"Picking this moves the sex difference into the laboratory value. Serum creatinine is measured in each patient and entered as it is; the equation assumes no value for it. The 0.85 is a separate factor applied after the division."},{"t":"Women are assumed to secrete more creatinine","why":"Picking this confuses the female factor with the known flaw of creatinine as a filtration marker. Creatinine is partly secreted in every patient, which is why inulin, almost completely filtered, is the better marker. The 0.85 rests on body size and muscle, not on secretion."},{"t":"Women have a higher glomerular filtration rate","why":"Picking this reverses the direction of the factor. Multiplying by 0.85 lowers the estimate, so the equation assigns a woman a lower creatinine clearance than a man of the same age, weight and serum creatinine, not a higher one."}],"teach":[{"h":"What the Cockcroft-Gault estimate assumes","list":["CrCl = {{frac:(140 − age)(IBW)|72 × SCr}}, × 0.85 if female; age in years, IBW (ideal body weight) in kg, SCr (serum creatinine) in mg/dL, result in mL/min.","Creatinine comes from muscle breakdown, so serum creatinine depends on muscle mass as well as on kidney function.","The 0.85 rests on the assumption that women are smaller and less muscular than men.","In patients whose muscle mass is far from average, frail elderly women or people who lift heavy weights, the serum creatinine may not reflect kidney function well."]}],"quote":"So, assumptions, the 0.85 if female. What do you think about that? The assumption is that women are smaller than men, less muscular than men.","audit":"Her 14 Sep discussion of the Cockcroft-Gault assumptions; on 5 Oct she lists \"why do we use Cockcroft galt and why do we use creatinine clearance?\" among the Exam 2 objectives. Written for this review.","cite":"4---Clearance-and-Elimination.pdf, slides 15 and 16 \"Creatinine Clearance/GFR\" and \"Creatinine Clearance\"; 09.14 lecture"},{"id":"x3-b-maxbolus","tier":"new","exam":2,"module":6,"lecture":"L07","topic":"multi","sub":"ssbolus","concept":"when-cmin","skill":"recall","source":"both","stem":"When does the maximum concentration of drug in the plasma occur with multiple IV bolus dosings?","options":[{"t":"when the dose is given","correct":true,"why":"An IV bolus puts the whole dose into the body at once, so the concentration is highest at the moment of injection and falls by first-order elimination until the next dose. At steady state each dose returns the level to the same peak, Cmax∞. No tmax is calculated for a bolus."},{"t":"at the end of the dosing interval","why":"Picking this names the trough. The concentration falls through the whole interval after a bolus, so the minimum, not the maximum, occurs at the end of the dosing interval, just before the next dose."},{"t":"in 3 to 5 half-lives","why":"Picking this answers when steady state is reached, not when the peak of each interval occurs. The plateau of equal peaks and troughs is reached in 3 to 5 half-lives; within each interval the peak still comes at the injection."},{"t":"when the rate of absorption equals the rate of elimination","why":"Picking this carries over the oral result. After an oral dose Cmax occurs at tmax, where the rate of absorption equals the rate of elimination. A bolus has no absorption phase, so there is no tmax to find; the peak is the injection itself."}],"teach":[{"h":"Where the peak and the trough fall","list":["Multiple IV bolus: peak when each dose is given (C0 for the first dose, Cmax∞ at steady state); trough at the end of the dosing interval.","Intermittent IV infusion: peak at the end of each infusion.","Multiple oral doses: peak at tmax, from ka, k and, at steady state, τ. tmax is needed only for oral doses.","Steady state, the plateau of equal peaks and troughs, is reached in 3 to 5 half-lives."]}],"quote":"When does the max occur? ... Yeah, when you give the dose, right? What happens in 3 to 5 half-lives? OK, that's when we reach our steady state, OK?","audit":"Her Exam 2 In-Class Review item 13 asks when the minimum occurs (keyed at the end of the dosing interval, 5 Oct); the maximum is her spoken follow-up to the 19 Oct Cmax-at-steady-state poll and her 28 Sep remark (\"when does the max occur? Initially ... right when you give the drug. So only for oral ... T Max\"). She has reversed the direction of her own items before (Quiz 3 Q2 and Exam 2 review 14). Options reuse item 13.","cite":"Final-Exam-Review-10.19.pdf slide 13 (PollEv follow-up); Exam 2 In-Class Review (handed out 7 Oct 2026), question 13 format; 6---Repetitive-IV-Bolus-and-Intermittent-IV-Infusions.pdf slide 8"},{"id":"x3-b-dosesata","tier":"new","exam":2,"module":6,"lecture":"L09","multi":true,"topic":"multoral","sub":"oparam","concept":"increase-dose-effects","skill":"apply","source":"both","dupOf":"m6b-c14","stem":"Which of the following would be expected following an increase in the dose with no change to the dosing interval? (Select all that apply)","options":[{"t":"decreased MTC","why":"Picking this treats the minimum toxic concentration as part of the regimen. The MTC belongs to the drug and the patient; a change in dose moves the concentrations, not the MTC."},{"t":"increased fluctuations between peak to trough concentrations","correct":true,"why":"A larger dose raises the peak and the trough in the same proportion, so the gap between them, which is C0 for a bolus, grows with the dose."},{"t":"increased patient compliance","why":"Picking this ties compliance to the dose. The patient takes the same number of doses a day, so compliance usually does not change; it is a longer interval, fewer doses, that increases compliance."},{"t":"increased steady-state concentrations","correct":true,"why":"With the interval fixed, a larger dose puts more drug in per interval, so Cmax∞, Cmin∞ and Cavg∞ all rise in proportion to the dose."},{"t":"decreased steady-state concentrations","why":"Picking this reverses the direction. Steady-state concentrations fall when the dose is decreased or the interval lengthened, not when the dose is increased."}],"teach":[{"h":"Changing one part of the regimen at a time","table":{"head":["","Dose increased","Interval increased","Interval decreased"],"rows":[["Steady-state concentrations","increase","decrease","increase"],["Peak-to-trough fluctuation","increase","increase","decrease"],["Patient compliance","usually no change","increase","decrease"]]}},{"t":"Dose and dosing interval are the two parameters a regimen can change; clearance, half-life and volume of distribution belong to the drug and the patient."}],"quote":"Increasing dose • increase steady-state concentrations • increase fluctuations between peak to trough (maximum & minimum) concentrations • usually no change in patient compliance","audit":"Options from her slide 14 \"Altering Dose\", built the way her Exam 2 In-Class Review item 9 is built from slide 18 \"Altering Dosing Interval\" (with MTC as a distractor); select-all as in her item 6. Written for this review.","cite":"6a---Multiple-Oral-Doses.pdf slide 14 \"Altering Dose\"; Exam 2 In-Class Review (handed out 7 Oct 2026), questions 6 and 9 format"},{"id":"x3-b-intsata","tier":"new","exam":2,"module":6,"lecture":"L09","multi":true,"topic":"multoral","sub":"oparam","concept":"increase-interval-effects","skill":"apply","source":"both","dupOf":"m6b-c15","stem":"Which of the following would be expected following an increase in the dosing interval with no change to the dose? (Select all that apply)","options":[{"t":"decreased MTC","why":"Picking this treats the minimum toxic concentration as part of the regimen. The MTC belongs to the drug and the patient; the interval moves the concentrations, not the MTC."},{"t":"increased fluctuations between peak to trough concentrations","correct":true,"why":"A longer interval gives the level more time to fall before the next dose, so the trough sits further below the peak and the fluctuation increases."},{"t":"increased patient compliance","correct":true,"why":"Fewer doses a day are easier for a patient to take as prescribed, so a longer interval increases compliance."},{"t":"decreased steady-state concentrations","correct":true,"why":"The same dose given less often puts less drug in per hour, so Cmax∞, Cmin∞ and Cavg∞ all decrease."},{"t":"increased steady-state concentrations","why":"Picking this reverses the direction. Steady-state concentrations increase when the interval is shortened, the best option in a regimen for raising them, not when it is lengthened."}],"teach":[{"h":"Changing one part of the regimen at a time","table":{"head":["","Dose increased","Interval increased","Interval decreased"],"rows":[["Steady-state concentrations","increase","decrease","increase"],["Peak-to-trough fluctuation","increase","increase","decrease"],["Patient compliance","usually no change","increase","decrease"]]}}],"quote":"Increasing dosing interval • decrease steady-state concentrations • increase fluctuations between peak to trough concentrations • increase patient compliance","audit":"Her Exam 2 In-Class Review item 9 (decrease in the dosing interval, single answer) reversed in direction and set as select-all, options from her slide 18 \"Altering Dosing Interval\". Written for this review.","cite":"6a---Multiple-Oral-Doses.pdf slide 18 \"Altering Dosing Interval\"; Exam 2 In-Class Review (handed out 7 Oct 2026), question 9 format"},{"id":"x3-b-adjsata","tier":"new","exam":2,"module":6,"lecture":"L09","multi":true,"topic":"multoral","sub":"oparam","concept":"regimen-parameters","skill":"recall","source":"both","dupOf":"m6b-c13","stem":"Which of the following can be adjusted in developing a dosage regimen? (Select all that apply)","options":[{"t":"dose size","correct":true,"why":"The size of each dose is one of the two parameters a regimen sets; changing it with the interval fixed raises or lowers the steady-state concentrations."},{"t":"clearance","why":"Picking this treats a property of the drug in the patient as part of the regimen. Clearance is constant for a first-order drug; a regimen is designed around it, not by changing it."},{"t":"dosing interval","correct":true,"why":"How often the dose is given is the second parameter a regimen sets; a shorter interval raises the steady-state concentrations and narrows the fluctuation."},{"t":"elimination half-life","why":"Picking this treats the half-life as a dial. The half-life is set by clearance and volume of distribution, t½ = {{frac:0.693 × VD|ClT}}, neither of which the regimen changes."},{"t":"volume of distribution","why":"Picking this treats the volume of distribution as part of the regimen. VD belongs to the drug in the patient and is the same whatever dose or interval is chosen."}],"teach":[{"h":"What a regimen can change","list":["Two parameters: the dose size and the dosing interval.","Clearance, half-life and volume of distribution belong to the drug in the patient; the regimen is designed around them.","Dose up, interval fixed: concentrations and fluctuation increase. Interval down, dose fixed: concentrations increase and fluctuation decreases."]}],"quote":"So the only things that we can change. Are the dose, so the, the size of the dose, how much drug we give, and the dosing intervals. OK. We don't change clearance, we don't change half-life, we don't change volume and distribution.","audit":"Her slide 11 \"Multiple-Dosage Regimens\" (two parameters) and her 28 Sep and 5 Oct statements; select-all as in her Exam 2 review item 6. Written for this review.","cite":"6a---Multiple-Oral-Doses.pdf slide 11 \"Multiple-Dosage Regimens\"; 09.28 lecture"},{"id":"x3-c-02","tier":"new","exam":3,"module":8,"lecture":"L12","topic":"nonlin","sub":"kmcp","concept":"nl-order-by-conc","skill":"recall","source":"both","stem":"For a drug that displays Michaelis-Menten (saturation) kinetics, which comparison decides whether the elimination rate depends on the concentration (first order) or is independent of it (zero order)?","options":[{"t":"Cp compared with KM","correct":true,"why":"KM, the Michaelis constant, carries units of concentration, as Cp does, so the two can be set against each other. Far below KM the rate follows Cp, first order; far above KM the rate is Vmax whatever Cp is, zero order."},{"t":"Cp compared with Vmax","why":"Picking this sets a level against a rate. Vmax is the maximum elimination rate, in mg/day or concentration per time; a plasma level in mg/L cannot be larger or smaller than a rate. The \"per time\" in its units is what separates Vmax from KM."},{"t":"The daily dose compared with KM","why":"Picking this sets a dose rate, in mg/day, against a concentration, in mg/L. A dose counts as \"low\" only when the level it produces is far below KM; the order is read from that level, not from the dose itself."},{"t":"Vmax compared with KM","why":"Picking this compares the two constants of the enzyme system. Both are fixed for a given drug in a given patient, so their ratio cannot switch elimination from first order to zero order as the level changes; only Cp moves."}],"teach":[{"h":"What decides the order","list":["Rate of elimination = {{frac:Vmax × Cp|KM + Cp}}.","KM (mg/L) and Cp (mg/L) share units, so Cp is compared with KM. Vmax (mg/day) is a rate and is not compared with a level.","Low concentrations relative to KM look first order; high concentrations relative to KM look zero order.","A \"low dose\" is low only because the Cp it gives is far below KM."]}],"quote":"So for those of you that missed the question that we just talked about before the quiz, I know who you are. Right, we just talked about it, right? You know what I'm talking about. KM and concentration.","audit":"Written for this review. Before Quiz 5 (10-19) the class rehearsed \"low dose first order and high dose zero order\"; after it she named the missed point \"KM and concentration\". Slide 2 objective: \"Discuss the relationship between KM and Cp\". Slide 8 prints Vmax in units of concentration/time and KM in units of concentration.","cite":"8 - Nonlinear PK.pdf, slides 2 \"Objectives\" and 8 \"Saturable-Enzymatic Elimination Processes\"; transcripts 10-14 and 10-19"},{"id":"x3-c-03","tier":"new","exam":3,"module":8,"lecture":"L12","multi":true,"topic":"nonlin","sub":"kmcp","concept":"nl-thalf-cl-trend","skill":"apply","source":"both","stem":"Which of the following would you expect with an increase in the daily dose of a drug that displays nonlinear pharmacokinetics? (Select all that apply)","options":[{"t":"Increased half-life","correct":true,"why":"t½ = VD({{frac:0.693|Vmax}})(KM + Cp). A larger daily dose gives a higher steady-state level, so KM + Cp grows and the half-life lengthens; VD, Vmax and KM do not move."},{"t":"Decreased half-life","why":"Picking this runs the half-life line backward. Cp is added to KM in the numerator of the half-life line, so a higher level gives a longer half-life, not a shorter one."},{"t":"Increased clearance","why":"Picking this carries the dose into the clearance. ClT = {{frac:Vmax|KM + Cp}} has Cp in the denominator, so a higher level gives a lower clearance. In linear kinetics clearance does not change with dose at all."},{"t":"Decreased clearance","correct":true,"why":"ClT = {{frac:Vmax|KM + Cp}}. A higher dose gives a higher Cp, a larger denominator and a lower clearance; this is why the level rises more than in proportion to the dose."},{"t":"Increased Vmax","why":"Picking this treats Vmax as a property of the dose. Vmax is the maximum elimination rate of the enzyme system, a constant for a given drug in a given patient; it does not change with the dose."},{"t":"Decreased Vmax","why":"Picking this reads saturation as a loss of capacity. The enzyme system still has the same Vmax; what changes with the dose is the level, and with it the half-life and the clearance."}],"teach":[{"h":"A larger dose of a nonlinear drug","list":["Vmax and KM are constants for a given drug in a given patient; the dose does not change them.","A higher daily dose gives a higher Cp, and both lines below contain Cp.","t½ = VD({{frac:0.693|Vmax}})(KM + Cp): rises as Cp rises.","ClT = {{frac:Vmax|KM + Cp}}: falls as Cp rises.","In linear kinetics neither changes with the dose; in nonlinear kinetics both do."]}],"quote":"So, concentration, as concentration increases, what's gonna happen to our clearance? It's gonna decrease.","audit":"Written for this review in the format of her Exam 2 In-Class Review question 6 (six paired increase/decrease options, select all). Keys from slides 17 and 18, Nonlinear-Solutions-2.pdf question 3 and Canvas Quiz 5 question 6 (\"Half-life changes as dose is increased\").","cite":"8 - Nonlinear PK.pdf, slides 6 \"Saturation Kinetics\", 17 \"Dependence of Elimination Half-Life on Dose\" and 18 \"Dependence of Clearance on Dose\"; Exam 2 In-Class Review, question 6 (format); transcript 10-14"},{"id":"x3-c-07","tier":"new","exam":3,"module":9,"lecture":"L11","topic":"pkpd","sub":"teff","concept":"teff-dose-change","skill":"pkpd","source":"both","stem":"What is the duration of action for a 2 g IV bolus dose with a VD = 12.5 L, t½ = 4 hr and MEC = 20 mg/L?","options":[{"t":"8 hours","why":"Picking this keeps the duration of a 1 g dose. C0 = {{frac:2000 mg|12.5 L}} = 160 mg/L, twice the 80 mg/L of 1 g, so the level needs one more half-life, 4 hours, to fall to 20 mg/L."},{"t":"12 hours","correct":true,"why":"C0 = {{frac:2000 mg|12.5 L}} = 160 mg/L, eight times the MEC. Eight is 2 × 2 × 2, so the level falls from 160 to 80 to 40 to 20 mg/L in three half-lives of 4 hours: 12 hours."},{"t":"16 hours","why":"Picking this doubles the 8-hour duration of a 1 g dose along with the dose. The dose sits inside a logarithm, so doubling it adds one half-life, 4 hours, to the 8 hours; it does not double the duration."},{"t":"None of the above","why":"Picking this usually follows leaving the dose in grams: 2 g has to be 2000 mg before it is divided by 12.5 L. Done in mg, the duration is 12 hours, which is listed."}],"steps":[{"k":"unit","t":"2 g = 2000 mg; C0 = {{frac:2000 mg|12.5 L}} = 160 mg/L; k = {{frac:0.693|4 hr}} = 0.17325 hr⁻¹","why":"The concentration just after the bolus is the dose over the volume, in the same units as the MEC. k comes from the half-life."},{"k":"algebra","t":"teff = {{frac:ln C0 − ln MEC|k}} = {{frac:ln(160 ÷ 20)|0.17325}} = {{frac:2.0794|0.17325}} = 12.00 hr","why":"C = C0e^(−kt) solved for the time the level reaches the MEC. 160 ÷ 20 = 8, three doublings, so the duration is three half-lives."},{"k":"round","t":"teff = 12 hours","why":"Three half-lives of 4 hours. With 500 mg, 1 g and 2 g the durations are 4, 8 and 12 hours: each doubling of the dose adds 4 hours."}],"teach":[{"h":"Doubling the dose","list":["teff = {{frac:ln C0 − ln MEC|k}}, with C0 = {{frac:D0|VD}}.","Doubling the dose doubles C0 and adds ln 2 to the top: one half-life more, whatever the starting duration.","With VD 12.5 L, t½ 4 hr and MEC 20 mg/L: 500 mg lasts 4 hours, 1 g lasts 8 hours, 2 g lasts 12 hours.","From 500 mg to 1 g the duration happens to double, because 4 hours is one half-life; from 1 g to 2 g it does not."]}],"quote":"And if we were to give 500 mg instead of 1 g, what would the duration of action be? 4 hours, right?","audit":"Her final-review poll (slide 23: 1 g, 8 hours) and her spoken follow-up (500 mg, 4 hours), with the dose doubled once more to 2 g. ln(8)/0.17325 = 12.0025 hr; 1.44 × 4 × ln 8 = 11.98 hr.","cite":"Final-Exam-Review-10.19.pdf slide 23 (PollEv, dose changed); 7b---Pharmacokinetics-and-Pharmacodynamics.pdf, slide 9 \"Effect of Dose and Elimination Half-life on Duration of Activity\""},{"id":"x3-c-08","tier":"new","exam":3,"module":9,"lecture":"L11","multi":true,"topic":"pkpd","sub":"teff","concept":"dose-double-teff","skill":"apply","source":"both","stem":"Which of the following would you expect with a 2-fold increase in the IV bolus dose of a drug that displays linear, first-order pharmacokinetics? (Select all that apply)","options":[{"t":"The AUC doubles","correct":true,"why":"AUC = {{frac:D0|Cl}} for an IV bolus, and in linear kinetics clearance does not change with the dose, so twice the dose gives twice the area under the curve."},{"t":"The initial plasma concentration doubles","correct":true,"why":"C0 = {{frac:D0|VD}}. The volume of distribution does not change with the dose, so twice the dose gives twice the concentration just after the bolus."},{"t":"The duration of action doubles","why":"Picking this treats the duration as proportional to the dose. In teff = 1.44 t½ ln({{frac:D0|VD × MEC}}) the dose sits inside the logarithm, so doubling it adds one half-life instead."},{"t":"The duration of action increases by one half-life","correct":true,"why":"Doubling C0 adds ln 2 to ln C0, and ln 2 divided by k is one half-life: the level needs exactly one half-life to fall from 2C0 back to C0, then follows the old curve."},{"t":"The half-life doubles","why":"Picking this moves the half-life with the dose. In linear, first-order kinetics t½ = {{frac:0.693|k}} and k does not depend on the dose; a half-life that changes with dose marks a nonlinear drug."},{"t":"The clearance doubles","why":"Picking this moves clearance with the dose. Clearance belongs to the drug and the patient; doubling the dose doubles the AUC instead, so that Cl = {{frac:D0|AUC}} stays the same."}],"teach":[{"h":"Doubling an IV bolus dose, linear kinetics","list":["Doubles: C0 = {{frac:D0|VD}} and AUC = {{frac:D0|Cl}}, because VD and Cl do not change with the dose.","Unchanged: k, t½, VD and Cl.","Duration of action: one half-life longer, not doubled, because the dose sits inside the logarithm in teff = 1.44 t½ ln({{frac:D0|VD × MEC}})."]}],"quote":"Because we expect for our linear pharmacokinetics, a proportional increase, decrease, or whatever, change. In the AUC as well as the concentration as we change the dose.","audit":"Written for this review in the format of her Exam 2 In-Class Review question 6 (select all, increase in dose). Keys: PollEv on slide 12 (doubling does not double duration: False), Quiz 5 question 2 (increased by one half-life), transcript 09-30 (AUC and concentration proportional to dose), IV-Bolus-Practice-4 (doubled dose: no change in half-life or clearance, initial concentration doubled).","cite":"7b---Pharmacokinetics-and-Pharmacodynamics.pdf, slides 9 \"Effect of Dose and Elimination Half-life on Duration of Activity\" and 12 (PollEv); Exam 2 In-Class Review, question 6 (format); 7a---Bioavailability-and-Bioequivalence.pdf, slide \"Absolute Bioavailability\" (Div = Cl × AUCiv); transcript 09-30"},{"id":"x3-c-09","tier":"new","exam":3,"module":9,"lecture":"L11","topic":"pkpd","sub":"teff","concept":"dose-double-teff","skill":"apply","source":"both","stem":"A drug has a VD of 12.5 L, a t½ of 4 hr and an MEC of 20 mg/L. A 500 mg IV bolus dose gives a duration of action of 4 hours, and a 1 g IV bolus dose gives 8 hours. Which of the following explains why doubling the dose doubled the duration of action here?","options":[{"t":"The 4-hour duration equals one half-life","correct":true,"why":"Doubling the dose always adds one half-life, here 4 hours. Starting from a duration of exactly one half-life, with C0 = 40 mg/L twice the MEC, adding one half-life doubles it; from any other starting duration it does not."},{"t":"Duration of action is proportional to the dose","why":"Picking this generalises from one pair of doses. With 2 g the duration is 12 hours, not 16: each doubling adds one half-life, because the dose sits inside a logarithm."},{"t":"The half-life doubles when the dose doubles","why":"Picking this moves the half-life with the dose. For linear, first-order kinetics t½ = {{frac:0.693|k}} stays 4 hours at every dose; it is the starting level, C0, that doubles."},{"t":"The MEC is halved when the dose doubles","why":"Picking this moves the threshold. The MEC is a property of the drug, 20 mg/L at any dose; a larger dose raises C0 further above it, and does not lower the MEC."}],"teach":[{"h":"One half-life per doubling","list":["teff = {{frac:ln C0 − ln MEC|k}}: doubling the dose adds {{frac:ln 2|k}}, one half-life.","The duration doubles only when it started at one half-life, that is when C0 is twice the MEC.","So doubling the IV bolus dose does not, in general, give a 2-fold increase in the duration of activity."]}],"quote":"Everybody know what happens if we double the dose? You get one half-life.","audit":"Written for this review. Her 12 Oct PollEv keys \"Doubling the IV bolus dose ... results in a 2-fold increase in the duration of activity\" False; her 19 Oct poll and follow-up give 8 hours at 1 g and 4 hours at 500 mg, a doubling. This item separates the two. C0 at 500 mg = 40 mg/L; ln 2/0.17325 = 4.0008 hr.","cite":"Final-Exam-Review-10.19.pdf slide 23 (PollEv and follow-up); 7b---Pharmacokinetics-and-Pharmacodynamics.pdf, slide 12 (PollEv, keyed False); transcript 10-19"},{"id":"x3-c-13","tier":"new","exam":2,"module":7,"lecture":"L10","multi":true,"topic":"bioavail","sub":"factors","concept":"factors-list","skill":"recall","source":"both","stem":"Which of the following can influence the bioavailability of a drug? (Select all that apply)","options":[{"t":"Food effects","correct":true,"why":"Food effects are one of the factors influencing bioavailability, with the physicochemical properties of the drug and formulation, stability and pH effects, first-pass metabolism, prodrugs, drug–drug interactions, efflux transporters, age and disease state."},{"t":"Efflux transporters","correct":true,"why":"Efflux transporters are on the same list of factors influencing bioavailability: the rate and extent to which the active ingredient is absorbed from the product and becomes available at the site of action."},{"t":"Drug–drug interactions","correct":true,"why":"Drug–drug interactions are on the list of factors influencing bioavailability, with food effects and efflux transporters."},{"t":"The apparent volume of distribution","why":"Picking this takes a distribution parameter for a determinant of absorption. VD relates the amount in the body to the plasma level after the drug is in the circulation; it does not decide how much of a dose gets there."},{"t":"The dosing interval","why":"Picking this takes a regimen setting for a property of the product or the patient. The dosing interval changes steady-state levels, but the fraction of each dose that reaches the circulation stays the same."}],"teach":[{"h":"Factors influencing bioavailability","list":["Physicochemical properties of the drug and formulation; drug stability and pH effects; pre-systemic and first-pass metabolism; prodrugs.","Food effects; drug–drug interactions; efflux transporters; age; disease state.","Formulation factors and the first-pass effect are the reasons most often behind low bioavailability.","The volume of distribution, the half-life and the dosing interval do not change F, the fraction of the dose that reaches the circulation."]}],"quote":"we had a long list of factors that can affect bioavailability","audit":"Written for this review from her slide \"Factors Influencing Bioavailability\" (nine bullets); her 10-05 review of Exam 2 objectives named the list. m7-c09 tests one factor with a single answer.","cite":"7a---Bioavailability-and-Bioequivalence.pdf, slides \"Factors Influencing Bioavailability\" and \"Summary\"; transcript 10-05"}],"topics":[{"id":"intro","name":"What pharmacokinetics is","open":true,"cite":"Introduction.pdf slides 2–15","subs":[{"id":"disc","name":"Pharmacokinetics and the related disciplines","cite":"Introduction.pdf slides 3–8"},{"id":"terms","name":"ADME and the fundamental terms","cite":"Introduction.pdf slides 4–5"},{"id":"matrix","name":"Whole blood, serum and plasma","cite":"Introduction.pdf slide 10"},{"id":"models","name":"Pharmacokinetic models","cite":"Introduction.pdf slides 11–14"},{"id":"curve","name":"The concentration versus time curve","cite":"Introduction.pdf slide 9"}]},{"id":"orders","name":"Kinetic orders and the maths","open":true,"cite":"Introduction.pdf slides 16–21","subs":[{"id":"zero","name":"Zero-order reactions","cite":"Introduction.pdf slide 17"},{"id":"first","name":"First-order reactions","cite":"Introduction.pdf slide 18"},{"id":"half","name":"Half-life, both orders","cite":"Introduction.pdf slide 19"},{"id":"plots","name":"Linear and semi-logarithmic plots","cite":"Introduction.pdf slides 20–21"},{"id":"decide","name":"Deciding the order from a data set","cite":"Introduction.pdf slides 17–18"}]},{"id":"infusion","name":"Intravenous infusion","cite":"3IntravenousInfusions.pdf, slide \"Objectives\"","subs":[{"id":"basics","name":"What an infusion does, and why the input is zero order","cite":"3IntravenousInfusions.pdf, slide \"Intravenous Infusion\""},{"id":"css","name":"Steady state and continuous dosing","cite":"3IntravenousInfusions.pdf, slide \"Drug Concentration at Steady-State\""},{"id":"pre","name":"Concentration before steady state is reached","cite":"3IntravenousInfusions.pdf, slides \"Drug Concentration Prior to Reaching Steady-State\""},{"id":"rate","name":"Infusion rate for a target steady-state concentration","cite":"3IntravenousInfusions.pdf, slide \"Objectives\", bullet 6"},{"id":"time","name":"Time to reach a stated fraction of steady state","cite":"3IntravenousInfusions.pdf, slide \"Example 4\""},{"id":"stop","name":"Concentration after the infusion is stopped","cite":"3IntravenousInfusions.pdf, slide \"Drug Concentration after an IV Infusion has Ended\""},{"id":"load","name":"Loading dose, alone and with a continuous infusion","cite":"3IntravenousInfusions.pdf, slides \"IV Bolus Loading Dose and Continuous IV Infusion\""}]},{"id":"clearance","name":"Elimination, clearance and renal clearance","cite":"4---Clearance-and-Elimination.pdf slide 2","subs":[{"id":"routes","name":"The main routes of elimination, renal and hepatic","cite":"4---Clearance-and-Elimination.pdf slide 2, bullet 1"},{"id":"renalmech","name":"Glomerular filtration, tubular secretion and reabsorption","cite":"4---Clearance-and-Elimination.pdf slide 2, bullet 2"},{"id":"crclcalc","name":"Creatinine clearance and its significance","cite":"4---Clearance-and-Elimination.pdf slide 2, bullet 3"},{"id":"ionization","name":"Degree of ionization and renal excretion","cite":"4---Clearance-and-Elimination.pdf slide 2, bullet 4"},{"id":"clcalc","name":"Total, renal and hepatic clearance","cite":"4---Clearance-and-Elimination.pdf slide 2, bullet 5"}]},{"id":"oral","name":"Oral absorption, single dose","cite":"5---Pharmacokinetics-of-Oral-Absorption.pdf slide 2","subs":[{"id":"extravasc","name":"Kinetics after extravascular administration","cite":"5---Pharmacokinetics-of-Oral-Absorption.pdf slide 2, bullet 1"},{"id":"conc","name":"Plasma concentration after a single oral dose","cite":"5---Pharmacokinetics-of-Oral-Absorption.pdf slide 2, bullet 2"},{"id":"peak","name":"Peak concentration and time to peak","cite":"5---Pharmacokinetics-of-Oral-Absorption.pdf slide 2, bullet 3"},{"id":"changes","name":"Effects of changing ka, k and dose","cite":"5---Pharmacokinetics-of-Oral-Absorption.pdf slide 2, bullet 4"}]},{"id":"multi","name":"Multiple dosing: repeated IV bolus (deck 6)","cite":"6---Repetitive-IV-Bolus-and-Intermittent-IV-Infusions.pdf, slide \"Objectives\"","subs":[{"id":"accum","name":"Drug accumulation and steady state","cite":"6---Repetitive-IV-Bolus-and-Intermittent-IV-Infusions.pdf, slide \"Drug accumulation with repeated administration\""},{"id":"superpos","name":"The principle of superposition","cite":"6---Repetitive-IV-Bolus-and-Intermittent-IV-Infusions.pdf, slide \"Superposition\""},{"id":"ssbolus","name":"Maximum, minimum and average at steady state","cite":"6---Repetitive-IV-Bolus-and-Intermittent-IV-Infusions.pdf, slides \"Amount of Drug in the Body Following Repeated IV Bolus Injections\" to \"Example 1\""},{"id":"ndose","name":"Concentration after n doses and after the last dose","cite":"6---Repetitive-IV-Bolus-and-Intermittent-IV-Infusions.pdf, slides \"Plasma Drug Concentration at Any Time After n Doses\" to \"Example 3\""}]},{"id":"intermit","name":"Multiple dosing: intermittent IV infusions (deck 6)","cite":"6---Repetitive-IV-Bolus-and-Intermittent-IV-Infusions.pdf, slide \"Intermittent Intravenous Infusions\"","subs":[{"id":"why","name":"Why, and the equation for one infusion","cite":"6---Repetitive-IV-Bolus-and-Intermittent-IV-Infusions.pdf, slides \"Rationale\" and \"Administering One or More Doses by IV Infusion\""},{"id":"add","name":"Adding the infusions on a time line","cite":"6---Repetitive-IV-Bolus-and-Intermittent-IV-Infusions.pdf, slides \"Example 4\" to \"Summary\""}]},{"id":"multoral","name":"Multiple dosing: oral doses (deck 6a)","cite":"6a---Multiple-Oral-Doses.pdf, slide \"Objectives\"","subs":[{"id":"oeq","name":"The multiple-oral-dose equations","cite":"6a---Multiple-Oral-Doses.pdf, slides \"Concentration of Drug in the Plasma at Any Time\" and \"Peak, Trough and Average Plasma Concentrations at Steady State\""},{"id":"ossc","name":"Peak, trough and time to peak at steady state","cite":"6a---Multiple-Oral-Doses.pdf, slides \"Time to Peak at Steady State\" and \"Example 1\""},{"id":"oparam","name":"Changing the dose and the dosing interval","cite":"6a---Multiple-Oral-Doses.pdf, slides \"Multiple-Dosage Regimens\" to \"Consider Peak and Trough\""}]},{"id":"bioavail","name":"Bioavailability and bioequivalence","cite":"7a---Bioavailability-and-Bioequivalence.pdf, slide \"Objectives\"","subs":[{"id":"defs","name":"Drug product performance, bioavailability, absolute and relative, bioequivalence","cite":"7a---Bioavailability-and-Bioequivalence.pdf, slides \"Drug Product Performance\" to \"Bioequivalence\""},{"id":"factors","name":"Factors influencing bioavailability","cite":"7a---Bioavailability-and-Bioequivalence.pdf, slides \"Factors Influencing Bioavailability\" and \"Summary\""},{"id":"fabs","name":"Absolute bioavailability and the equivalent oral dose","cite":"7a---Bioavailability-and-Bioequivalence.pdf, slides \"Absolute Bioavailability\" and \"Practice Problem\""},{"id":"frel","name":"Relative bioavailability","cite":"7a---Bioavailability-and-Bioequivalence.pdf, slides \"Relative Bioavailability\" and \"Practice Problem\""},{"id":"figure","name":"Reading the bioequivalence example","cite":"7a---Bioavailability-and-Bioequivalence.pdf, slide \"Bioequivalence Example\""}]},{"id":"pkpd","name":"PK-PD relationship","cite":"7b---Pharmacokinetics-and-Pharmacodynamics.pdf, slide 2 \"Objectives\"","subs":[{"id":"pd","name":"Pharmacodynamics and the exposure–response relationship","cite":"7b---Pharmacokinetics-and-Pharmacodynamics.pdf, slide 3 \"Pharmacodynamics\""},{"id":"doseresp","name":"Response rising with dose and concentration up to a maximum","cite":"7b---Pharmacokinetics-and-Pharmacodynamics.pdf, slides 4 \"Relationship of Dose to Pharmacologic Effect\", 5 \"Typical Log Dose-versus-Pharmacologic Response Curves\" and 11 \"Summary\""},{"id":"teff","name":"Dose and the duration of activity, teff","cite":"7b---Pharmacokinetics-and-Pharmacodynamics.pdf, slides 6 to 9 and 12"},{"id":"dosefor","name":"The dose for a target duration of activity","cite":"7b---Pharmacokinetics-and-Pharmacodynamics.pdf, slide 8 and the In-Class Activity on slide 13"},{"id":"thalf","name":"Elimination half-life and the duration of activity","cite":"7b---Pharmacokinetics-and-Pharmacodynamics.pdf, slides 9 \"Effect of Dose and Elimination Half-life on Duration of Activity\" and 10 \"Effect of Elimination Half-life on Duration of Activity\""}]},{"id":"nonlin","name":"Nonlinear pharmacokinetics","cite":"8 - Nonlinear PK.pdf, slide 2 \"Objectives\"","subs":[{"id":"linear","name":"Linear and nonlinear pharmacokinetics; saturation kinetics","cite":"8 - Nonlinear PK.pdf, slides 3 \"Linear vs. Nonlinear Pharmacokinetics\" to 6 \"Saturation Kinetics\", and 19 \"Summary\""},{"id":"kmcp","name":"KM and Cp: the order of saturable elimination, half-life and clearance","cite":"8 - Nonlinear PK.pdf, slides 7 \"Parameters\", 8 \"Saturable-Enzymatic Elimination Processes\", 9, 17 and 18"},{"id":"kmvmax","name":"Vmax and KM from two dose rates in a patient","cite":"8 - Nonlinear PK.pdf, slides 13 \"Determination of KM and Vmax by Direct Method\", 14 \"Example\" and 15"},{"id":"dose","name":"Dose rate and steady state for a nonlinear drug such as phenytoin","cite":"8 - Nonlinear PK.pdf, slides 11 \"In Vivo Determination of KM and Vmax\" and 12 \"Example\""}]}],"lectures":[{"id":"L01","deck":"Introduction.pdf","label":"Module 1: Introduction, kinetic orders and AUC (17 & 19 Aug)","exam":1,"module":1},{"id":"L02","deck":"2IVBolusAdministration.pdf","label":"Module 2: One-compartment IV bolus (24 Aug)","exam":1,"module":2},{"id":"L03","deck":"2IVBolusAdministration.pdf","label":"Module 2: Multicompartment IV bolus (26 Aug)","exam":1,"module":2},{"id":"L04","deck":"3IntravenousInfusions.pdf","label":"Module 3: Intravenous infusion (2 Sep)","exam":1,"module":3},{"id":"L05","deck":"4---Clearance-and-Elimination.pdf","label":"Module 4: Drug elimination, clearance and renal clearance (14 Sep)","exam":2,"module":4},{"id":"L06","deck":"5---Pharmacokinetics-of-Oral-Absorption.pdf","label":"Module 5: Pharmacokinetics of oral absorption (16 & 21 Sep)","exam":2,"module":5},{"id":"L07","deck":"6---Repetitive-IV-Bolus-and-Intermittent-IV-Infusions.pdf","label":"Module 6: Repetitive IV bolus injections (23 Sep)","exam":2,"module":6},{"id":"L08","deck":"6---Repetitive-IV-Bolus-and-Intermittent-IV-Infusions.pdf","label":"Module 6: Intermittent IV infusions (28 Sep)","exam":2,"module":6},{"id":"L09","deck":"6a---Multiple-Oral-Doses.pdf","label":"Module 6a: Multiple oral doses (28 Sep)","exam":2,"module":6},{"id":"L10","deck":"7a---Bioavailability-and-Bioequivalence.pdf","label":"Module 7a: Bioavailability and bioequivalence (30 Sep)","exam":2,"module":7},{"id":"L11","deck":"7b---Pharmacokinetics-and-Pharmacodynamics.pdf","label":"Module 7b: PK-PD relationship (12 Oct)","exam":3,"module":9},{"id":"L12","deck":"8 - Nonlinear PK.pdf","label":"Module 8: Nonlinear pharmacokinetics (14 Oct)","exam":3,"module":8}],"skills":[{"id":"recall","label":"Recall a definition or fact","short":"Recall","kind":"concept"},{"id":"tell","label":"Tell two similar things apart","short":"Tell apart","kind":"concept"},{"id":"read","label":"Read a graph, table or equation","short":"Read","kind":"concept"},{"id":"apply","label":"Reason about a patient or a change","short":"Apply","kind":"concept"},{"id":"order","label":"Decide the order from a data set","short":"Order","kind":"calc"},{"id":"infusion","label":"Infusion rate and steady state","short":"Infusion","kind":"calc"},{"id":"multidose","label":"Repeated dosing — peak, trough, average","short":"Multi-dose","kind":"calc"},{"id":"bioavail","label":"Bioavailability — absolute, relative, equivalent dose","short":"Bioavail","kind":"calc"},{"id":"pkpd","label":"PK-PD — effect, Emax, EC50 and exposure targets","short":"PK-PD","kind":"calc"}],"exams":[{"id":1,"name":"Exam 1","date":"2026-09-11","when":"2026-09-11T10:00","questions":40,"minutes":120,"sata":4,"blurb":"Fri 11 September. Modules 1–3: kinetic orders and the maths, one- and multi-compartment IV bolus, IV infusion. Half the paper is calculation. The mark split across the three modules is not published — this drill weights it by lecture time (2 : 2 : 1).","facts":[["When","Fri 11 September, 10:00–12:00"],["Covers","Modules 1–3: kinetic orders and the maths; one- and multi-compartment IV bolus; IV infusion"],["Shape","Half the paper is calculation"],["Mark split","Not published; this drill weights the three modules by lecture time, 2 : 2 : 1"]],"pools":[{"key":"m1","name":"Module 1 — Intro, kinetic orders, AUC","marks":16,"filter":{"module":1}},{"key":"m2","name":"Module 2 — IV bolus, one and multi-compartment","marks":16,"filter":{"module":2}},{"key":"m3","name":"Module 3 — IV infusion","marks":8,"filter":{"module":3}}]},{"id":2,"name":"Exam 2","date":"2026-10-08","when":"2026-10-08T07:50","questions":40,"minutes":120,"sata":4,"blurb":"Thu 8 October, 7:50–9:50. Modules 4–7a are lectured: elimination and clearance, single oral dosing, multiple dosing (repeated IV bolus, intermittent IV infusions, multiple oral doses), and bioavailability and bioequivalence. She said on 30 September that this exam is cumulative in the sense that multiple-dose problems need the single-dose skills. The per-module mark split is not published; this drill weights it by lecture time.","facts":[["When","Thu 8 October, 7:50–9:50"],["Covers","Modules 4–7a: elimination and clearance; single oral dosing; multiple dosing (repeated IV bolus, intermittent IV infusions, multiple oral doses); bioavailability and bioequivalence"],["Cumulative","In the sense she gave on 30 September: a multiple-dose problem needs the single-dose skills"],["Mark split","Not published; this drill weights the modules by lecture time"]],"pools":[{"key":"m4","name":"Module 4 — Elimination, clearance, renal clearance","marks":7,"filter":{"module":4}},{"key":"m5","name":"Module 5 — Oral absorption, single dose","marks":7,"filter":{"module":5}},{"key":"m6","name":"Module 6 — Multiple dosing: IV bolus, intermittent infusion, oral","marks":20,"filter":{"module":6}},{"key":"m7","name":"Module 7a — Bioavailability and bioequivalence","marks":6,"filter":{"module":7}}]},{"id":3,"name":"Exam 3 (final)","date":"2026-10-27","when":"2026-10-27T08:00","questions":40,"minutes":120,"sata":4,"blurb":"Tue 27 October, 8:00 a.m. Cumulative: 40 questions, 20 multiple choice and 20 fill in the blank, with 25% on the two lectures after Exam 2, PK-PD (12 Oct) and nonlinear pharmacokinetics (14 Oct). Know total clearance, ideal body weight and Cockcroft-Gault without the equation sheet. How the other 30 questions divide between Exam 1 and Exam 2 material is not published; this drill splits them evenly.","facts":[["When","Tue 27 October, starting at 8:00 a.m. (her announcement of 26 October)"],["After it","Exam review: Thu 29 October, 8:15 to 8:45 a.m., in the P2 classroom"],["Not on the sheet","Total clearance, ideal body weight and Cockcroft-Gault: \"we're only gonna use the ideal body weight\""],["What she expects","Zero and first order; k, t½, VD and Cp; total, renal and hepatic clearance; steady-state peaks, troughs, averages and tmax; Cp against time for each route; bioavailability; linear and nonlinear; AUC; duration of action and the times to steady state, to the peak and to elimination; Cp after IV bolus, IV infusion and extravascular doses"],["Weight","33% of the course grade"],["Shape","40 questions, \"similar in format to the two previous exams\": 20 multiple choice and 20 fill in the blank"],["New material","25%, 10 of the 40 questions, \"material that you have not been tested on before\": PK-PD (12 Oct) and nonlinear pharmacokinetics (14 Oct). On 14 Oct: \"25% new stuff, but the new isn't even really new\""],["The rest","Cumulative: Modules 1 to 7a. The split between Exam 1 and Exam 2 material is not published; this drill uses 15 and 15"]],"pools":[{"key":"f-e1","name":"Exam 1 material (Modules 1–3)","marks":15,"filter":{"exam":1}},{"key":"f-e2","name":"Exam 2 material (Modules 4–7a)","marks":15,"filter":{"exam":2}},{"key":"f-pkpd","name":"Module 7b — PK-PD relationship","marks":5,"filter":{"module":9}},{"key":"f-nl","name":"Module 8 — Nonlinear pharmacokinetics","marks":5,"filter":{"module":8}}]}],"activeExam":3,"images":{"oral_peak":"data:image/svg+xml;base64,","oral_semilog":"data:image/svg+xml;base64,","ord_semilog_curve":"data:image/svg+xml;base64,","ord_semilog_straight":"data:image/svg+xml;base64,","slide_6RepetitiveIVBolus_p17":"data:image/webp;base64,","slide_Introduction_p20":"data:image/webp;base64,","slide_Introduction_p23":"data:image/webp;base64,","slide_Introduction_p24":"data:image/webp;base64,","slide_Introduction_p6":"data:image/webp;base64,"}};
const FILE = 'q90_paper_picker_pk.js';
function courseData(prof){
  if(typeof prof !== 'string' || !prof || /['\\\n]/.test(prof)) throw new Error('the professor cannot be written as a literal');
  const lit = s => { if(!/^[A-Za-z0-9_. -]+$/.test(String(s))) throw new Error('cannot be written as a literal: ' + s); return "'" + s + "'"; };
  const rest = (o, drop) => { const c = Object.assign({}, o); drop.forEach(k => { delete c[k]; }); c.prof = prof; return JSON.stringify(c).slice(1); };
  const qline = q => '{id:' + lit(q.id) + ',' + (q.dupOf ? ' dupOf:' + lit(q.dupOf) + ',' : '') + ' skill:' + lit(q.skill) + ', prof:' + lit(prof) + ', ' +
    JSON.stringify((() => { const c = Object.assign({}, q); delete c.id; delete c.dupOf; delete c.skill; return c; })()).slice(1) + ',';
  const text = '/* paper-picker test data: Basic-Pharmacokinetics\' own topics and questions (ac2eb73), as\n' +
    '   features/paper-picker/current/test_fixture.js names them; the professor set to the course\'s own */\n' +
    'TOPICS.push(\n' + PK.topics.map(t => JSON.stringify(Object.assign({}, t, {prof}))).join(',\n') + ');\n' +
    'QUESTIONS.push(\n' + PK.qs.map(qline).join('\n') + '\n);\n';
  const lecture = l => '{id:' + lit('pp-' + l.id) + ', ' + rest(l, ['id']);
  const courseLine = 'COURSE.lectures = (COURSE.lectures || []).concat([' + PK.lectures.map(lecture).join(', ') + ']); ' +
    'COURSE.skills = (COURSE.skills || []).concat(' + JSON.stringify(PK.skills) + '.filter(s => !(COURSE.skills || []).some(k => k.id === s.id))); ' +
    'COURSE.exams = ' + JSON.stringify(PK.exams) + '; COURSE.activeExam = ' + JSON.stringify(PK.activeExam) + ';';
  return {files: {[FILE]: text}, courseLine, images: PK.images};
}
/* The course's images.json with the fixture's images added (an image the course already
   has under the same key stops it: nothing of the course is overwritten). */
function withImages(json){
  const have = JSON.parse(json || '{}');
  for(const [k, v] of Object.entries(PK.images)){
    if(k in have && have[k] !== v) throw new Error('images.json already has another image under ' + k);
    have[k] = v;
  }
  return JSON.stringify(have, null, 1) + '\n';
}
module.exports = {PK, FILE, courseData, withImages};
